window.QUESTIONS=[{"id":"B1.1","lv":"CCNA","t":"מבוא לרשתות","q":"איזה התקן מחבר בין רשתות שונות ומעביר חבילות לפי כתובת IP?","c":"נתב (Router)","w":["מתג (Switch)","רכזת (Hub)","נקודת גישה (AP)"],"e":"הנתב עובד בשכבה 3, ומחבר בין רשתות שונות לפי כתובות IP וטבלת הניתוב. המתג וה־AP מחברים מארחים בתוך אותו LAN לפי MAC, והרכזת רק משכפלת ביטים."},{"id":"B1.2","lv":"CCNA","t":"מבוא לרשתות","q":"כמה קישורים נדרשים לחיבור 6 נתבים בטופולוגיית Full Mesh?","c":"15","w":["30","12","6"],"e":"לפי הנוסחה n(n-1)/2 מקבלים 6×5/2 = 15. התשובה 30 היא n(n-1) בלי חלוקה ב־2, ולכן סופרת כל קישור פעמיים."},{"id":"B1.3","lv":"CCNA","t":"מבוא לרשתות","q":"מה מתאר בצורה הטובה ביותר את המונח Host?","c":"כל התקן קצה שמשתתף בתקשורת – לקוח או שרת","w":["כל כבל ברשת","רק מתגים ונתבים","רק שרתים שנותנים שירות"],"e":"Host הוא כל התקן קצה שיש לו כתובת ושמשמש מקור או יעד לתקשורת. זה כולל לקוחות וגם שרתים. מתגים ונתבים הם התקני תשתית."},{"id":"B2.1","lv":"CCNA","t":"מודלי OSI ו־TCP/IP","q":"איזו יחידת מידע (PDU) נוצרת בשכבת ה־Network?","c":"Packet","w":["Bits","Frame","Segment"],"e":"בשכבה 3 מוסיפים כותרת IP, ונוצרת Packet. Segment נוצר בשכבה 4, Frame בשכבה 2, ו־Bits בשכבה 1."},{"id":"B2.2","lv":"CCNA","t":"מודלי OSI ו־TCP/IP","q":"לקוח גולש לשרת Web. איזה פורט מקור יופיע בדרך כלל בבקשה?","c":"פורט אקראי מהטווח הדינמי, למשל 57101","w":["80","443","23"],"e":"הלקוח בוחר פורט מקור אקראי (Ephemeral), ופורט היעד הוא הפורט המוכר של השירות – 80 או 443. 23 הוא Telnet."},{"id":"B2.3","lv":"CCNA","t":"מודלי OSI ו־TCP/IP","q":"איזה מהפרוטוקולים הבאים משתמש בעיקר ב־UDP?","c":"DHCP","w":["HTTP","SSH","FTP"],"e":"DHCP משתמש ב־UDP בפורטים 67 (שרת) ו־68 (לקוח). SSH, HTTP ו־FTP משתמשים ב־TCP, כי הם צריכים אמינות."},{"id":"B2.4","lv":"CCNA","t":"מודלי OSI ו־TCP/IP","q":"איזה התקן מסיר את כותרת ה־Ethernet ובונה כותרת חדשה בכל קפיצה?","c":"Router","w":["Hub","Switch","Access Point"],"e":"הנתב פותח את החבילה עד שכבה 3, מחליט לאן להעביר אותה, ועוטף אותה במסגרת Ethernet חדשה עם כתובות MAC של הקטע הבא. המתג מעביר את המסגרת בלי לשנות את כתובות ה־MAC."},{"id":"B3.1","lv":"CCNA","t":"שכבה פיזית וכבלים","q":"מה המרחק המרבי לכבל UTP בתקן 1000BASE-T?","c":"100 מטר","w":["2 קילומטר","185 מטר","55 מטר"],"e":"כל תקני Ethernet הנפוצים על UTP מוגבלים ל־100 מטר. 55 מטר הוא המגבלה של 10 Gbps על Cat 6, ו־185 מטר הוא תקן Coax ישן."},{"id":"B3.2","lv":"CCNA","t":"שכבה פיזית וכבלים","q":"איזה כבל נדרש לחיבור בין שני מתגים ישנים שאין בהם Auto-MDIX?","c":"Crossover","w":["Rollover","Straight-Through","Serial DCE"],"e":"שני מתגים משדרים באותם פינים (3,6), ולכן צריך כבל מוצלב. כבל ישר מתאים להתקנים מסוגים שונים, ו־Rollover הוא כבל קונסולה."},{"id":"B3.3","lv":"CCNA","t":"שכבה פיזית וכבלים","q":"בצד אחד של קישור הוגדר duplex full ידנית, והצד השני נשאר auto. מה יקרה?","c":"הצד שנשאר auto ייפול ל־Half-Duplex, ויופיעו שגיאות והתנגשויות","w":["הקישור לא יעלה בכלל","המהירות תרד ל־10 Mbps בלבד","שני הצדדים יעבדו ב־Full-Duplex"],"e":"הצד הידני לא משתתף במשא ומתן, ולכן הצד שנשאר auto מניח Half-Duplex. מקבלים Duplex Mismatch: הקישור עולה, אבל איטי ומלא ב־late collisions ושגיאות CRC."},{"id":"B3.4","lv":"CCNA","t":"שכבה פיזית וכבלים","q":"מה היתרון העיקרי של סיב Single-mode על פני Multimode?","c":"מגיע למרחקים ארוכים בהרבה","w":["משתמש ב־LED","מעביר חשמל (PoE)","זול יותר"],"e":"לסיב Single-mode יש ליבה צרה מאוד (9 מיקרון) ומקור לייזר, ולכן הוא מגיע לעשרות קילומטרים. הוא דווקא יקר יותר, ה־LED שייך ל־Multimode, וסיבים לא מעבירים חשמל."},{"id":"B4.1","lv":"CCNA","t":"Ethernet ו־MAC","q":"מה תפקיד השדה FCS במסגרת Ethernet?","c":"לזהות שגיאות במסגרת באמצעות CRC","w":["לסנכרן את השעון של המקבל","לזהות את פרוטוקול שכבה 3","לשמור את כתובת היעד"],"e":"ה־FCS מכיל ערך CRC. המקבל מחשב אותו מחדש, ואם יש אי־התאמה הוא זורק את המסגרת. הזיהוי של פרוטוקול שכבה 3 הוא תפקיד ה־Type, והסנכרון הוא תפקיד ה־Preamble."},{"id":"B4.2","lv":"CCNA","t":"Ethernet ו־MAC","q":"מה הערך של שדה EtherType כשהמסגרת נושאת הודעת ARP?","c":"0x0806","w":["0x8100","0x86DD","0x0800"],"e":"0x0806 מציין ARP. 0x0800 הוא IPv4, 0x86DD הוא IPv6, ו־0x8100 מסמן תג VLAN של 802.1Q."},{"id":"B4.3","lv":"CCNA","t":"Ethernet ו־MAC","q":"מה מייצגים 24 הביטים הראשונים של כתובת MAC?","c":"ה־OUI – המזהה של היצרן","w":["ה־VLAN של ההתקן","מספר הפורט במתג","כתובת ה־IP בפורמט בינארי"],"e":"3 הבתים הראשונים הם ה־OUI, שה־IEEE הקצה ליצרן. 3 הבתים האחרונים הם מספר ייחודי שהיצרן נתן לכרטיס."},{"id":"B4.4","lv":"CCNA","t":"Ethernet ו־MAC","q":"מה גודל המסגרת המינימלי ב־Ethernet (לא כולל Preamble)?","c":"64 בתים","w":["1518 בתים","46 בתים","1500 בתים"],"e":"מסגרת מינימלית היא 64 בתים: 14 בתי כותרת, 46 בתי Payload ו־4 בתי FCS. 46 הוא המינימום של ה־Payload בלבד, ו־1518 הוא הגודל המרבי."},{"id":"B5.1","lv":"CCNA","t":"מיתוג Ethernet","q":"על פי איזו כתובת מתג **לומד** ומעדכן את טבלת ה־MAC?","c":"MAC המקור","w":["IP המקור","MAC היעד","IP היעד"],"e":"המתג לומד מכתובת ה־MAC של המקור – הוא רושם מאיזה פורט היא הגיעה. את כתובת היעד הוא בודק כדי להחליט לאן להעביר, אבל לא לומד ממנה."},{"id":"B5.2","lv":"CCNA","t":"מיתוג Ethernet","q":"מסגרת מגיעה למתג, וכתובת היעד שלה (Unicast) לא קיימת בטבלה. מה יעשה המתג?","c":"יציף אותה לכל הפורטים באותו VLAN, חוץ מפורט המקור","w":["ישלח ARP כדי לברר מי היעד","ישלח אותה רק לנתב","יזרוק את המסגרת"],"e":"זה Unknown Unicast, והמתג מבצע Flooding. כשהיעד יענה, המתג ילמד את הכתובת שלו. המתג לא משתמש ב־ARP כדי להעביר מסגרות."},{"id":"B5.3","lv":"CCNA","t":"מיתוג Ethernet","q":"מהו זמן ההתיישנות (Aging Time) של רשומה דינמית בטבלת MAC במתג Cisco, כברירת מחדל?","c":"300 שניות","w":["4 שעות","30 שניות","120 שניות"],"e":"ברירת המחדל היא 300 שניות (5 דקות). 4 שעות הוא זמן ההתיישנות של טבלת ה־ARP בנתבי Cisco – לא להתבלבל."},{"id":"B5.4","lv":"CCNA","t":"מיתוג Ethernet","q":"איזו שיטת העברה בודקת את ה־FCS לפני שהיא מעבירה את המסגרת?","c":"Store-and-Forward","w":["Fragment-Free","Cut-Through","Flooding"],"e":"ב־Store-and-Forward המתג קולט את כל המסגרת ובודק את ה־CRC, ולכן לא מעביר מסגרות פגומות. Cut-Through מעביר מיד אחרי MAC היעד, ו־Fragment-Free בודק רק את 64 הבתים הראשונים."},{"id":"B6.1","lv":"CCNA","t":"ARP","q":"איך נשלחת בקשת ARP (ARP Request)?","c":"Broadcast לכתובת FF:FF:FF:FF:FF:FF","w":["Multicast לכתובת 01:00:5E:00:00:05","Unicast ל־Default Gateway","Unicast לשרת DNS"],"e":"השולח עדיין לא יודע את ה־MAC של היעד, ולכן שואל את כולם ב־Broadcast. התשובה (Reply) נשלחת ב־Unicast."},{"id":"B6.2","lv":"CCNA","t":"ARP","q":"PC-1 (192.168.1.1/24) שולח חבילה ל־192.168.2.5. מהי כתובת ה־MAC של היעד במסגרת שיוצאת מ־PC-1?","c":"ה־MAC של ה־Default Gateway","w":["ה־MAC של 192.168.2.5","FF:FF:FF:FF:FF:FF","ה־MAC של המתג"],"e":"היעד ברשת אחרת, ולכן המסגרת נשלחת לנתב. כתובת ה־IP של היעד נשארת 192.168.2.5, אבל ה־MAC של היעד הוא של ה־Default Gateway. המתג שקוף ולא מופיע בכתובות."},{"id":"B6.3","lv":"CCNA","t":"ARP","q":"מה מציין הערך Opcode = 2 בהודעת ARP?","c":"ARP Reply","w":["RARP Request","ARP Request","Gratuitous ARP"],"e":"Opcode 1 הוא Request ו־Opcode 2 הוא Reply. Gratuitous ARP הוא בדרך כלל Request או Reply שבו כתובות ה־IP של השולח ושל היעד זהות."},{"id":"B6.4","lv":"CCNA","t":"ARP","q":"איזה מנגנון במתגי Cisco מגן מפני ARP Spoofing?","c":"Dynamic ARP Inspection","w":["PortFast","Port Security","BPDU Guard"],"e":"DAI בודק כל הודעת ARP בפורטים לא מהימנים מול טבלת ה־DHCP Snooping, וזורק הודעות מזויפות. Port Security מגביל כתובות MAC, BPDU Guard מגן על STP, ו־PortFast מאיץ עליית פורט."},{"id":"B7.1","lv":"CCNA","t":"Cisco IOS","q":"מהן הגדרות ברירת המחדל של חיבור קונסולה לציוד Cisco?","c":"9600, 8, None, 1","w":["115200, 8, Even, 1","9600, 7, Odd, 2","19200, 8, None, 1"],"e":"ברירת המחדל היא 9600 baud, 8 ביטי נתונים, ללא Parity, וביט עצירה אחד (9600 8N1), ללא Flow Control."},{"id":"B7.2","lv":"CCNA","t":"Cisco IOS","q":"מנהל רשת הגדיר ממשקים והפעיל מחדש את הנתב (reload), ומגלה שכל ההגדרות נעלמו. מה הסיבה הסבירה ביותר?","c":"הוא לא הריץ copy running-config startup-config","w":["ה־IOS נמחק מה־Flash","הוא לא הריץ no shutdown","ה־NVRAM פגום"],"e":"ההגדרות נשמרות ב־running-config שב־RAM, שנמחק בכיבוי. בלי שמירה ל־startup-config ב־NVRAM, הן אובדות."},{"id":"B7.3","lv":"CCNA","t":"Cisco IOS","q":"באיזו פקודה מריצים show running-config מתוך מצב Global Configuration?","c":"do show running-config","w":["show running-config","exec show running-config","run show running-config"],"e":"הקידומת do מאפשרת להריץ פקודות EXEC מתוך מצבי Config. בלעדיה תתקבל השגיאה Invalid input."},{"id":"B7.4","lv":"CCNA","t":"Cisco IOS","q":"איזה זיכרון מכיל את קובץ ה־IOS?","c":"Flash","w":["ROM","RAM","NVRAM"],"e":"קובץ ה־IOS נשמר ב־Flash. ה־NVRAM מכיל את ה־startup-config, ה־RAM מכיל את ה־running-config, וה־ROM מכיל את ה־Bootstrap ואת ה־ROMMON."},{"id":"B8.1","lv":"CCNA","t":"IPv4","q":"מהי כתובת הרשת של המארח 192.168.10.77/24?","c":"192.168.10.0","w":["192.168.0.0","192.168.10.255","192.168.10.1"],"e":"ב־/24 שלושת האוקטטים הראשונים הם רשת. איפוס האוקטט האחרון נותן 192.168.10.0. הכתובת 192.168.10.255 היא ה־Broadcast."},{"id":"B8.2","lv":"CCNA","t":"IPv4","q":"מה הערך הבינארי של המספר 224?","c":"11100000","w":["10100000","11110000","11000000"],"e":"128+64+32 = 224, ולכן שלושת הביטים השמאליים דולקים: 11100000. 11000000 הוא 192, ו־11110000 הוא 240."},{"id":"B8.3","lv":"CCNA","t":"IPv4","q":"איזו מהכתובות הבאות היא כתובת פרטית?","c":"172.20.5.5","w":["192.169.1.1","172.32.1.1","11.0.0.1"],"e":"הטווח הפרטי של מחלקה B הוא 172.16.0.0 עד 172.31.255.255, ולכן 172.20.5.5 פרטית. 172.32 כבר מחוץ לטווח, 192.169 אינה 192.168, ו־11.x אינה 10.x."},{"id":"B8.4","lv":"CCNA","t":"IPv4","q":"מה מאפשר שדה ה־TTL בכותרת IPv4?","c":"למנוע מחבילות להסתובב בלולאה לנצח","w":["לסמן עדיפות QoS","לזהות את פרוטוקול שכבה 4","לפצל חבילות גדולות"],"e":"כל נתב מוריד את ה־TTL ב־1, וכשהוא מגיע ל־0 החבילה נזרקת. Protocol מזהה את שכבה 4, DSCP מסמן QoS, ו־Flags/Offset מטפלים בפיצול."},{"id":"B8.5","lv":"CCNA","t":"IPv4","q":"מחשב קיבל את הכתובת 169.254.33.10. מה המשמעות?","c":"הוא לא קיבל תשובה מ־DHCP והקצה לעצמו כתובת APIPA","w":["הוא קיבל כתובת תקינה משרת DHCP","זו כתובת Multicast","זו כתובת Loopback"],"e":"169.254.0.0/16 הוא טווח APIPA. מחשב מקצה לעצמו כתובת מהטווח הזה כשאין תשובה מ־DHCP. זה סימן לבעיית קישוריות או לבעיה בשרת."},{"id":"B9.1","lv":"CCNA","t":"Subnetting ו־VLSM","q":"כמה מארחים שמישים יש ברשת ‎/27?","c":"30","w":["14","32","62"],"e":"ב־‎/27 נשארים 5 ביטי מארח: 2<sup>5</sup> − 2 = 30. ‏32 הוא גודל הבלוק כולל כתובת הרשת וה־Broadcast."},{"id":"B9.2","lv":"CCNA","t":"Subnetting ו־VLSM","q":"לאיזו רשת שייכת הכתובת 10.10.37.200/21?","c":"10.10.32.0","w":["10.10.37.0","10.10.40.0","10.10.36.0"],"e":"‎/21 → המסכה 255.255.248.0, וגודל הבלוק באוקטט השלישי הוא 8. הכפולות של 8: ‏32, 40. ‏37 נמצא בין 32 ל־40, ולכן הרשת היא 10.10.32.0."},{"id":"B9.3","lv":"CCNA","t":"Subnetting ו־VLSM","q":"מה המסכה המתאימה ביותר לקישור נקודה לנקודה בין שני נתבים (בלי ‎/31)?","c":"255.255.255.252","w":["255.255.255.240","255.255.255.0","255.255.255.248"],"e":"‎/30 (‏255.255.255.252) נותן בדיוק 2 כתובות שמישות, אחת לכל נתב. האחרות מבזבזות כתובות."},{"id":"B9.4","lv":"CCNA","t":"Subnetting ו־VLSM","q":"רשת 192.1.2.0/24 חולקה ל־8 תתי־רשתות שוות. מהי כתובת ה־Broadcast של תת־הרשת השלישית?","c":"192.1.2.95","w":["192.1.2.127","192.1.2.96","192.1.2.63"],"e":"גודל הבלוק הוא 32. תתי־הרשתות מתחילות ב־`.0`, `.32`, `.64`, `.96`. השלישית היא `.64`, וה־Broadcast שלה הוא `.96 − 1 = .95`."},{"id":"B9.5","lv":"CCNA","t":"Subnetting ו־VLSM","q":"מהו הנתיב המסכם של 10.1.4.0/24, ‏10.1.5.0/24, ‏10.1.6.0/24 ו־10.1.7.0/24?","c":"10.1.4.0/22","w":["10.1.4.0/23","10.1.4.0/21","10.1.0.0/16"],"e":"4 עד 7 בבינארי: 000001|00 עד 000001|11. שישה ביטים משותפים באוקטט השלישי, ועוד 16 ביטים קודמים, נותנים ‎/22. ‏‎/23 מכסה רק את 4–5, ו־‎/21 מכסה גם את 0–3."},{"id":"B10.1","lv":"CCNA","t":"העברת חבילות","q":"מחשב 192.168.1.10/24 עם Gateway ‏192.168.1.1 שולח חבילה ל־8.8.8.8. על איזו כתובת IP הוא שולח ARP Request?","c":"192.168.1.1","w":["255.255.255.255","8.8.8.8","192.168.1.255"],"e":"היעד מרוחק, ולכן המחשב צריך את ה־MAC של ה־Default Gateway – זו הכתובת שעליה הוא שואל. הוא לא יכול לגלות ב־ARP את ה־MAC של 8.8.8.8."},{"id":"B10.2","lv":"CCNA","t":"העברת חבילות","q":"בטבלת הניתוב יש את הנתיבים 172.16.0.0/16, ‏172.16.4.0/22 ו־172.16.4.0/24. לפי איזה נתיב תועבר חבילה ל־172.16.5.9?","c":"172.16.4.0/22","w":["החבילה תיזרק","172.16.0.0/16","172.16.4.0/24"],"e":"‎172.16.5.9 לא בתוך ‎/24 (שמכסה רק 4.x), אבל כן בתוך ‎/22 (שמכסה 4.0 עד 7.255). ‏‎/22 ספציפי יותר מ־‎/16, ולכן הוא נבחר – Longest Prefix Match."},{"id":"B10.3","lv":"CCNA","t":"העברת חבילות","q":"מה עושה נתב לחבילה בזמן שהוא מעביר אותה?","c":"מוריד את ה־TTL ב־1 ובונה כותרת Ethernet חדשה","w":["משנה את כתובת ה־IP של היעד","משאיר את כותרת ה־Ethernet כמו שהיא","משנה את פורט ה־TCP"],"e":"הנתב מוריד את ה־TTL, מחשב מחדש את ה־Checksum, ועוטף את החבילה במסגרת חדשה עם כתובות MAC של הקטע הבא. כתובות ה־IP והפורטים לא משתנים (בלי NAT)."},{"id":"B10.4","lv":"CCNA","t":"העברת חבילות","q":"מה מייצג קוד L בטבלת הניתוב?","c":"כתובת ה־IP של ממשק הנתב עצמו, כ־‎/32","w":["נתיב שנלמד מנתב שכן","נתיב שנלמד מ־LDP","נתיב ברירת מחדל"],"e":"L (Local) הוא נתיב מארח (‎/32) לכתובת שהוגדרה על ממשק הנתב. הוא מאפשר לנתב לזהות חבילות שמיועדות אליו עצמו."},{"id":"B11.1","lv":"CCNA","t":"Telnet ו־SVI","q":"הוגדר password cisco תחת line vty 0 15, אבל המשתמשים מתחברים בלי שמתבקשת מהם סיסמה. מה חסר?","c":"הפקודה login","w":["ip default-gateway","enable secret","transport input ssh"],"e":"הפקודה login היא שמפעילה את בדיקת הסיסמה בקו. בלעדיה הסיסמה מוגדרת אבל לא נבדקת. בציוד אמיתי, בלי login וגם בלי סיסמה, החיבור נדחה."},{"id":"B11.2","lv":"CCNA","t":"Telnet ו־SVI","q":"איזה ממשק מגדירים כדי לתת כתובת IP לניהול של מתג שכבה 2?","c":"interface vlan 99","w":["interface loopback 0","interface port-channel 1","interface gigabitEthernet 0/1"],"e":"SVI (‏interface vlan X) הוא הממשק הלוגי שמחזיק את כתובת הניהול של מתג שכבה 2. פורטים פיזיים במתג שכבה 2 לא מקבלים כתובת IP."},{"id":"B11.3","lv":"CCNA","t":"Telnet ו־SVI","q":"מנהל מצליח לעשות Telnet למתג מאותה רשת, אבל לא מרשת אחרת. מה כנראה חסר במתג?","c":"ip default-gateway","w":["no shutdown על ה־SVI","login local","ip routing"],"e":"מאותה רשת החיבור עובד, ולכן ה־SVI והסיסמאות תקינים. כדי לענות לרשת אחרת, המתג צריך Default Gateway. הפקודה ip routing שייכת למתגי שכבה 3."},{"id":"B11.4","lv":"CCNA","t":"Telnet ו־SVI","q":"מה עושה הפקודה login local תחת line vty?","c":"מאמתת לפי שם משתמש וסיסמה שהוגדרו בפקודה username","w":["מאמתת מול שרת RADIUS","מבטלת את הצורך בסיסמה","מאפשרת גישה רק מהקונסולה"],"e":"login local בודק את פרטי ההתחברות מול מסד המשתמשים המקומי. אימות מול RADIUS דורש AAA (פרק 31)."},{"id":"B12.1","lv":"CCNA","t":"ניתוב סטטי","q":"מה המרחק המנהלי (AD) של נתיב סטטי, כברירת מחדל?","c":"1","w":["90","110","0"],"e":"לנתיב סטטי יש AD של 1. ל־Connected יש 0, ל־EIGRP יש 90, ול־OSPF יש 110."},{"id":"B12.2","lv":"CCNA","t":"ניתוב סטטי","q":"איזו פקודה מגדירה נתיב צף שמגבה נתיב ברירת מחדל ראשי עם AD של 1?","c":"ip route 0.0.0.0 0.0.0.0 172.16.224.2 5","w":["ip route 0.0.0.0 0.0.0.0 172.16.224.2 1","ip route 0.0.0.0 255.255.255.255 172.16.224.2","ip default-gateway 172.16.224.2"],"e":"נתיב צף צריך AD גבוה יותר מזה של הנתיב הראשי, כדי שייכנס לטבלה רק כשהראשי נופל. עם AD 1 שני הנתיבים יהיו שווים ויחלקו עומס. ip default-gateway שייכת למתג שכבה 2."},{"id":"B12.3","lv":"CCNA","t":"ניתוב סטטי","q":"מה מציין הסימן S* בטבלת הניתוב?","c":"נתיב סטטי שהוא מועמד לנתיב ברירת מחדל","w":["נתיב סטטי שאינו פעיל","נתיב סיכום","נתיב שנלמד ב־RIP"],"e":"S הוא Static, וה־* מציין Candidate Default – בדרך כלל זה הנתיב ‎0.0.0.0/0."},{"id":"B12.4","lv":"CCNA","t":"ניתוב סטטי","q":"Router-1 מגיע ל־Router-3, אבל ping מ־LAN-1 ל־LAN-3 נכשל, ו־traceroute מראה שהחבילה מגיעה ל־Router-3. מה הסיבה הסבירה ביותר?","c":"ל־Router-3 או ל־Router-2 אין נתיב חזרה ל־LAN-1","w":["הממשק ב־Router-1 כבוי","ה־AD שגוי","ל־Router-1 אין נתיב ל־LAN-3"],"e":"אם החבילה מגיעה ל־Router-3, הדרך הלוך תקינה. התשובה לא חוזרת, ולכן חסר נתיב חזרה. ping דורש ניתוב בשני הכיוונים."},{"id":"B13.1","lv":"CCNA","t":"VLAN","q":"מה המשמעות של כך ששני מחשבים נמצאים ב־VLANים שונים על אותו מתג?","c":"הם נמצאים בתחומי שידור שונים, וצריך התקן שכבה 3 כדי שיתקשרו","w":["הם יכולים לתקשר ישירות דרך המתג","הם חולקים את אותה טבלת MAC","אחד מהם יקבל err-disabled"],"e":"כל VLAN הוא תחום שידור נפרד. בלי נתב או מתג שכבה 3 אין ביניהם תקשורת, גם אם הם על אותו מתג פיזי."},{"id":"B13.2","lv":"CCNA","t":"VLAN","q":"מנהל הריץ erase startup-config ו־reload, אבל ה־VLANים עדיין קיימים. למה?","c":"ה־VLANים נשמרים בקובץ vlan.dat ב־Flash","w":["reload לא מוחק דבר","ה־VLANים נשמרים ב־ROM","ה־VLANים נשמרים ב־NVRAM"],"e":"VLANים בטווח הרגיל נשמרים ב־flash:vlan.dat. כדי למחוק אותם צריך delete flash:vlan.dat."},{"id":"B13.3","lv":"CCNA","t":"VLAN","q":"מה קורה לפורטים של VLAN 20 אחרי no vlan 20?","c":"הם נשארים מוקצים ל־VLAN 20 שלא קיים, ולכן לא פעילים","w":["הם נכבים במצב err-disabled","הם עוברים אוטומטית ל־VLAN 1","הם הופכים ל־Trunk"],"e":"הפורטים נשארים עם ההגדרה switchport access vlan 20. כיוון שה־VLAN לא קיים, הם לא מעבירים תעבורה עד שמקצים אותם מחדש."},{"id":"B13.4","lv":"CCNA","t":"VLAN","q":"איזה טווח VLAN נשמר ב־vlan.dat ומופץ על ידי VTP גרסה 1/2?","c":"1–1005","w":["1006–4094","1–4094","רק VLAN 1"],"e":"Normal Range (‏1–1005) נשמר ב־vlan.dat ומופץ ב־VTP v1/v2. Extended Range (‏1006–4094) נשמר ב־running-config, ונתמך ב־VTP רק מגרסה 3."},{"id":"B14.1","lv":"CCNA","t":"Trunk ו־DTP","q":"כמה בתים מוסיף תג 802.1Q למסגרת Ethernet?","c":"4","w":["26","2","30"],"e":"תג 802.1Q הוא 4 בתים: ‏TPID (2), ‏PCP+DEI+VID (2). ‏ISL הוא זה שמוסיף 26+4 בתים."},{"id":"B14.2","lv":"CCNA","t":"Trunk ו־DTP","q":"מה קורה למסגרות של ה־Native VLAN בקישור Trunk מסוג 802.1Q?","c":"הן נשלחות בלי תג","w":["הן מוצפנות","הן מתויגות בתג כפול","הן נזרקות"],"e":"מסגרות של ה־Native VLAN עוברות בלי תג, וכל מסגרת לא מתויגת שמגיעה ל־Trunk משויכת ל־Native VLAN – אלא אם הוגדר vlan dot1q tag native."},{"id":"B14.3","lv":"CCNA","t":"Trunk ו־DTP","q":"על Trunk פעיל הוגדרה הפקודה switchport trunk allowed vlan 30. מה התוצאה?","c":"רק VLAN 30 יעבור ב־Trunk, וכל השאר ייחסמו","w":["הפקודה תידחה","VLAN 30 ייחסם","VLAN 30 נוסף לרשימה הקיימת"],"e":"בלי המילה add, הפקודה מחליפה את כל הרשימה. כדי להוסיף, משתמשים ב־switchport trunk allowed vlan add 30."},{"id":"B14.4","lv":"CCNA","t":"Trunk ו־DTP","q":"שני מתגים מחוברים, ושני הפורטים במצב dynamic auto. מה יהיה מצב הקישור?","c":"Access","w":["err-disabled","הקישור לא יעלה","Trunk"],"e":"במצב Auto המתג פסיבי ומחכה שהצד השני ייזום. כששני הצדדים מחכים, אף אחד לא יוזם, והקישור נשאר Access."},{"id":"B14.5","lv":"CCNA","t":"Trunk ו־DTP","q":"מה ההגנה העיקרית מפני VLAN Hopping בשיטת Double Tagging?","c":"להעביר את ה־Native VLAN ל־VLAN שלא בשימוש, ו/או לתייג את ה־Native","w":["להפעיל CDP","להגדיל את ה־MTU","להפעיל PortFast"],"e":"המתקפה מנצלת את העובדה שהמתג מסיר את תג ה־Native. אם ה־Native הוא VLAN ריק, או שהוא מתויג, המתקפה לא עובדת."},{"id":"B15.1","lv":"CCNA","t":"ניתוב בין VLANים","q":"איזו פקודה מגדירה תת־ממשק בנתב כך שיטפל במסגרות של VLAN 30?","c":"encapsulation dot1Q 30","w":["ip vlan 30","switchport access vlan 30","vlan 30"],"e":"בתת־ממשק (למשל g0/0.30), הפקודה encapsulation dot1Q 30 קובעת שהוא מטפל במסגרות עם תג VLAN 30. switchport היא פקודה של מתג."},{"id":"B15.2","lv":"CCNA","t":"ניתוב בין VLANים","q":"הוגדרו SVIים ל־VLAN 10 ול־VLAN 20 במתג שכבה 3, שניהם up/up, אבל אין תקשורת בין ה־VLANים. מה חסר?","c":"ip routing","w":["no switchport","encapsulation dot1q","switchport mode trunk"],"e":"ip routing מפעיל את מנוע הניתוב במתג. בלעדיו ה־SVIים הם רק ממשקי ניהול, והמתג לא מעביר חבילות בין רשתות."},{"id":"B15.3","lv":"CCNA","t":"ניתוב בין VLANים","q":"מה עושה הפקודה no switchport בפורט של מתג שכבה 3?","c":"הופכת את הפורט לפורט מנותב (שכבה 3), שאפשר לתת לו כתובת IP","w":["מכבה את הפורט","מוחקת את ה־VLAN","הופכת את הפורט ל־Trunk"],"e":"no switchport מוציאה את הפורט מתפקוד שכבה 2. הוא מתנהג כמו ממשק של נתב, ומקבל כתובת IP ישירות."},{"id":"B15.4","lv":"CCNA","t":"ניתוב בין VLANים","q":"מה החיסרון העיקרי של Router-on-a-Stick?","c":"הקישור היחיד בין המתג לנתב הוא צוואר בקבוק, וכל חבילה בין VLANים עוברת בו פעמיים","w":["דורש מתג שכבה 3","לא תומך ב־802.1Q","דורש ממשק פיזי לכל VLAN"],"e":"ב־ROAS כל התעבורה בין VLANים עולה לנתב ויורדת חזרה באותו כבל. ממשק לכל VLAN הוא דווקא החיסרון של שיטת ה־Legacy."},{"id":"B16.1","lv":"CCNP","t":"VTP","q":"באיזה מצב VTP אי אפשר ליצור VLANים במתג?","c":"Client","w":["Server","Transparent","Off"],"e":"במצב Client המתג רק מקבל את מסד ה־VLANים מהשרת. ב־Transparent וב־Off אפשר ליצור VLANים מקומיים, וב־Server אפשר ליצור VLANים שמופצים לכל הדומיין."},{"id":"B16.2","lv":"CCNP","t":"VTP","q":"מתג מקבל פרסומת VTP עם אותו שם דומיין ואותה סיסמה. מתי הוא יעדכן את מסד ה־VLANים שלו?","c":"כשמספר הגרסה בפרסומת גבוה משלו","w":["כשמספר הגרסה נמוך משלו","תמיד","רק אם הוא במצב Transparent"],"e":"VTP מסתמך על Configuration Revision. מתג מחליף את המסד שלו רק אם המספר בפרסומת גבוה יותר. מתג Transparent בכלל לא מעדכן את המסד שלו לפי פרסומות."},{"id":"B16.3","lv":"CCNP","t":"VTP","q":"איזה מצב VTP מאפשר ליצור VLANים מקומיים, ועדיין מעביר פרסומות VTP הלאה (בגרסה 2)?","c":"Transparent","w":["Off","Server","Client"],"e":"Transparent מנהל VLANים מקומיים, לא מסתנכרן לפי אחרים, ומעביר פרסומות VTP לשכנים. מצב Off (‏v3) לא מעביר אותן."},{"id":"B16.4","lv":"CCNP","t":"VTP","q":"מה עושה VTP Pruning?","c":"מונע הצפה של תעבורת VLAN ב־Trunks שמובילים למתגים שאין בהם את ה־VLAN","w":["מצפין את הודעות VTP","מאפס את מספר הגרסה","מוחק VLANים לא בשימוש"],"e":"Pruning חוסך רוחב פס, כי Broadcast ו־Unknown Unicast של VLAN לא נשלחים למתגים שאין להם בו אף פורט פעיל. ה־VLANים עצמם לא נמחקים."},{"id":"B17.1","lv":"CCNA","t":"STP","q":"איך נבחר ה־Root Bridge ב־STP?","c":"המתג עם ה־Bridge ID הנמוך ביותר – קודם לפי Priority, ואחר כך לפי MAC","w":["המתג עם ה־IP הנמוך ביותר","המתג עם ה־Bridge ID הגבוה ביותר","המתג עם הכי הרבה פורטים"],"e":"Bridge ID נמוך מנצח. משווים קודם את ה־Priority, ובשוויון את כתובת ה־MAC. ל־IP אין שום תפקיד ב־STP."},{"id":"B17.2","lv":"CCNA","t":"STP","q":"מתג ב־VLAN 10 מוגדר עם עדיפות ברירת מחדל. איזה ערך Priority יוצג ב־show spanning-tree?","c":"32778","w":["10","32768","4096"],"e":"העדיפות המוצגת היא 32768 + VLAN ID (‏Extended System ID), כלומר 32768 + 10 = 32778."},{"id":"B17.3","lv":"CCNA","t":"STP","q":"כמה זמן לוקח לפורט ב־802.1D לעבור מ־Blocking ל־Forwarding אחרי תקלה עקיפה?","c":"50 שניות","w":["15 שניות","30 שניות","2 שניות"],"e":"בתקלה עקיפה מחכים Max Age ‏(20), ואחר כך Listening ‏(15) ו־Learning ‏(15), סך הכול 50 שניות. בתקלה ישירה מדלגים על Max Age, ולכן לוקח 30 שניות."},{"id":"B17.4","lv":"CCNA","t":"STP","q":"באיזה מצב פורט כבר לומד כתובות MAC, אבל עדיין לא מעביר נתונים?","c":"Learning","w":["Listening","Blocking","Forwarding"],"e":"במצב Learning הפורט ממלא את טבלת ה־MAC כדי להתכונן, אבל עוד לא מעביר נתונים. ב־Listening הוא רק משתתף בתהליך ה־BPDU."},{"id":"B17.5","lv":"CCNA","t":"STP","q":"מה עלות STP (Short) של פורט 1 Gbps?","c":"4","w":["100","2","19"],"e":"בשיטת Short: ‏10 Mbps = 100, ‏100 Mbps = 19, ‏1 Gbps = 4, ‏10 Gbps = 2."},{"id":"B18.1","lv":"CCNA","t":"RSTP ו־PVST+","q":"מה היתרון העיקרי של PVST+ על פני 802.1D הרגיל?","c":"אפשרות ל־Root נפרד לכל VLAN, וכך לחלוקת עומסים בין הקישורים","w":["שימוש בפחות CPU","התכנסות מתחת לשנייה","תקן פתוח של IEEE"],"e":"PVST+ מריץ מופע לכל VLAN, ולכן כל VLAN יכול לבחור Root ונתיב אחרים. הוא עדיין איטי (כמו 802.1D), צורך יותר CPU, והוא קנייני של Cisco."},{"id":"B18.2","lv":"CCNA","t":"RSTP ו־PVST+","q":"איזה תפקיד פורט ב־RSTP משמש כגיבוי מוכן ל־Root Port?","c":"Alternate","w":["Backup","Designated","Edge"],"e":"Alternate Port מספק דרך חלופית ל־Root, דרך מתג אחר, ועובר ל־Forwarding מיד כשה־RP נופל. Backup הוא גיבוי ל־Designated באותו מקטע."},{"id":"B18.3","lv":"CCNA","t":"RSTP ו־PVST+","q":"מה יקרה אם פורט עם PortFast ו־BPDU Guard יקבל BPDU?","c":"הפורט יעבור ל־err-disabled","w":["הפורט יעבור למצב Listening","ה־BPDU ייזרק, והפורט ימשיך לעבוד","הפורט יהפוך ל־Root Port"],"e":"BPDU Guard מכבה את הפורט (err-disabled) ברגע שמגיע BPDU, כי זה סימן שחובר מתג. מתעלם מ־BPDUs זה BPDU Filter."},{"id":"B18.4","lv":"CCNA","t":"RSTP ו־PVST+","q":"איזה ערך עדיפות יקבע המאקרו spanning-tree vlan 10 root primary, אם כל המתגים בברירת המחדל?","c":"24576","w":["28672","0","4096"],"e":"root primary קובע 24576, אם זה מספיק כדי לנצח את ה־Root הנוכחי. root secondary קובע 28672."},{"id":"B18.5","lv":"CCNP","t":"RSTP ו־PVST+","q":"מה מונע Root Guard?","c":"מתג בפורט מסוים מלהפוך ל־Root Bridge","w":["קבלת BPDU בפורט של מחשב","לולאות בגלל קישור חד־כיווני","Native VLAN Mismatch"],"e":"Root Guard חוסם פורט (root-inconsistent) כשמגיע בו Superior BPDU. קישור חד־כיווני מטופל ב־Loop Guard וב־UDLD, ו־BPDU בפורט של מחשב מטופל ב־BPDU Guard."},{"id":"B19.1","lv":"CCNP","t":"MST","q":"אילו שלושה פרמטרים חייבים להיות זהים כדי שמתגים יהיו באותו אזור MST?","c":"שם התצורה, מספר ה־Revision וטבלת המיפוי של VLANים למופעים","w":["כתובת IP, מסכה ו־Gateway","Hostname, ‏VTP Domain ו־Native VLAN","Bridge Priority, ‏Hello Timer ו־Max Age"],"e":"אזור MST מוגדר לפי Name, ‏Revision וטבלת המיפוי. הבדל באחד מהם יוצר אזור נפרד."},{"id":"B19.2","lv":"CCNP","t":"MST","q":"לאיזה מופע שייך VLAN שלא מופה במפורש לשום מופע ב־MST?","c":"MST0 (‏IST)","w":["הוא לא משתתף ב־STP","המופע עם המספר הגבוה ביותר","MST1"],"e":"כל ה־VLANים שייכים כברירת מחדל ל־MST0 (‏IST). רק VLANים שממופים במפורש עוברים למופעים אחרים."},{"id":"B19.3","lv":"CCNP","t":"MST","q":"מה מייצג ה־sysid בפלט show spanning-tree mst 2?","c":"מספר המופע (2)","w":["מספר ה־VLAN","מספר ה־Revision","כתובת ה־MAC"],"e":"ב־MST, ה־Extended System ID מכיל את מספר המופע. לכן ב־MST2 עם עדיפות 4096 תוצג העדיפות 4098."},{"id":"B19.4","lv":"CCNP","t":"MST","q":"מתי נכנסים לתוקף שינויים שבוצעו במצב spanning-tree mst configuration?","c":"רק ביציאה מהמצב","w":["רק אחרי copy run start","מיד אחרי כל פקודה","רק אחרי reload"],"e":"השינויים ממתינים (show pending) עד שיוצאים מהמצב, ואז מופעלים בבת אחת. אפשר לבטל אותם עם abort."},{"id":"B20.1","lv":"CCNA","t":"EtherChannel","q":"איזה צירוף מצבים **לא** ייצור EtherChannel?","c":"passive – passive","w":["desirable – auto","active – passive","on – on"],"e":"במצב passive המתג לא יוזם משא ומתן. כששני הצדדים פסיביים, אף אחד לא שולח LACP, והערוץ לא נוצר. ‏on–on עובד בלי משא ומתן."},{"id":"B20.2","lv":"CCNA","t":"EtherChannel","q":"איזה פרוטוקול EtherChannel מתאים לחיבור בין מתג Cisco למתג של ספק אחר?","c":"LACP","w":["DTP","VTP","PAgP"],"e":"‏LACP הוא תקן IEEE (‏802.3ad), ולכן נתמך אצל כל הספקים. ‏PAgP, ‏DTP ו־VTP הם קנייניים של Cisco."},{"id":"B20.3","lv":"CCNA","t":"EtherChannel","q":"בפלט show etherchannel summary, פורט מסומן (I). מה המשמעות?","c":"הפורט פועל עצמאית (Stand-alone) – לא הצטרף לערוץ","w":["הפורט בהמתנה (Hot-standby)","הפורט פעיל בערוץ","הפורט מוגדר כשכבה 3"],"e":"‏I הוא Individual / Stand-alone: הפורט לא הצליח להצטרף לערוץ, בדרך כלל כי לא התקבלה הסכמה מהצד השני. ‏P הוא Bundled, ו־H הוא Hot-standby."},{"id":"B20.4","lv":"CCNP","t":"EtherChannel","q":"כמה פורטים יכולים להיות פעילים בו־זמנית ב־EtherChannel עם LACP?","c":"8","w":["2","4","16"],"e":"‏LACP מאפשר עד 16 פורטים בקבוצה, אבל רק 8 פעילים. השאר נמצאים ב־Hot-Standby."},{"id":"B20.5","lv":"CCNA","t":"EtherChannel","q":"מתג משתמש ב־src-mac לאיזון עומסים, וכל התעבורה מגיעה מנתב אחד. מה התוצאה הסבירה?","c":"כל התעבורה תעבור בקישור אחד, כי ה־MAC של המקור זהה","w":["הערוץ ייפול","העומס יתחלק שווה בשווה","STP יחסום את הערוץ"],"e":"ה־Hash מחושב רק על ה־MAC של המקור, וכשהוא קבוע התוצאה זהה, ולכן כל הזרמים עוברים באותו קישור. כדאי לעבור ל־src-dst-ip."},{"id":"B21.1","lv":"CCNA","t":"CDP ו־LLDP","q":"מה מציין השדה Port ID בפלט show cdp neighbors?","c":"הפורט של ההתקן השכן, שדרכו הוא מחובר אליי","w":["מספר ה־VLAN","פורט ה־TCP של CDP","הפורט המקומי"],"e":"‏Port ID הוא הפורט אצל השכן. הפורט המקומי מופיע בעמודה Local Intrfce."},{"id":"B21.2","lv":"CCNA","t":"CDP ו־LLDP","q":"מה ההבדל המרכזי בין CDP ל־LLDP?","c":"‏CDP קנייני של Cisco, ו־LLDP הוא תקן IEEE 802.1AB שנתמך אצל כל הספקים","w":["‏CDP עובד בשכבה 3, ו־LLDP בשכבה 2","‏CDP עובר דרך נתבים, ו־LLDP לא","‏LLDP מופעל כברירת מחדל בציוד Cisco, ו־CDP לא"],"e":"שניהם פרוטוקולי שכבה 2 שלא עוברים נתבים. ‏CDP קנייני ומופעל כברירת מחדל ב־Cisco, ו־LLDP הוא תקן פתוח שבדרך כלל כבוי כברירת מחדל."},{"id":"B21.3","lv":"CCNA","t":"CDP ו־LLDP","q":"איזו פקודה מפעילה LLDP בכל המתג?","c":"lldp run","w":["lldp enable","lldp transmit","cdp run"],"e":"‏lldp run מפעיל LLDP ברמה הגלובלית. ‏lldp transmit ו־lldp receive פועלות ברמת הממשק."},{"id":"B21.4","lv":"CCNA","t":"CDP ו־LLDP","q":"מה כל כמה זמן נשלחות הודעות CDP כברירת מחדל, ומה ה־Holdtime?","c":"60 ו־180 שניות","w":["10 ו־40 שניות","5 ו־15 שניות","30 ו־120 שניות"],"e":"‏CDP שולח כל 60 שניות, עם Holdtime של 180. ב־LLDP הערכים הם 30 ו־120. ‏10/40 הם טיימרי Hello/Dead של OSPF."},{"id":"B22.1","lv":"CCNA","t":"ניתוב דינמי","q":"מה ההבדל בין Administrative Distance לבין Metric?","c":"‏AD משווה בין מקורות ופרוטוקולים שונים, ו־Metric משווה בין נתיבים של אותו פרוטוקול","w":["‏Metric משווה בין פרוטוקולים, ו־AD בין נתיבים","אין הבדל","‏AD קובע את ה־Next-Hop"],"e":"‏AD מדרג את אמינות המקור (Connected, ‏Static, ‏OSPF…). ‏Metric מדרג נתיבים שונים לאותו יעד שנלמדו באותו פרוטוקול."},{"id":"B22.2","lv":"CCNA","t":"ניתוב דינמי","q":"איזה מהפרוטוקולים הבאים הוא Link State?","c":"OSPF","w":["RIPv2","EIGRP","BGP"],"e":"‏OSPF (וגם IS-IS) הוא פרוטוקול Link State שמריץ את אלגוריתם SPF. ‏RIP הוא Distance Vector, ‏EIGRP הוא DV מתקדם, ו־BGP הוא Path Vector."},{"id":"B22.3","lv":"CCNA","t":"ניתוב דינמי","q":"מה עושה passive-interface בממשק?","c":"ממשיך לפרסם את הרשת של הממשק, אבל לא שולח בו הודעות ניתוב ולא יוצר בו שכנות","w":["משנה את ה־AD של הממשק","מכבה את הממשק","מפסיק לפרסם את הרשת, אבל ממשיך לשלוח Hellos"],"e":"ממשק פסיבי עדיין משתתף בפרוטוקול (הרשת שלו מפורסמת), אבל לא שולח Hellos או Updates – וזה חוסך משאבים ומשפר אבטחה."},{"id":"B22.4","lv":"CCNA","t":"ניתוב דינמי","q":"בשורה O 10.5.5.0/24 [110/3] via 10.1.1.2, מה מייצג המספר 3?","c":"ה־Metric (‏Cost של OSPF)","w":["ה־AD","מספר ה־Area","מספר הקפיצות"],"e":"בסוגריים מופיעים AD ואז Metric. ‏110 הוא ה־AD של OSPF, ו־3 הוא ה־Cost המצטבר."},{"id":"B23.1","lv":"CCNP","t":"RIP ו־EIGRP","q":"למה RIPv1 לא מתאים לרשתות עם VLSM?","c":"כי הוא Classful – לא שולח מסכה בעדכונים","w":["כי הוא תומך רק ב־IPv6","כי הוא משתמש ב־Multicast","כי ה־AD שלו נמוך"],"e":"‏RIPv1 לא כולל מסכה בעדכונים, ולכן מניח את מסכת המחלקה. ‏RIPv2 שולח מסכה, ולכן תומך ב־VLSM. ‏RIPv1 משתמש ב־Broadcast."},{"id":"B23.2","lv":"CCNP","t":"RIP ו־EIGRP","q":"מהו ה־Hop Count שמסמן נתיב לא נגיש ב־RIP?","c":"16","w":["15","255","0"],"e":"‏16 מייצג אינסוף ב־RIP. הנתיב הרחוק ביותר שעדיין נגיש הוא בן 15 קפיצות."},{"id":"B23.3","lv":"CCNP","t":"RIP ו־EIGRP","q":"באיזה תנאי שכן ב־EIGRP ייחשב Feasible Successor?","c":"ה־Reported Distance שלו נמוך מה־Feasible Distance של הנתיב הטוב ביותר","w":["ה־FD שלו נמוך מה־FD של ה־Successor","ה־AD שלו נמוך מ־90","הוא נמצא באותו AS"],"e":"זהו Feasibility Condition: אם השכן מדווח על מרחק קטן מהמרחק הנוכחי שלי ליעד, מובטח שהנתיב שלו לא עובר דרכי, ולכן הוא ללא לולאה."},{"id":"B23.4","lv":"CCNP","t":"RIP ו־EIGRP","q":"‏RIP ו־EIGRP פועלים יחד, ושניהם מכירים את אותה רשת. איזה נתיב ייכנס לטבלת הניתוב?","c":"EIGRP, כי ה־AD שלו (‏90) נמוך מזה של RIP (‏120)","w":["RIP, כי הוא נלמד קודם","שניהם – איזון עומסים","זה שה־Metric שלו נמוך יותר"],"e":"בין פרוטוקולים שונים משווים AD, לא Metric. ‏90 נמוך מ־120, ולכן EIGRP מנצח."},{"id":"B23.5","lv":"CCNP","t":"RIP ו־EIGRP","q":"מה גורם לבעיה ברשת לא רציפה עם RIPv2 או EIGRP ישן?","c":"סיכום אוטומטי (auto-summary) לגבול המחלקה","w":["Split Horizon","Hold-down Timer","passive-interface"],"e":"עם auto-summary כל נתב מסכם את החלק שלו לאותה רשת מחלקתית, ונתבים אחרים לא יודעים לאן כל תת־רשת שייכת. הפתרון: no auto-summary."},{"id":"B24.1","lv":"CCNA","t":"OSPF","q":"מה ה־Wildcard Mask שתואם לרשת ‎/29?","c":"0.0.0.7","w":["255.255.255.248","0.0.0.15","0.0.0.3"],"e":"מסכת ‎/29 היא 255.255.255.248. ‏255.255.255.255 פחות 255.255.255.248 נותן 0.0.0.7."},{"id":"B24.2","lv":"CCNA","t":"OSPF","q":"לנתב אין router-id מוגדר. יש לו Loopback0 = ‏10.0.0.1, ‏Loopback1 = ‏5.5.5.5, ‏G0/0 = ‏192.168.1.1. מה יהיה ה־Router ID?","c":"10.0.0.1","w":["192.168.1.1","5.5.5.5","0.0.0.0"],"e":"כשאין router-id ידני, נבחרת הכתובת הגבוהה מבין ה־Loopbacks – ‏10.0.0.1 גבוה מ־5.5.5.5. כתובות של ממשקים פיזיים נבדקות רק אם אין Loopback, גם אם הן גבוהות יותר."},{"id":"B24.3","lv":"CCNA","t":"OSPF","q":"באיזה מצב שכנות נשארים שני נתבים מסוג DROTHER באותו מקטע Broadcast?","c":"2-Way","w":["Full","ExStart","Init"],"e":"נתבי DROTHER יוצרים שכנות מלאה רק עם ה־DR וה־BDR. ביניהם הם נשארים ב־2-Way – וזה מצב תקין."},{"id":"B24.4","lv":"CCNA","t":"OSPF","q":"שני נתבים תקועים במצב ExStart/Exchange. מה הסיבה הסבירה ביותר?","c":"MTU לא תואם בממשקים","w":["Area ID שונה","Process ID שונה","Hello Timer שונה"],"e":"כש־MTU לא תואם, הודעות ה־DBD נזרקות ונתקעים ב־ExStart/Exchange. ‏Area או Hello שונים מונעים שכנות כבר בשלב ה־Hello, ו־Process ID הוא מקומי ולא חייב להיות זהה."},{"id":"B24.5","lv":"CCNA","t":"OSPF","q":"מה ה־Cost של OSPF בממשק GigabitEthernet, עם Reference Bandwidth ברירת מחדל?","c":"1","w":["64","10","100"],"e":"‏100 Mbps חלקי 1000 Mbps יוצא קטן מ־1, ולכן מעוגל ל־1 – בדיוק כמו FastEthernet. לכן מומלץ להעלות את ה־Reference Bandwidth."},{"id":"B24.6","lv":"CCNA","t":"OSPF","q":"כיצד נבחר ה־DR במקטע Broadcast?","c":"ה־Priority הגבוה, ובשוויון ה־RID הגבוה","w":["ה־RID הנמוך","הנתב הראשון שעולה תמיד","ה־Priority הנמוך"],"e":"קודם משווים OSPF Priority (גבוה מנצח, ו־0 לא משתתף), ואחר כך Router ID (גבוה מנצח). הבחירה לא מקדימה (Non-Preemptive), ולכן לפעמים הנתב שעלה ראשון נשאר DR – אבל זה לא הכלל."},{"id":"B25.1","lv":"CCNP","t":"OSPF מרובה אזורים","q":"איזה סוג LSA מייצר ABR כדי לפרסם רשתות מאזור אחד לאזור אחר?","c":"Type 3","w":["Type 5","Type 1","Type 2"],"e":"‏Type 3 (‏Summary LSA) נוצר על ידי ABR, ומתאר רשתות מאזורים אחרים. ‏Type 1 ו־2 נשארים בתוך האזור, ו־Type 5 נוצר על ידי ASBR."},{"id":"B25.2","lv":"CCNP","t":"OSPF מרובה אזורים","q":"מה משמעות הקוד O IA בטבלת הניתוב?","c":"נתיב לרשת באזור אחר (Inter-Area)","w":["נתיב חיצוני מסוג 1","נתיב שסונן","נתיב בתוך האזור"],"e":"‏O IA הוא נתיב Inter-Area שנלמד מ־LSA מסוג 3. נתיב בתוך האזור מופיע כ־O, ונתיב חיצוני כ־O E1 או O E2."},{"id":"B25.3","lv":"CCNP","t":"OSPF מרובה אזורים","q":"איזו פקודה מסכמת ב־ABR את הרשתות של Area 12 לנתיב 192.168.1.0/24?","c":"area 12 range 192.168.1.0 255.255.255.0","w":["ip summary-address ospf 1 192.168.1.0/24","network 192.168.1.0 0.0.0.255 area 12","summary-address 192.168.1.0 255.255.255.0"],"e":"‏area X range מסכם LSAs מסוג 3 ב־ABR. ‏summary-address מסכם נתיבים חיצוניים (‏Type 5) ב־ASBR."},{"id":"B25.4","lv":"CCNP","t":"OSPF מרובה אזורים","q":"מה ההבדל בין נתיב E1 לנתיב E2 ב־OSPF?","c":"ב־E2 ה־Cost קבוע (רק החיצוני), וב־E1 מוסיפים לו גם את ה־Cost הפנימי עד ה־ASBR","w":["‏E1 פנימי ו־E2 חיצוני","אין הבדל","‏E2 תמיד מועדף על E1"],"e":"‏E2 שומר על ה־Metric החיצוני לאורך כל הדרך, ו־E1 מצטבר. כשיש שני נתיבים זהים, ‏E1 מועדף על E2."},{"id":"B25.5","lv":"CCNP","t":"OSPF מרובה אזורים","q":"איזה סוג LSA אומר לנתבים באזור אחר איך להגיע ל־ASBR?","c":"Type 4","w":["Type 2","Type 7","Type 3"],"e":"‏Type 4 (‏ASBR Summary) נוצר על ידי ABR, ומפרסם את הנגישות ל־ASBR באזורים אחרים. ‏Type 7 הוא LSA חיצוני בתוך NSSA."},{"id":"B25.6","lv":"CCNP","t":"OSPF מרובה אזורים","q":"איזה סוג אזור מאפשר ASBR בתוכו, אבל חוסם LSAs מסוג 5?","c":"NSSA","w":["Backbone","Stub","Totally Stubby"],"e":"ב־NSSA, ה־ASBR מייצר LSAs מסוג 7, וה־ABR מתרגם אותם ל־Type 5 לשאר הרשת. ב־Stub וב־Totally Stubby אסור שיהיה ASBR."},{"id":"B26.1","lv":"CCNA","t":"DNS","q":"איזו רשומת DNS ממפה שם מתחם לכתובת IPv6?","c":"AAAA","w":["A","MX","PTR"],"e":"‏AAAA ממפה שם ל־IPv6, ו־A ממפה ל־IPv4. ‏PTR ממפה כתובת לשם, ו־MX מצביע על שרת דואר."},{"id":"B26.2","lv":"CCNA","t":"DNS","q":"באיזה פורט ופרוטוקול נשלחת בדרך כלל שאילתת DNS של לקוח?","c":"UDP 53","w":["TCP 80","UDP 67","TCP 53"],"e":"שאילתות רגילות נשלחות ב־UDP 53. ‏TCP 53 משמש להעברת אזורים ולתשובות גדולות, ו־UDP 67 שייך ל־DHCP."},{"id":"B26.3","lv":"CCNA","t":"DNS","q":"משתמש מצליח לעשות ping ל־8.8.8.8, אבל לא ל־www.example.com. מה הסיבה הסבירה ביותר?","c":"בעיה בתרגום DNS","w":["VLAN שגוי","ה־Default Gateway שגוי","כבל פגום"],"e":"אם ping לכתובת IP מרוחקת עובד, הקישוריות והניתוב תקינים. הבעיה היא בתרגום השם, כלומר ב־DNS."},{"id":"B26.4","lv":"CCNA","t":"DNS","q":"מה מציינת התשובה Non-authoritative answer ב־nslookup?","c":"התשובה הגיעה ממטמון של שרת שאינו הסמכותי לדומיין","w":["התשובה שגויה","השם לא קיים","השרת דחה את הבקשה"],"e":"ה־Resolver החזיר תשובה מהמטמון שלו, ולא מהשרת הסמכותי של הדומיין. זה המצב הרגיל, והתשובה תקינה."},{"id":"B27.1","lv":"CCNA","t":"DHCP","q":"מה סדר ההודעות בתהליך DHCP?","c":"Discover, Offer, Request, Ack","w":["Request, Offer, Discover, Ack","Discover, Request, Offer, Ack","Offer, Discover, Ack, Request"],"e":"‏DORA – ‏Discover, ‏Offer, ‏Request, ‏Ack."},{"id":"B27.2","lv":"CCNA","t":"DHCP","q":"מהי כתובת ה־IP של המקור בהודעת DHCPDISCOVER?","c":"0.0.0.0","w":["255.255.255.255","169.254.0.1","כתובת ה־Gateway"],"e":"ללקוח עוד אין כתובת, ולכן המקור הוא 0.0.0.0 והיעד הוא 255.255.255.255."},{"id":"B27.3","lv":"CCNA","t":"DHCP","q":"שרת DHCP נמצא ברשת אחרת, והלקוחות מקבלים APIPA. איזו פקודה פותרת את הבעיה בנתב שמחובר ללקוחות?","c":"ip helper-address <כתובת השרת> בממשק שפונה ללקוחות","w":["ip default-gateway","ip forward-protocol any","ip dhcp pool"],"e":"‏ip helper-address הופך את הנתב ל־Relay Agent: הוא ממיר את ה־Broadcast ל־Unicast לשרת, וממלא את giaddr. הפקודה מוגדרת בממשק שבו הלקוחות נמצאים."},{"id":"B27.4","lv":"CCNA","t":"DHCP","q":"על פי מה בוחר שרת DHCP מרכזי מאיזה Pool להקצות כתובת לבקשה שהגיעה דרך Relay?","c":"לפי השדה giaddr שה־Relay מילא","w":["לפי פורט ה־UDP","לפי ה־VLAN בתג","לפי ה־MAC של הלקוח"],"e":"ה־Relay כותב בשדה giaddr את כתובת הממשק שבו התקבלה הבקשה, והשרת בוחר את ה־Pool שהכתובת הזו נמצאת בו."},{"id":"B27.5","lv":"CCNA","t":"DHCP","q":"מתי לקוח DHCP מנסה לראשונה לחדש את ה־Lease שלו?","c":"ב־50% מזמן ה־Lease (‏T1), ב־Unicast לשרת המקורי","w":["ב־87.5% מהזמן, ב־Broadcast","כל 30 שניות","כשה־Lease פג"],"e":"ב־T1 (‏50%) הלקוח פונה בשקט לשרת שלו. רק אם אין תשובה, ב־T2 (‏87.5%) הוא שולח Broadcast לכל שרת."},{"id":"B28.1","lv":"CCNA","t":"Syslog","q":"מה מציין המספר 4 בהודעה ‎%CDP-4-NATIVE_VLAN_MISMATCH?","c":"רמת החומרה – Warning","w":["מספר הפורט","מספר ההודעה ברצף","מספר ה־VLAN"],"e":"בפורמט ‎%FACILITY-SEVERITY-MNEMONIC, המספר הוא רמת החומרה. ‏4 = Warning."},{"id":"B28.2","lv":"CCNA","t":"Syslog","q":"מנהל הגדיר logging trap 4. אילו הודעות יישלחו לשרת ה־Syslog?","c":"רמות 0 עד 4","w":["כל ההודעות","רק רמה 4","רמות 4 עד 7"],"e":"הרמה שנקבעה כוללת את עצמה ואת כל הרמות החמורות ממנה (המספרים הנמוכים): ‏0, 1, 2, 3 ו־4."},{"id":"B28.3","lv":"CCNA","t":"Syslog","q":"מנהל מחובר ב־SSH ולא רואה הודעות Syslog. איזו פקודה תציג אותן בחיבור שלו?","c":"terminal monitor","w":["show logging","logging console","logging synchronous"],"e":"בחיבורי VTY ההודעות לא מוצגות, אלא אם מריצים terminal monitor באותו חיבור. ‏show logging מציג את ה־buffer, אבל לא בזמן אמת."},{"id":"B28.4","lv":"CCNA","t":"Syslog","q":"מהי רמת החומרה של הודעות debug?","c":"7","w":["0","5","6"],"e":"‏Debugging היא רמה 7 – הפחות חמורה והכי מפורטת. ‏6 היא Informational, ו־5 היא Notification."},{"id":"B28.5","lv":"CCNA","t":"Syslog","q":"באיזה פורט ופרוטוקול נשלחות הודעות Syslog לשרת?","c":"UDP 514","w":["TCP 23","UDP 161","UDP 123"],"e":"‏Syslog משתמש ב־UDP 514. ‏161 הוא SNMP, ‏123 הוא NTP, ו־23 הוא Telnet."},{"id":"B29.1","lv":"CCNA","t":"הצפנה וסיסמאות","q":"מה ההבדל המהותי בין הצפנה ל־Hash?","c":"הצפנה הפיכה עם מפתח, ו־Hash הוא חד־כיווני, באורך קבוע ובלתי הפיך","w":["הצפנה תמיד באורך קבוע","אין הבדל","‏Hash דורש מפתח ציבורי"],"e":"מטרת ההצפנה היא סודיות, ואפשר לפענח אותה עם המפתח. ‏Hash נועד לשלמות ולשמירת סיסמאות – אי אפשר לשחזר ממנו את הקלט, והפלט תמיד באורך קבוע."},{"id":"B29.2","lv":"CCNA","t":"הצפנה וסיסמאות","q":"איזה סוג סיסמה ב־IOS ניתן לפענוח מיידי, ולכן אינו נחשב מאובטח?","c":"Type 7","w":["Type 9","Type 8","Type 5"],"e":"‏Type 7 הוא הצפנה הפיכה וחלשה של Cisco (‏service password-encryption). ‏Types 5, 8 ו־9 הם Hashes, ו־9 (‏scrypt) הוא החזק ביותר."},{"id":"B29.3","lv":"CCNA","t":"הצפנה וסיסמאות","q":"מוגדרות גם enable password וגם enable secret. איזו סיסמה תידרש בכניסה ל־Privileged EXEC?","c":"ה־enable secret","w":["אף אחת","ה־enable password","שתיהן, אחת אחרי השנייה"],"e":"‏enable secret תמיד גוברת על enable password."},{"id":"B29.4","lv":"CCNA","t":"הצפנה וסיסמאות","q":"איזה אלגוריתם משמש להחלפת מפתחות בלבד, כך ששני צדדים יוצרים מפתח משותף בלי לשלוח אותו?","c":"Diffie-Hellman","w":["SHA-256","MD5","AES"],"e":"‏Diffie-Hellman מאפשר לשני צדדים ליצור סוד משותף מעל ערוץ פתוח. ‏AES היא הצפנה סימטרית, ו־SHA ו־MD5 הם Hashes."},{"id":"B29.5","lv":"CCNA","t":"הצפנה וסיסמאות","q":"מה רמת ההרשאה ב־IOS שמקבילה ל־Privileged EXEC המלא?","c":"15","w":["0","1","7"],"e":"רמה 15 נותנת גישה מלאה (‏#). רמה 1 היא User EXEC, ורמות 2–14 מיועדות להתאמה אישית."},{"id":"B30.1","lv":"CCNA","t":"SSH ואבטחת קווים","q":"אילו פקודות נדרשות כדי לייצר מפתחות RSA ל־SSH?","c":"hostname שאינו ברירת המחדל, ip domain-name, ואז crypto key generate rsa","w":["רק crypto key generate rsa","transport input ssh בלבד","ip ssh version 2 בלבד"],"e":"שם המפתח נבנה משם המארח ומהדומיין, ולכן שניהם חייבים להיות מוגדרים לפני היצירה. היצירה עצמה היא שמפעילה את SSH."},{"id":"B30.2","lv":"CCNA","t":"SSH ואבטחת קווים","q":"באיזו פקודה מחילים ACL על קווי VTY?","c":"access-class 10 in","w":["access-list 10 vty","ip vty-filter 10","ip access-group 10 in"],"e":"‏access-class מחילה ACL על קווי VTY. ‏ip access-group מחילה ACL על ממשק."},{"id":"B30.3","lv":"CCNA","t":"SSH ואבטחת קווים","q":"מה היתרון העיקרי של login local על פני password בקו VTY?","c":"Accountability – לכל משתמש פרטי זיהוי משלו, ואפשר לדעת מי התחבר","w":["הצפנה של השיחה","אין צורך ב־enable","חיבור מהיר יותר"],"e":"אימות לפי משתמש מאפשר לבטל משתמש בודד ולעקוב מי התחבר ומה עשה. את ההצפנה נותן SSH, לא login local."},{"id":"B30.4","lv":"CCNA","t":"SSH ואבטחת קווים","q":"מה עושה הפקודה transport input ssh תחת line vty?","c":"מאפשרת רק חיבורי SSH בקווים, וחוסמת Telnet","w":["מייצרת מפתחות RSA","משנה את גרסת SSH ל־2","מפעילה SSH בהתקן"],"e":"הפקודה קובעת אילו פרוטוקולים מותרים בקו. ‏SSH עצמו מופעל ביצירת המפתחות, והגרסה נקבעת עם ip ssh version 2."},{"id":"B31.1","lv":"CCNA","t":"AAA","q":"מה ההבדל בין Authentication ל־Authorization?","c":"‏Authentication מאמת מי המשתמש, ו־Authorization קובע מה מותר לו לעשות","w":["‏Authentication קובע את רמת ההרשאה","אין הבדל","‏Authorization מתעד את הפעולות"],"e":"אימות עונה על \"מי אתה?\", הרשאה על \"מה מותר לך?\", ותיעוד (Accounting) על \"מה עשית?\"."},{"id":"B31.2","lv":"CCNA","t":"AAA","q":"איזה פרוטוקול AAA מצפין את כל תוכן החבילה ועובד ב־TCP?","c":"TACACS+","w":["Kerberos","LDAP","RADIUS"],"e":"‏TACACS+ עובד ב־TCP 49 ומצפין את כל ה־Payload. ‏RADIUS עובד ב־UDP 1812/1813, ומצפין רק את הסיסמה."},{"id":"B31.3","lv":"CCNA","t":"AAA","q":"הוגדר aaa authentication login default group radius local, ושרת ה־RADIUS דוחה משתמש עם סיסמה שגויה. מה יקרה?","c":"הגישה תידחה – המעבר ל־local קורה רק כשהשרת לא עונה","w":["ההתקן יאותחל","ההתקן ינסה לאמת מול המסד המקומי","המשתמש ייכנס בלי סיסמה"],"e":"‏Method List עוברת לשיטה הבאה רק במקרה של שגיאה (אין תשובה). דחייה מפורשת מהשרת היא תשובה סופית."},{"id":"B31.4","lv":"CCNA","t":"AAA","q":"מה הסכנה המיידית בהרצת aaa new-model?","c":"היא משנה את האימות בכל הקווים לרשימת default (‏local), וללא משתמש מקומי אפשר לנעול את עצמך בחוץ","w":["היא מכבה SSH","היא מוחקת את התצורה","היא מאתחלת את הנתב"],"e":"מיד אחרי aaa new-model כל הקווים עוברים לאימות לפי Method List. בלי משתמש מקומי, או בלי שרת זמין, אי אפשר יהיה להתחבר."},{"id":"B31.5","lv":"CCNA","t":"AAA","q":"איזה פרוטוקול משמש בדרך כלל לאימות משתמשים ב־802.1X וב־Wi-Fi ארגוני?","c":"RADIUS","w":["SNMP","Syslog","TACACS+"],"e":"‏802.1X משתמש ב־EAP, שנישא ב־RADIUS בין המתג או ה־AP לבין שרת האימות. ‏TACACS+ מתאים לניהול התקנים."},{"id":"B32.1","lv":"CCNA","t":"Port Security","q":"מה ברירת המחדל של Violation Mode ושל Maximum ב־Port Security?","c":"Shutdown ו־1","w":["Protect ו־1","Restrict ו־2","Shutdown ו־10"],"e":"אחרי switchport port-security, ברירת המחדל היא כתובת MAC אחת ומצב הפרה Shutdown."},{"id":"B32.2","lv":"CCNA","t":"Port Security","q":"איזה מצב הפרה זורק את התעבורה הלא מורשית, שולח הודעת Syslog ומעלה את מונה ההפרות – אבל משאיר את הפורט פעיל?","c":"Restrict","w":["Disable","Protect","Shutdown"],"e":"‏Restrict זורק ומדווח. ‏Protect זורק בשקט, בלי לוג ובלי מונה. ‏Shutdown מעביר את הפורט ל־err-disabled."},{"id":"B32.3","lv":"CCNA","t":"Port Security","q":"מה עושה האפשרות sticky ב־Port Security?","c":"לומדת כתובות דינמית ומוסיפה אותן אוטומטית ל־running-config","w":["מכבה את הפורט בכל הפרה","מאפשרת כתובות ללא הגבלה","מונעת למידת כתובות"],"e":"‏Sticky משלב לימוד אוטומטי עם שמירה בתצורה. אחרי copy run start, הכתובות נשמרות גם אחרי reload."},{"id":"B32.4","lv":"CCNA","t":"Port Security","q":"מנהל הקליד switchport port-security maximum 2 ו־violation restrict, אבל Port Security לא פועל. מה חסר?","c":"הפקודה switchport port-security עצמה","w":["spanning-tree portfast","errdisable recovery","switchport mode trunk"],"e":"בלי switchport port-security התכונה לא מופעלת, גם אם שאר הפרמטרים מוגדרים."},{"id":"B32.5","lv":"CCNA","t":"Port Security","q":"הפורט נמצא במצב err-disabled בגלל psecure-violation. מה הדרך הידנית להחזיר אותו לפעולה?","c":"shutdown ואחריו no shutdown בממשק, אחרי ניתוק ההתקן הלא מורשה","w":["no switchport port-security maximum","clear mac address-table","reload"],"e":"‏shutdown ו־no shutdown משחררים את הפורט. אם ההתקן הלא מורשה עדיין מחובר, ההפרה תחזור מיד."},{"id":"B33.1","lv":"CCNA","t":"DHCP Snooping","q":"מהי התוצאה העיקרית של מתקפת Rogue DHCP שבה התוקף מחלק את הכתובת שלו כ־Default Gateway?","c":"Man-in-the-Middle – התעבורה של הלקוחות עוברת דרך התוקף","w":["ה־Pool של השרת הלגיטימי מתרוקן","התוקף מקבל הרשאות מנהל במתג","הלקוחות מקבלים כתובת APIPA"],"e":"הלקוחות שולחים את כל התעבורה החוצה ל\"Gateway\" – שהוא התוקף. התרוקנות ה־Pool היא התוצאה של Starvation."},{"id":"B33.2","lv":"CCNA","t":"DHCP Snooping","q":"בפורט Untrusted עם DHCP Snooping, איזו הודעה תיחסם?","c":"DHCPOFFER","w":["כל ההודעות","DHCPREQUEST","DHCPDISCOVER"],"e":"הודעות שרת (OFFER, ‏ACK, ‏NAK) נחסמות בפורטים לא מהימנים. הודעות לקוח מותרות, אחרי בדיקה."},{"id":"B33.3","lv":"CCNA","t":"DHCP Snooping","q":"הופעל DHCP Snooping במתג, ופתאום אף לקוח לא מקבל כתובת משרת DHCP שהוא נתב Cisco. מה הסיבה הסבירה?","c":"המתג מוסיף Option 82 עם giaddr = 0, והשרת זורק את הבקשות","w":["ה־Lease ארוך מדי","השרת כבוי","ה־VLAN לא קיים"],"e":"זו הבעיה הקלאסית. פתרונות: no ip dhcp snooping information option במתג, או ip dhcp relay information trust-all בשרת. (גם פורט שרת שלא הוגדר כ־trust יגרום לאותה תוצאה – זה הדבר הראשון לבדוק.)"},{"id":"B33.4","lv":"CCNA","t":"DHCP Snooping","q":"מה מכילה טבלת ה־DHCP Snooping Binding?","c":"MAC, ‏IP, ‏Lease, ‏VLAN ופורט של כל לקוח שקיבל כתובת","w":["את ה־Pools","רק כתובות MAC","את רשימת שרתי ה־DHCP המורשים"],"e":"המתג בונה את הטבלה מתוך מעקב אחרי DORA. ‏DAI ו־IP Source Guard משתמשים בה כדי לאמת את הלקוחות."},{"id":"B33.5","lv":"CCNA","t":"DHCP Snooping","q":"למה Port Security לבד לא עוצר מתקפת DHCP Starvation טיפוסית?","c":"כי התוקף משנה רק את ה־chaddr בתוך הודעת ה־DHCP, ולא את ה־MAC של המקור במסגרת","w":["כי הוא לא תומך ב־UDP","כי הוא כבוי בפורטי Access","כי Starvation משתמש ב־IPv6"],"e":"‏Port Security בודק את ה־Source MAC בשכבה 2, שנשאר קבוע. ‏DHCP Snooping משווה בין chaddr ל־Source MAC, ומגביל קצב."},{"id":"B34.1","lv":"CCNA","t":"DAI","q":"על איזה מידע DAI מתבסס כדי לאמת הודעות ARP?","c":"טבלת ה־DHCP Snooping Binding (ו־ARP ACLs)","w":["טבלת הניתוב","טבלת ה־MAC של המתג","טבלת ה־CAM של ה־STP"],"e":"‏DAI משווה את צמד ה־IP וה־MAC של השולח לטבלת ה־Binding שנבנתה ב־DHCP Snooping, או ל־ARP ACL שהוגדר ידנית."},{"id":"B34.2","lv":"CCNA","t":"DAI","q":"הופעל DAI ב־VLAN, ומאז אף מחשב לא מגיע ל־Default Gateway (נתב עם כתובת סטטית). מה הסיבה?","c":"לנתב אין רשומה בטבלת DHCP Snooping, והפורט שלו Untrusted – ולכן ה־ARP שלו נחסם","w":["הנתב כבוי","צריך להפעיל Port Security","ה־VLAN שגוי"],"e":"מארחים עם כתובת סטטית לא מופיעים בטבלת ה־Binding. צריך ip arp inspection trust בפורט שלהם, או ARP ACL."},{"id":"B34.3","lv":"CCNA","t":"DAI","q":"מה התנאי ההכרחי להפעלת DAI בצורה תקינה?","c":"‏DHCP Snooping פעיל באותו VLAN","w":["‏CDP פעיל","‏STP במצב RSTP","‏VTP במצב Server"],"e":"בלי DHCP Snooping אין טבלת Binding, ו־DAI יזרוק כל ARP (חוץ ממה שמותר ב־ARP ACL)."},{"id":"B34.4","lv":"CCNA","t":"DAI","q":"מהו קצב ה־ARP המרבי שמותר כברירת מחדל בפורט Untrusted עם DAI, לפני שהוא עובר ל־err-disabled?","c":"15 לשנייה","w":["100 לשנייה","אין הגבלה","5 לשנייה"],"e":"ברירת המחדל היא 15pps בפורטים לא מהימנים. בפורטים מהימנים אין הגבלה."},{"id":"B35.1","lv":"CCNA","t":"ACL רגילה","q":"מה יקרה לחבילה שלא מתאימה לאף אחת מהשורות ב־ACL?","c":"היא תיזרק, בגלל ה־deny any המרומז","w":["היא תישלח ל־CPU","היא תועבר","היא תסומן ב־QoS"],"e":"בסוף כל ACL יש deny any מרומז. חבילה שלא נתפסה באף שורה נזרקת."},{"id":"B35.2","lv":"CCNA","t":"ACL רגילה","q":"איזה טווח מספרים מזהה ACL רגילה (Standard)?","c":"1–99","w":["1000–1099","200–299","100–199"],"e":"‏1–99 (ו־1300–1999) הם ACL רגילות, ו־100–199 (ו־2000–2699) הן ACL מורחבות."},{"id":"B35.3","lv":"CCNA","t":"ACL רגילה","q":"היכן מומלץ למקם ACL רגילה?","c":"קרוב ליעד","w":["קרוב למקור","אין חשיבות","תמיד בנתב הליבה"],"e":"‏ACL רגילה בודקת רק את המקור. קרוב למקור היא תחסום את המקור לכל היעדים (Over-filtering). את ה־ACL המורחבת ממקמים קרוב למקור."},{"id":"B35.4","lv":"CCNA","t":"ACL רגילה","q":"מהו ה־Wildcard של המארח 10.1.1.5 בלבד?","c":"0.0.0.0 (או המילה host)","w":["255.255.255.255","0.0.0.1","0.0.0.255"],"e":"‏Wildcard ‏0.0.0.0 מחייב התאמה בכל 32 הביטים, כלומר כתובת אחת בדיוק. ‏host 10.1.1.5 הוא הקיצור. ‏255.255.255.255 הוא any."},{"id":"B35.5","lv":"CCNA","t":"ACL רגילה","q":"ACL כוללת רק את השורה deny host 192.168.1.50, והיא הוחלה על ממשק. מה התוצאה?","c":"כל התעבורה בממשק תיחסם","w":["שום דבר לא ייחסם","ה־ACL תידחה","רק 192.168.1.50 ייחסם"],"e":"בגלל ה־deny any המרומז, כל מה שאינו 192.168.1.50 נחסם גם הוא. צריך להוסיף permit any."},{"id":"B36.1","lv":"CCNA","t":"ACL מורחבת ו־PBR","q":"מה ההבדל המהותי בין ACL רגילה ל־ACL מורחבת?","c":"רגילה בודקת רק את כתובת המקור, ומורחבת בודקת מקור, יעד, פרוטוקול ופורטים","w":["מורחבת בודקת רק את כתובת היעד","אין הבדל מלבד המספר","רגילה תומכת בפורטים"],"e":"‏ACL רגילה מתאימה רק לפי כתובת המקור. ‏ACL מורחבת מתאימה לפי מגוון שדות בשכבות 3 ו־4."},{"id":"B36.2","lv":"CCNA","t":"ACL מורחבת ו־PBR","q":"איזו שורה חוסמת גישת Web מהמארח 172.16.1.1 לשרת 10.2.2.145?","c":"deny tcp host 172.16.1.1 host 10.2.2.145 eq 80","w":["deny ip host 172.16.1.1 host 10.2.2.145 eq 80","deny tcp host 10.2.2.145 host 172.16.1.1 eq 80","deny tcp host 172.16.1.1 eq 80 host 10.2.2.145"],"e":"מקור ← יעד, והפורט 80 צמוד ליעד (פורט היעד של השרת). כשהפורט צמוד למקור הוא נבדק כפורט מקור (תשובות מהשרת), ועם הפרוטוקול ip אי אפשר לציין פורט בכלל."},{"id":"B36.3","lv":"CCNA","t":"ACL מורחבת ו־PBR","q":"היכן מומלץ למקם ACL מורחבת?","c":"קרוב למקור","w":["קרוב ליעד","רק על VTY","תמיד בממשק היוצא לאינטרנט"],"e":"היא מזהה במדויק את התעבורה, ולכן אפשר לזרוק אותה מוקדם ככל האפשר, בלי לפגוע בתעבורה אחרת."},{"id":"B36.4","lv":"CCNA","t":"ACL מורחבת ו־PBR","q":"מה עושה המילה established בשורת ACL מורחבת?","c":"מתאימה רק לחבילות TCP עם דגל ACK או RST – תשובות בשיחות קיימות","w":["מתירה רק חבילות SYN חדשות","מתאימה לכל UDP","מתעדת את החיבור"],"e":"‏established תופסת חבילות TCP שאינן פתיחת שיחה (יש בהן ACK או RST). כך אפשר להתיר תשובות מבחוץ, בלי לאפשר פתיחת חיבורים חדשים מבחוץ."},{"id":"B36.5","lv":"CCNA","t":"ACL מורחבת ו־PBR","q":"ב־PBR, מה קורה לחבילה שלא מתאימה לשום בלוק permit ב־route-map?","c":"היא מנותבת כרגיל, לפי טבלת הניתוב","w":["היא נשלחת ל־Next-Hop של הבלוק הראשון","היא נשלחת ל־Null0","היא נזרקת"],"e":"ב־PBR, חבילה שלא הותאמה (או שהתאימה לבלוק deny) פשוט חוזרת לניתוב הרגיל. זה שונה מ־ACL לסינון, שבה יש deny מרומז."},{"id":"B36.6","lv":"CCNA","t":"ACL מורחבת ו־PBR","q":"על איזה ממשק מחילים ip policy route-map?","c":"על הממשק שבו התעבורה נכנסת לנתב","w":["על הממשק שבו התעבורה יוצאת","על Loopback","גלובלית בלבד"],"e":"‏PBR פועל על חבילות שנכנסות לממשק, לפני החלטת הניתוב. לתעבורה שהנתב עצמו מייצר משתמשים ב־ip local policy route-map."},{"id":"N01.1","lv":"CCNA","t":"מודלי OSI ו־TCP/IP","q":"באיזו שכבה של מודל OSI פועלים פרוטוקולי TCP ו־UDP?","c":"שכבה 4 – Transport","w":["שכבה 3 – Network","שכבה 5 – Session","שכבה 2 – Data Link"],"e":"TCP ו־UDP הם פרוטוקולי שכבת התעבורה (4). הם מספקים מספרי פורטים ומעבירים מידע מתהליך לתהליך."},{"id":"N01.2","lv":"CCNA","t":"מודלי OSI ו־TCP/IP","q":"איזו שכבה במודל OSI אחראית על הצפנה, דחיסה ופורמט נתונים?","c":"Presentation (שכבה 6)","w":["Session (שכבה 5)","Application (שכבה 7)","Transport (שכבה 4)"],"e":"שכבת ההצגה (6) מטפלת בייצוג הנתונים: קידוד, הצפנה ודחיסה, למשל TLS ו־JPEG."},{"id":"N01.3","lv":"CCNA","t":"מודלי OSI ו־TCP/IP","q":"מהו סדר האנקפסולציה הנכון אצל השולח?","c":"Data → Segment → Packet → Frame → Bits","w":["Data → Packet → Segment → Frame → Bits","Bits → Frame → Packet → Segment → Data","Data → Frame → Packet → Segment → Bits"],"e":"כל שכבה עוטפת את מה שקיבלה מלמעלה: Transport יוצרת Segment, ‏Network יוצרת Packet, ‏Data Link יוצרת Frame, וה־Physical משדרת Bits."},{"id":"N01.4","lv":"CCNA","t":"מודלי OSI ו־TCP/IP","q":"איזה דגל TCP משמש לפתיחת חיבור חדש?","c":"SYN","w":["FIN","RST","PSH"],"e":"לחיצת היד המשולשת מתחילה ב־SYN, ממשיכה ב־SYN-ACK ומסתיימת ב־ACK. ‏FIN סוגר חיבור, ו־RST מאפס אותו."},{"id":"N01.5","lv":"CCNA","t":"מודלי OSI ו־TCP/IP","q":"מה גודל הכותרת של UDP?","c":"8 בתים","w":["20 בתים","4 בתים","32 בתים"],"e":"לכותרת UDP יש רק ארבעה שדות של 2 בתים כל אחד: Source Port, ‏Destination Port, ‏Length ו־Checksum. סך הכול 8 בתים."},{"id":"N01.6","lv":"CCNA","t":"מודלי OSI ו־TCP/IP","q":"איזה מנגנון ב־TCP מאפשר למקבל לקבוע כמה מידע אפשר לשלוח לו לפני אישור?","c":"Window (בקרת זרימה)","w":["Checksum","Urgent Pointer","TTL"],"e":"גודל החלון (Window Size) מגדיר כמה בתים אפשר לשלוח בלי לחכות ל־ACK. כך המקבל שולט בקצב."},{"id":"N01.7","lv":"CCNA","t":"מודלי OSI ו־TCP/IP","q":"איזה פורט משמש את HTTPS?","c":"TCP 443","w":["TCP 80","TCP 8443 בלבד","UDP 443 בלבד"],"e":"HTTPS משתמש כברירת מחדל ב־TCP 443. ‏HTTP משתמש ב־80."},{"id":"N01.8","lv":"CCNA","t":"מודלי OSI ו־TCP/IP","q":"איזה פרוטוקול משתמש ב־UDP 69?","c":"TFTP","w":["FTP","SNMP","NTP"],"e":"TFTP הוא פרוטוקול העברת קבצים פשוט, בלי אימות, שעובד ב־UDP 69. ‏FTP עובד ב־TCP 20/21."},{"id":"N01.9","lv":"CCNA","t":"מודלי OSI ו־TCP/IP","q":"מה נקרא השילוב של כתובת IP ומספר פורט?","c":"Socket","w":["Segment","Frame","Session ID"],"e":"Socket הוא הצמד IP:Port (למשל 10.1.1.5:443). צמד של שני Sockets מזהה חיבור באופן ייחודי."},{"id":"N01.10","lv":"CCNA","t":"שכבה פיזית וכבלים","q":"איזה סוג סיב מתאים למרחקים של עשרות קילומטרים?","c":"Single-mode","w":["Multimode OM1","Multimode OM3","UTP Cat 6a"],"e":"לסיב Single-mode יש ליבה צרה (כ־9 מיקרון) ומקור לייזר, ולכן הוא מגיע למרחקים ארוכים בהרבה מ־Multimode."},{"id":"N01.11","lv":"CCNA","t":"שכבה פיזית וכבלים","q":"מה מתאר המונח Attenuation?","c":"היחלשות האות לאורך הכבל","w":["הפרעה מכבל סמוך","התנגשות בין מסגרות","החזרת אות מקצה הכבל"],"e":"Attenuation היא היחלשות האות לאורך המרחק. זו הסיבה למגבלה של 100 מטר בכבלי UTP."},{"id":"N01.12","lv":"CCNA","t":"שכבה פיזית וכבלים","q":"מה מספק תקן IEEE 802.3at (PoE+)?","c":"עד 30 וואט לפורט","w":["עד 15.4 וואט לפורט","עד 90 וואט לפורט","רק נתונים, בלי חשמל"],"e":"‏802.3af (PoE) מספק 15.4W, ‏802.3at (PoE+) מספק 30W, ו־802.3bt מגיע ל־60 עד 90 וואט."},{"id":"N01.13","lv":"CCNA","t":"שכבה פיזית וכבלים","q":"איזה מונה בממשק מצביע על מסגרות שה־FCS שלהן לא תקין?","c":"CRC","w":["Giants","Collisions","Output drops"],"e":"שגיאת CRC פירושה שה־FCS שחושב לא תואם לזה שבמסגרת. הסיבות הנפוצות: כבל פגום, הפרעות או Duplex Mismatch."},{"id":"N01.14","lv":"CCNA","t":"שכבה פיזית וכבלים","q":"איזה תקן Ethernet מעביר 1 Gbps על כבל UTP?","c":"1000BASE-T","w":["1000BASE-SX","100BASE-TX","10GBASE-SR"],"e":"‏1000BASE-T (‏802.3ab) משתמש בכל ארבעת הזוגות של UTP. ‏SX הוא סיב Multimode."},{"id":"N01.15","lv":"CCNA","t":"שכבה פיזית וכבלים","q":"למה משמשים פורטי SFP במתג?","c":"להכנסת מודולים שקובעים את סוג החיבור – סיב או נחושת","w":["לחיבור כבל קונסולה","לאספקת חשמל בלבד","לגיבוי התצורה"],"e":"SFP הוא מודול שמכניסים לחריץ. כך אותו מתג יכול להתחבר לסיב Multimode, לסיב Single-mode או לנחושת, לפי הצורך."},{"id":"N01.16","lv":"CCNA","t":"Ethernet ו־MAC","q":"מה גודל כתובת MAC?","c":"48 ביט","w":["32 ביט","64 ביט","128 ביט"],"e":"כתובת MAC היא 48 ביט (6 בתים), ונכתבת ב־12 ספרות הקסדצימליות."},{"id":"N01.17","lv":"CCNA","t":"Ethernet ו־MAC","q":"מהי כתובת ה־MAC של Broadcast?","c":"FFFF.FFFF.FFFF","w":["0000.0000.0000","0100.5E00.0000","3333.0000.0001"],"e":"כל הביטים דלוקים: FF:FF:FF:FF:FF:FF. מסגרת כזו מתקבלת אצל כל ההתקנים באותו VLAN."},{"id":"N01.18","lv":"CCNA","t":"Ethernet ו־MAC","q":"באיזה תחילית מתחילות כתובות MAC של IPv4 Multicast?","c":"01:00:5E","w":["FF:FF:FF","33:33","00:00:0C"],"e":"‏IPv4 Multicast ממופה ל־MAC שמתחיל ב־01:00:5E. ‏33:33 משמש ל־IPv6 Multicast, ו־00:00:0C הוא OUI של Cisco."},{"id":"N01.19","lv":"CCNA","t":"Ethernet ו־MAC","q":"מה המשמעות של ביט I/G שערכו 1 בכתובת MAC?","c":"כתובת קבוצה – Multicast או Broadcast","w":["כתובת שהוגדרה מקומית","כתובת Unicast","כתובת של נתב"],"e":"ביט I/G (הביט הנמוך בבית הראשון) קובע: 0 = כתובת יחידה (Unicast), ו־1 = כתובת קבוצה."},{"id":"N01.20","lv":"CCNA","t":"Ethernet ו־MAC","q":"מה גודל ה־MTU הסטנדרטי ב־Ethernet?","c":"1500 בתים","w":["1518 בתים","9000 בתים","64 בתים"],"e":"ה־MTU הוא גודל המטען המרבי – 1500 בתים. ‏1518 הוא גודל המסגרת כולה, ו־9000 הוא Jumbo Frame."},{"id":"N01.21","lv":"CCNA","t":"מיתוג Ethernet","q":"נתב עם 3 ממשקים פעילים, ובכל ממשק מתג. כמה תחומי שידור יש?","c":"3","w":["1","6","תלוי במספר המחשבים"],"e":"כל ממשק של נתב הוא תחום שידור נפרד, כי נתב לא מעביר Broadcast. בלי VLANים, כל מתג הוא חלק מתחום אחד."},{"id":"N01.22","lv":"CCNA","t":"מיתוג Ethernet","q":"מה עושה מתג כשמגיעה מסגרת שה־MAC של היעד שלה רשום על אותו פורט שממנו היא נכנסה?","c":"זורק את המסגרת (Filter)","w":["מציף לכל הפורטים","מחזיר אותה לשולח","שולח אותה לנתב"],"e":"היעד נמצא באותו מקטע וכבר קיבל את המסגרת. אין סיבה להעביר אותה הלאה, ולכן המתג מסנן אותה."},{"id":"N01.23","lv":"CCNA","t":"מיתוג Ethernet","q":"איזו פקודה מציגה את טבלת כתובות ה־MAC במתג?","c":"show mac address-table","w":["show ip arp","show cam-table all","show interfaces mac"],"e":"show mac address-table מציגה VLAN, כתובת, סוג (Dynamic/Static) ופורט. ‏show ip arp מציגה את טבלת ה־ARP."},{"id":"N01.24","lv":"CCNA","t":"ARP","q":"מה עושה Gratuitous ARP?","c":"מכריז על מיפוי IP–MAC של השולח בלי שמישהו שאל","w":["מבקש כתובת IP משרת","מתרגם שם מתחם לכתובת","מוחק את טבלת ה־ARP"],"e":"Gratuitous ARP משמש לזיהוי כתובת כפולה ולעדכון טבלאות אחרי שינוי MAC, למשל במעבר בין נתבים ב־HSRP."},{"id":"N01.25","lv":"CCNA","t":"ARP","q":"איזה פרוטוקול מחליף את ARP ב־IPv6?","c":"NDP – Neighbor Discovery (ICMPv6)","w":["DHCPv6","RARP","IGMP"],"e":"ב־IPv6 אין ARP. ‏NDP משתמש בהודעות Neighbor Solicitation ו־Neighbor Advertisement, שנשלחות ב־Multicast."},{"id":"N01.26","lv":"CCNA","t":"IPv4","q":"מה ערך שדה Protocol בכותרת IPv4 כשהמטען הוא TCP?","c":"6","w":["17","1","89"],"e":"‏1 = ICMP, ‏6 = TCP, ‏17 = UDP, ‏89 = OSPF."},{"id":"N01.27","lv":"CCNA","t":"IPv4","q":"מה כתובת ה־Broadcast של הרשת 172.16.0.0/16?","c":"172.16.255.255","w":["172.16.0.255","172.255.255.255","255.255.255.255"],"e":"ב־‎/16 שני האוקטטים האחרונים שייכים למארחים. כשכל ביטי המארח דלוקים מקבלים 172.16.255.255."},{"id":"N01.28","lv":"CCNA","t":"IPv4","q":"איזה טווח הוא כתובות Loopback?","c":"127.0.0.0/8","w":["169.254.0.0/16","10.0.0.0/8","224.0.0.0/4"],"e":"‏127.0.0.0/8 שמור ל־Loopback. ‏ping 127.0.0.1 בודק את מחסנית ה־TCP/IP במחשב עצמו."},{"id":"N01.29","lv":"CCNA","t":"IPv4","q":"לאיזו מחלקה שייכת הכתובת 191.10.5.1?","c":"B","w":["A","C","D"],"e":"מחלקה B מתחילה בביטים 10, ולכן האוקטט הראשון שלה בטווח 128–191."},{"id":"N01.30","lv":"CCNA","t":"IPv4","q":"מה משמעות הסמל U בפלט של ping ב־IOS?","c":"התקבלה הודעת Destination Unreachable","w":["תשובה התקבלה","פג הזמן (Timeout)","החבילה פוצלה"],"e":"‏! = הצלחה, ‏. = Timeout, ‏U = Unreachable. ‏U מופיע, למשל, כשנתב לא מוצא נתיב או כש־ACL חוסם."},{"id":"N01.31","lv":"CCNA","t":"Subnetting ו־VLSM","q":"כמה תתי־רשתות ‎/28 אפשר ליצור מרשת ‎/24?","c":"16","w":["8","14","32"],"e":"גונבים 4 ביטים (‏28 פחות 24), ו־2 בחזקת 4 שווה 16 תתי־רשתות. בכל אחת יש 14 מארחים שמישים."},{"id":"N01.32","lv":"CCNA","t":"Subnetting ו־VLSM","q":"מהי המסכה העשרונית של ‎/27?","c":"255.255.255.224","w":["255.255.255.240","255.255.255.192","255.255.255.248"],"e":"‏‎/27 משאיר 3 ביטים דלוקים באוקטט האחרון: 128+64+32 = 224."},{"id":"N01.33","lv":"CCNA","t":"Subnetting ו־VLSM","q":"מה הכתובת האחרונה שאפשר לתת למארח ברשת 10.1.1.64/26?","c":"10.1.1.126","w":["10.1.1.127","10.1.1.128","10.1.1.94"],"e":"גודל הבלוק הוא 64, ולכן הרשת היא 64–127. ה־Broadcast הוא ‎.127, והמארח האחרון הוא ‎.126."},{"id":"N01.34","lv":"CCNA","t":"Subnetting ו־VLSM","q":"איזו מסכה הקטנה ביותר תספק 500 מארחים?","c":"‎/23","w":["‎/24","‎/22","‎/25"],"e":"ב־‎/23 יש 9 ביטי מארח: 2 בחזקת 9 פחות 2 = 510 מארחים. ‏‎/24 נותן רק 254."},{"id":"N01.35","lv":"CCNA","t":"Subnetting ו־VLSM","q":"האם 192.168.5.130/25 ו־192.168.5.120/25 נמצאים באותה תת־רשת?","c":"לא – הראשונה ב־‎.128/25 והשנייה ב־‎.0/25","w":["כן – שתיהן ב־192.168.5.0/24","כן – אותה מסכה","אי אפשר לדעת"],"e":"ב־‎/25 גודל הבלוק הוא 128. ‏‎.120 שייכת לרשת 0–127, ו־‎.130 שייכת לרשת 128–255."},{"id":"N01.36","lv":"CCNA","t":"Subnetting ו־VLSM","q":"מה ה־Wildcard של המסכה 255.255.240.0?","c":"0.0.15.255","w":["0.0.16.255","0.0.240.255","255.255.15.0"],"e":"מחסרים כל אוקטט מ־255: ‏255−255=0, ‏255−240=15, ‏255−0=255. התוצאה 0.0.15.255."},{"id":"N01.37","lv":"CCNA","t":"Subnetting ו־VLSM","q":"לאיזו רשת שייכת הכתובת 172.20.77.9/19?","c":"172.20.64.0","w":["172.20.72.0","172.20.77.0","172.20.32.0"],"e":"‏‎/19 → 255.255.224.0, וגודל הבלוק באוקטט השלישי הוא 32. הכפולות הן 0, 32, 64, 96, ו־77 נופל בין 64 ל־96."},{"id":"N01.38","lv":"CCNA","t":"IPv6","q":"מה אורכה של כתובת IPv6?","c":"128 ביט","w":["64 ביט","32 ביט","48 ביט"],"e":"כתובת IPv6 היא 128 ביט, ונכתבת ב־8 קבוצות של 4 ספרות הקסדצימליות."},{"id":"N01.39","lv":"CCNA","t":"IPv6","q":"מהו הקיצור התקין של 2001:0DB8:0000:0000:0000:0000:0000:0001?","c":"2001:DB8::1","w":["2001:DB8:0:1","2001::DB8::1","2001:DB8:::1"],"e":"מוחקים אפסים מובילים בכל קבוצה, ומחליפים רצף אחד של קבוצות אפסים ב־\"::\". מותר להשתמש ב־\"::\" פעם אחת בלבד."},{"id":"N01.40","lv":"CCNA","t":"IPv6","q":"באיזו תחילית מתחילות כתובות Link-Local ב־IPv6?","c":"FE80::/10","w":["FC00::/7","2000::/3","FF00::/8"],"e":"‏Link-Local (‏FE80::/10) נוצרת אוטומטית בכל ממשק, ולא עוברת נתב. ‏FC00::/7 היא Unique Local, ‏2000::/3 היא Global Unicast, ו־FF00::/8 היא Multicast."},{"id":"N01.41","lv":"CCNA","t":"IPv6","q":"מה עושה EUI-64?","c":"בונה מזהה ממשק של 64 ביט מכתובת ה־MAC, עם FFFE באמצע והיפוך ביט U/L","w":["מצפין כתובת IPv6","מתרגם IPv4 ל־IPv6","מקצה כתובת משרת DHCPv6"],"e":"‏EUI-64 מפצל את ה־MAC לשני חצאים, מכניס ביניהם FFFE והופך את הביט השביעי (U/L). כך מתקבלים 64 ביטים של Interface ID."},{"id":"N01.42","lv":"CCNA","t":"IPv6","q":"איזו פקודה מפעילה ניתוב IPv6 בנתב Cisco?","c":"ipv6 unicast-routing","w":["ipv6 enable","ip routing ipv6","ipv6 routing on"],"e":"כברירת מחדל נתב לא מעביר חבילות IPv6. ‏ipv6 unicast-routing מפעיל את ההעברה ושליחת ה־RA. ‏ipv6 enable רק יוצר כתובת Link-Local בממשק."},{"id":"N01.43","lv":"CCNA","t":"IPv6","q":"מה תפקיד SLAAC?","c":"המארח בונה לעצמו כתובת IPv6 לפי ה־Prefix שמגיע בהודעת RA של הנתב","w":["שרת מקצה כתובות ושומר מצב","תרגום כתובות בין רשתות","מניעת כתובות כפולות בלבד"],"e":"ב־SLAAC הנתב שולח Router Advertisement עם ה־Prefix, והמארח משלים את מזהה הממשק בעצמו (EUI-64 או אקראי)."},{"id":"N01.44","lv":"CCNA","t":"IPv6","q":"איזו כתובת IPv6 שקולה ל־Loopback?","c":"::1","w":["::","FE80::1","FF02::1"],"e":"‏::1 היא Loopback. ‏:: היא הכתובת הלא מוגדרת, ו־FF02::1 היא Multicast לכל הצמתים."},{"id":"N01.45","lv":"CCNA","t":"IPv6","q":"איזו כתובת Multicast מייצגת את כל הנתבים ב־Link המקומי?","c":"FF02::2","w":["FF02::1","FF02::5","FF02::9"],"e":"‏FF02::1 = כל הצמתים, ‏FF02::2 = כל הנתבים, ‏FF02::5 = נתבי OSPFv3, ‏FF02::9 = RIPng."},{"id":"N02.1","lv":"CCNA","t":"Cisco IOS","q":"איזו פקודה מבטלת את ניסיון התרגום ב־DNS אחרי שמקלידים פקודה שגויה?","c":"no ip domain-lookup","w":["no ip dns","no ip name-server","no service dns"],"e":"כשהפקודה שהוקלדה לא מוכרת, IOS מנסה לתרגם אותה כשם מארח. ‏no ip domain-lookup מבטלת את הניסיון הזה."},{"id":"N02.2","lv":"CCNA","t":"Cisco IOS","q":"איזה צירוף מקשים עוצר ping או traceroute ב־IOS?","c":"Ctrl+Shift+6","w":["Ctrl+C","Ctrl+Z","Esc"],"e":"‏Ctrl+Shift+6 הוא רצף ה־Escape של IOS. ‏Ctrl+Z חוזר ל־Privileged EXEC."},{"id":"N02.3","lv":"CCNA","t":"Cisco IOS","q":"מה עושה הפקודה logging synchronous תחת line console 0?","c":"מונעת מהודעות Syslog לקטוע את השורה שמקלידים","w":["שולחת לוגים לשרת","מסנכרנת שעון","מכבה הודעות"],"e":"אחרי שמוצגת הודעה, IOS מדפיסה שוב את מה שהוקלד, כך שהשורה לא נשברת."},{"id":"N02.4","lv":"CCNA","t":"Cisco IOS","q":"מה מציגה הפקודה show version?","c":"גרסת IOS, זמן פעילות, דגם, זיכרון ו־Configuration Register","w":["רק את התצורה הפעילה","את טבלת הניתוב","את רשימת ה־VLANים"],"e":"show version היא פקודת המידע הכללית על ההתקן והתוכנה שרצה עליו."},{"id":"N02.5","lv":"CCNA","t":"Cisco IOS","q":"איזה ערך Configuration Register גורם לנתב להתעלם מה־startup-config (לשחזור סיסמה)?","c":"0x2142","w":["0x2102","0x2100","0x0000"],"e":"‏0x2102 הוא ערך ברירת המחדל. ‏0x2142 מדלג על טעינת ה־NVRAM, ולכן משמש לשחזור סיסמה."},{"id":"N02.6","lv":"CCNA","t":"Cisco IOS","q":"איזו פקודה מציגה רק את השורות שמכילות \"ospf\" בתצורה?","c":"show running-config | include ospf","w":["show running-config ospf","grep ospf","show ospf config"],"e":"ה־pipe עם include מסנן את הפלט לשורות שמכילות את המחרוזת. הסינון רגיש לאותיות גדולות וקטנות."},{"id":"N02.7","lv":"CCNA","t":"ניתוב סטטי","q":"איזו פקודה מגדירה נתיב ברירת מחדל דרך 10.0.0.1?","c":"ip route 0.0.0.0 0.0.0.0 10.0.0.1","w":["ip default-gateway 10.0.0.1","ip route 255.255.255.255 0.0.0.0 10.0.0.1","route default 10.0.0.1"],"e":"נתיב ברירת המחדל הוא 0.0.0.0/0. ‏ip default-gateway משמש רק במתג שכבה 2, או בנתב שהניתוב בו כבוי."},{"id":"N02.8","lv":"CCNA","t":"ניתוב סטטי","q":"מה מציין [1/0] בשורה S 10.3.0.0/16 [1/0] via 10.1.1.2?","c":"AD של 1 ו־Metric של 0","w":["1 נתיבים ו־0 שגיאות","עדיפות 1 וגרסה 0","Hop אחד ו־0 עלות"],"e":"הערך הראשון בסוגריים הוא המרחק המנהלי, והשני הוא ה־Metric. נתיב סטטי מקבל 1/0."},{"id":"N02.9","lv":"CCNA","t":"ניתוב סטטי","q":"איזו מסכה משמשת לנתיב מארח (Host Route)?","c":"255.255.255.255","w":["255.255.255.0","0.0.0.0","255.255.255.252"],"e":"נתיב מארח מצביע על כתובת בודדת, ולכן מסכתו ‎/32."},{"id":"N02.10","lv":"CCNA","t":"ניתוב סטטי","q":"מתי נתיב סטטי עם Exit Interface יוצא מטבלת הניתוב?","c":"כשהממשק יורד (לא במצב up/up)","w":["כל 30 שניות","כשמתקבל עדכון RIP","אף פעם"],"e":"נתיב סטטי מותקן רק כשהממשק או ה־Next-Hop זמינים. זה מה שמאפשר לנתיב צף להיכנס לטבלה במקומו."},{"id":"N02.11","lv":"CCNA","t":"ניתוב סטטי","q":"איזו פקודה מגדירה נתיב ברירת מחדל ב־IPv6?","c":"ipv6 route ::/0 2001:db8::1","w":["ipv6 route 0.0.0.0/0 2001:db8::1","ipv6 default-route 2001:db8::1","ip route ::/0 2001:db8::1"],"e":"‏::/0 הוא נתיב ברירת המחדל של IPv6. התחביר: ipv6 route prefix/len next-hop."},{"id":"N02.12","lv":"CCNA","t":"VLAN","q":"באיזה VLAN נמצאים כל הפורטים במתג Cisco כברירת מחדל?","c":"VLAN 1","w":["VLAN 0","VLAN 1002","אף VLAN"],"e":"‏VLAN 1 הוא ה־Default VLAN. אי אפשר למחוק אותו או לשנות לו שם."},{"id":"N02.13","lv":"CCNA","t":"VLAN","q":"איזו פקודה משייכת פורט ל־VLAN 20?","c":"switchport access vlan 20","w":["vlan 20 access","switchport vlan 20","interface vlan 20"],"e":"בממשק במצב Access, ‏switchport access vlan 20 קובעת את ה־VLAN. ‏interface vlan 20 יוצרת SVI."},{"id":"N02.14","lv":"CCNA","t":"VLAN","q":"מה מאפשרת ההגדרה switchport voice vlan 50?","c":"טלפון IP מתייג תעבורת קול ב־VLAN 50, והמחשב שמחובר דרכו נשאר ב־Access VLAN","w":["כל הפורט עובר ל־VLAN 50","הפורט הופך ל־Trunk מלא","חסימה של קול"],"e":"בפורט עם Voice VLAN יש שני VLANים: קול מתויג (מהטלפון) ונתונים לא מתויגים (מהמחשב)."},{"id":"N02.15","lv":"CCNA","t":"VLAN","q":"איזו פקודה מציגה את רשימת ה־VLANים ואת הפורטים ששייכים לכל אחד?","c":"show vlan brief","w":["show interfaces trunk","show vtp status","show spanning-tree"],"e":"show vlan brief מציגה VLAN, שם, סטטוס ופורטי Access. פורטי Trunk לא מופיעים בה."},{"id":"N02.16","lv":"CCNA","t":"Trunk ו־DTP","q":"מה ה־Native VLAN כברירת מחדל בקישור 802.1Q?","c":"VLAN 1","w":["VLAN 99","VLAN 0","אין Native VLAN"],"e":"ברירת המחדל היא VLAN 1. מומלץ לשנות אותו ל־VLAN שאין בו משתמשים."},{"id":"N02.17","lv":"CCNA","t":"Trunk ו־DTP","q":"מה ערך ה־TPID בתג 802.1Q?","c":"0x8100","w":["0x0800","0x86DD","0x0806"],"e":"‏0x8100 בשדה ה־EtherType מסמן שמגיע תג VLAN."},{"id":"N02.18","lv":"CCNA","t":"Trunk ו־DTP","q":"כמה ביטים מוקצים ל־VLAN ID בתג 802.1Q?","c":"12","w":["8","16","10"],"e":"‏12 ביטים נותנים 4096 ערכים (0–4095). ‏0 ו־4095 שמורים."},{"id":"N02.19","lv":"CCNA","t":"Trunk ו־DTP","q":"איזו פקודה מוסיפה את VLAN 40 לרשימת ה־VLANים המותרים בלי למחוק את הקיימים?","c":"switchport trunk allowed vlan add 40","w":["switchport trunk allowed vlan 40","switchport trunk vlan 40","switchport allowed add 40"],"e":"בלי המילה add, הפקודה מחליפה את כל הרשימה ב־40 בלבד."},{"id":"N02.20","lv":"CCNA","t":"ניתוב בין VLANים","q":"ב־Router-on-a-Stick, מה צריך להיות מוגדר בצד המתג לכיוון הנתב?","c":"פורט Trunk","w":["פורט Access ב־VLAN 1","פורט מנותב","EtherChannel חובה"],"e":"הנתב מקבל מסגרות מתויגות מכל ה־VLANים בכבל אחד, ולכן הפורט במתג חייב להיות Trunk."},{"id":"N02.21","lv":"CCNA","t":"ניתוב בין VLANים","q":"מה עושה SVI במתג שכבה 3 כשמופעל ip routing?","c":"משמש Default Gateway ל־VLAN ומנתב בינו לבין רשתות אחרות","w":["משמש רק לניהול","מחליף את STP","יוצר Trunk"],"e":"‏interface vlan X עם IP הוא ממשק שכבה 3 של ה־VLAN. עם ip routing המתג מנתב בין ה־SVIים."},{"id":"N02.22","lv":"CCNA","t":"STP","q":"איזה מתג ייבחר ל־Root Bridge, אם לכולם עדיפות 32768?","c":"זה עם כתובת ה־MAC הנמוכה ביותר","w":["זה עם ה־MAC הגבוהה ביותר","זה עם הכי הרבה פורטים","זה שעלה ראשון"],"e":"כשהעדיפות שווה, ה־MAC הנמוכה ביותר שוברת את השוויון."},{"id":"N02.23","lv":"CCNA","t":"STP","q":"מה תפקיד ה־Root Port?","c":"הפורט עם העלות הנמוכה ביותר ל־Root Bridge, בכל מתג שאינו Root","w":["הפורט החסום","הפורט של ה־Root Bridge","פורט שמחובר למחשב"],"e":"בכל מתג שאינו Root יש בדיוק Root Port אחד – הדרך הטובה ביותר שלו ל־Root."},{"id":"N02.24","lv":"CCNA","t":"STP","q":"מהו ה־Forward Delay כברירת מחדל ב־802.1D?","c":"15 שניות","w":["2 שניות","20 שניות","50 שניות"],"e":"‏Hello = 2, ‏Max Age = 20, ‏Forward Delay = 15. ה־Forward Delay הוא משך כל אחד מהמצבים Listening ו־Learning."},{"id":"N02.25","lv":"CCNA","t":"STP","q":"באיזה תדירות ה־Root Bridge שולח BPDUs כברירת מחדל?","c":"כל 2 שניות","w":["כל 10 שניות","כל 30 שניות","רק כשיש שינוי"],"e":"‏Hello Time הוא 2 שניות. ב־RSTP כל מתג שולח BPDUs בעצמו כל 2 שניות."},{"id":"N02.26","lv":"CCNA","t":"RSTP ו־PVST+","q":"איזו פקודה מפעילה Rapid PVST+ במתג?","c":"spanning-tree mode rapid-pvst","w":["spanning-tree rstp enable","spanning-tree mode mst","spanning-tree rapid on"],"e":"‏spanning-tree mode rapid-pvst מעבירה את המתג לגרסה המהירה של PVST."},{"id":"N02.27","lv":"CCNA","t":"RSTP ו־PVST+","q":"אילו שלושה מצבי פורט קיימים ב־RSTP?","c":"Discarding, Learning, Forwarding","w":["Blocking, Listening, Forwarding","Disabled, Blocking, Learning","Listening, Learning, Forwarding"],"e":"‏RSTP איחד את Disabled, ‏Blocking ו־Listening למצב אחד – Discarding."},{"id":"N02.28","lv":"CCNA","t":"RSTP ו־PVST+","q":"מה עושה PortFast?","c":"מעביר פורט Access מיד ל־Forwarding בלי לעבור Listening ו־Learning","w":["מגביר את מהירות הפורט","חוסם BPDUs","מאחד פורטים"],"e":"‏PortFast מתאים לפורטים של התקני קצה. הוא חוסך 30 שניות עלייה, ומונע בעיות של DHCP."},{"id":"N02.29","lv":"CCNA","t":"RSTP ו־PVST+","q":"מה יקרה לפורט עם BPDU Guard אם יחברו אליו מתג?","c":"הפורט יעבור ל־err-disabled","w":["הפורט יהפוך ל־Root Port","ה־BPDU ייזרק בשקט","הפורט יעבור ל־Listening"],"e":"‏BPDU Guard מכבה את הפורט ברגע שמגיע בו BPDU, כדי למנוע לולאות ושינויים בטופולוגיה."},{"id":"N02.30","lv":"CCNA","t":"RSTP ו־PVST+","q":"בקפיצות של כמה אפשר לקבוע Bridge Priority?","c":"4096","w":["1024","100","128"],"e":"‏12 הביטים התחתונים שמורים ל־Extended System ID (‏VLAN), ולכן העדיפות נקבעת רק בכפולות של 4096."},{"id":"N02.31","lv":"CCNA","t":"EtherChannel","q":"איזה מצב LACP יוזם משא ומתן?","c":"active","w":["passive","desirable","auto"],"e":"ב־LACP: ‏active יוזם ו־passive מגיב. ‏desirable ו־auto הם מצבים של PAgP."},{"id":"N02.32","lv":"CCNA","t":"EtherChannel","q":"מה הסימן בפלט show etherchannel summary לערוץ שכבה 2 תקין?","c":"SU","w":["SD","RU","I"],"e":"‏S = Layer2, ‏U = in use. ‏RU הוא ערוץ שכבה 3 תקין, ‏SD = Down, ו־I הוא פורט עצמאי."},{"id":"N02.33","lv":"CCNA","t":"EtherChannel","q":"איזה תקן מגדיר את LACP?","c":"IEEE 802.3ad","w":["IEEE 802.1Q","IEEE 802.1D","IEEE 802.1X"],"e":"‏LACP מוגדר ב־802.3ad (היום חלק מ־802.1AX). ‏802.1Q הוא תיוג VLAN, ‏802.1D הוא STP, ו־802.1X הוא אימות פורטים."},{"id":"N02.34","lv":"CCNA","t":"EtherChannel","q":"איזה פרמטר חייב להיות זהה בכל הפורטים החברים ב־EtherChannel?","c":"מהירות, Duplex ומצב Switchport/VLANים","w":["שם התיאור (description)","מספר הפורט","כתובת ה־MAC"],"e":"פורטים עם הגדרות שונות יקבלו סטטוס suspended, או לא יצטרפו לערוץ."},{"id":"N02.35","lv":"CCNA","t":"EtherChannel","q":"איזו פקודה יוצרת EtherChannel עם LACP בממשקים?","c":"channel-group 1 mode active","w":["channel-protocol pagp","interface port-channel 1 lacp","etherchannel 1 lacp"],"e":"‏channel-group מצרף את הממשק לקבוצה, ו־mode active בוחר LACP יוזם. ממשק ה־Port-channel נוצר אוטומטית."},{"id":"N02.36","lv":"CCNA","t":"CDP ו־LLDP","q":"איזה מידע לא מועבר ב־CDP?","c":"סיסמת ה־enable","w":["גרסת IOS","כתובת IP לניהול","שם הפורט של השכן"],"e":"‏CDP מפרסם זהות, פלטפורמה, גרסה, כתובות ופורטים – אבל לא סיסמאות. ובכל זאת, החשיפה הזו היא סיכון."},{"id":"N02.37","lv":"CCNA","t":"CDP ו־LLDP","q":"איזו פקודה מכבה CDP בממשק בודד?","c":"no cdp enable","w":["no cdp run","cdp disable","shutdown cdp"],"e":"‏no cdp run מכבה גלובלית, ו־no cdp enable מכבה בממשק אחד."},{"id":"N02.38","lv":"CCNA","t":"Telnet ו־SVI","q":"באיזה פורט TCP עובד Telnet?","c":"23","w":["22","21","25"],"e":"‏Telnet = 23 (לא מוצפן), ‏SSH = 22, ‏FTP = 21, ‏SMTP = 25."},{"id":"N02.39","lv":"CCNA","t":"העברת חבילות","q":"מה הסדר שבו נתב בוחר נתיב מתוך כמה נתיבים מתאימים?","c":"Longest Prefix Match, אחריו AD, אחריו Metric","w":["AD, אחריו Metric, אחריו Prefix","Metric, אחריו AD","הנתיב שנלמד אחרון"],"e":"קודם המסכה הארוכה ביותר. בין נתיבים עם אותה קידומת – AD נמוך, ואחריו Metric נמוך."},{"id":"N02.40","lv":"CCNA","t":"העברת חבילות","q":"מה עושה CEF?","c":"מעביר חבילות מהר בעזרת FIB וטבלת Adjacency שנבנו מראש","w":["מצפין חבילות","מחשב נתיבי OSPF","מגן מפני לולאות STP"],"e":"‏Cisco Express Forwarding בונה מראש מבנים שמאפשרים העברה מהירה, בלי חיפוש מלא בטבלת הניתוב לכל חבילה."},{"id":"N03.1","lv":"CCNA","t":"OSPF","q":"מה ה־AD של OSPF?","c":"110","w":["90","120","1"],"e":"‏OSPF = 110, ‏EIGRP פנימי = 90, ‏RIP = 120, סטטי = 1."},{"id":"N03.2","lv":"CCNA","t":"OSPF","q":"לאיזו כתובת Multicast נשלחות הודעות Hello של OSPF?","c":"224.0.0.5","w":["224.0.0.9","224.0.0.10","255.255.255.255"],"e":"‏224.0.0.5 היא AllSPFRouters, ו־224.0.0.6 היא AllDRouters. ‏224.0.0.9 שייכת ל־RIPv2, ו־224.0.0.10 ל־EIGRP."},{"id":"N03.3","lv":"CCNA","t":"OSPF","q":"מה טיימר ה־Dead של OSPF כברירת מחדל ברשת Broadcast?","c":"40 שניות","w":["10 שניות","30 שניות","120 שניות"],"e":"‏Hello הוא 10 שניות, ו־Dead הוא פי ארבעה – 40 שניות. ב־NBMA הערכים הם 30 ו־120."},{"id":"N03.4","lv":"CCNA","t":"OSPF","q":"איזו פקודה קובעת ידנית את ה־Router ID של OSPF?","c":"router-id 1.1.1.1 תחת router ospf","w":["ip ospf router-id 1.1.1.1 בממשק","ospf id 1.1.1.1","hostname 1.1.1.1"],"e":"‏router-id בתהליך OSPF גובר על כל שיטה אחרת. ייתכן שיידרש clear ip ospf process כדי שייכנס לתוקף."},{"id":"N03.5","lv":"CCNA","t":"OSPF","q":"באיזה מספר פרוטוקול IP משתמש OSPF?","c":"89","w":["88","6","17"],"e":"‏OSPF רץ ישירות מעל IP, עם Protocol 89. ‏88 שייך ל־EIGRP."},{"id":"N03.6","lv":"CCNA","t":"OSPF","q":"מה עושה ip ospf priority 0 בממשק?","c":"מונע מהנתב להיבחר ל־DR או BDR במקטע","w":["הופך את הנתב ל־DR","מכבה OSPF בממשק","מאפס את העלות"],"e":"עדיפות 0 מוציאה את הנתב מבחירת DR/BDR. ברירת המחדל היא 1."},{"id":"N03.7","lv":"CCNA","t":"OSPF","q":"באיזה סוג רשת OSPF לא נבחרים DR ו־BDR?","c":"Point-to-Point","w":["Broadcast","NBMA","כל סוגי הרשת בוחרים DR"],"e":"בקישור P2P יש רק שני נתבים, ולכן אין צורך ב־DR. ב־Broadcast וב־NBMA נבחרים DR ו־BDR."},{"id":"N03.8","lv":"CCNA","t":"OSPF","q":"מה תוצאת הפקודה auto-cost reference-bandwidth 10000?","c":"רוחב פס הייחוס עולה ל־10 Gbps, וכך OSPF מבחין בין 1G ל־10G","w":["ה־Cost של כל הממשקים יהיה 10000","כיבוי חישוב העלות","שינוי ה־AD"],"e":"העלות מחושבת כרוחב פס ייחוס חלקי רוחב פס הממשק. ייחוס גבוה יותר מאפשר להבחין בין ממשקים מהירים. צריך להגדיר אותו זהה בכל הנתבים."},{"id":"N03.9","lv":"CCNA","t":"OSPF","q":"אילו פרמטרים חייבים להיות זהים כדי ששני נתבים יהפכו לשכני OSPF?","c":"Area, תת־רשת ומסכה, Hello/Dead, אימות ודגל Stub","w":["Process ID ו־Router ID","Hostname","Priority"],"e":"‏Process ID הוא מקומי, וה־Router ID חייב להיות שונה. ‏Priority משפיע רק על בחירת DR."},{"id":"N03.10","lv":"CCNA","t":"OSPF","q":"מה מציין המצב 2WAY/DROTHER בפלט show ip ospf neighbor?","c":"שכן תקין שאינו DR או BDR – וזה מצב סופי תקין בין שני DROTHERs","w":["תקלה בשכנות","השכן הוא DR","שכנות בתהליך טעינה"],"e":"‏DROTHERs יוצרים שכנות מלאה רק עם ה־DR וה־BDR. ביניהם הם נשארים ב־2-Way, וזה תקין."},{"id":"N03.11","lv":"CCNA","t":"DHCP","q":"איזו פקודה מונעת משרת DHCP של Cisco לחלק את הכתובות 10.1.1.1 עד 10.1.1.10?","c":"ip dhcp excluded-address 10.1.1.1 10.1.1.10","w":["ip dhcp pool exclude 10.1.1.1-10","no ip dhcp 10.1.1.1 10.1.1.10","dhcp reserve 10.1.1.1 10.1.1.10"],"e":"ההחרגה מוגדרת במצב הגלובלי, מחוץ ל־Pool, ומקבלת טווח של כתובת ראשונה ואחרונה."},{"id":"N03.12","lv":"CCNA","t":"DHCP","q":"באיזה פורט UDP מאזין שרת DHCPv4?","c":"67","w":["68","53","69"],"e":"השרת מאזין ב־67, והלקוח ב־68."},{"id":"N03.13","lv":"CCNA","t":"DHCP","q":"איזו פקודה מאפשרת לממשק נתב לקבל כתובת מספק דרך DHCP?","c":"ip address dhcp","w":["ip dhcp client","dhcp enable","ip address auto"],"e":"‏ip address dhcp בממשק הופך אותו ללקוח DHCP."},{"id":"N03.14","lv":"CCNA","t":"DHCP","q":"מה עושה DHCPNAK?","c":"השרת דוחה את בקשת הלקוח, למשל כשהלקוח מבקש כתובת מרשת אחרת","w":["הלקוח משחרר כתובת","השרת מציע כתובת","הלקוח מאשר כתובת"],"e":"‏NAK אומר ללקוח שהבקשה לא תקפה, והלקוח מתחיל DORA מחדש."},{"id":"N03.15","lv":"CCNA","t":"DNS","q":"איזו רשומת DNS מצביעה על שרת הדואר של הדומיין?","c":"MX","w":["A","CNAME","PTR"],"e":"‏MX (Mail Exchanger) מגדירה את שרתי הדואר, עם עדיפות שבה המספר הנמוך עדיף."},{"id":"N03.16","lv":"CCNA","t":"DNS","q":"איזו רשומה משמשת לשאילתה הפוכה – מכתובת IP לשם?","c":"PTR","w":["A","AAAA","NS"],"e":"רשומות PTR נמצאות באזור in-addr.arpa (ב־IPv6: ip6.arpa)."},{"id":"N03.17","lv":"CCNA","t":"DNS","q":"איזו פקודה מגדירה לנתב Cisco שרת DNS?","c":"ip name-server 8.8.8.8","w":["ip dns-server 8.8.8.8","dns server 8.8.8.8","ip domain-server 8.8.8.8"],"e":"‏ip name-server קובעת לאיזה שרת הנתב עצמו שולח שאילתות. ללקוחות מוסרים את השרת ב־DHCP עם dns-server."},{"id":"N03.18","lv":"CCNA","t":"NTP","q":"באיזה פורט עובד NTP?","c":"UDP 123","w":["UDP 161","TCP 123","UDP 514"],"e":"‏NTP משתמש ב־UDP 123. ‏161 שייך ל־SNMP, ו־514 ל־Syslog."},{"id":"N03.19","lv":"CCNA","t":"NTP","q":"מה מציין Stratum ב־NTP?","c":"את המרחק ממקור הזמן המדויק – מספר נמוך הוא קרוב יותר","w":["את רמת ההצפנה","את מספר השרתים","את אזור הזמן"],"e":"‏Stratum 0 הוא השעון עצמו (אטומי או GPS), ‏Stratum 1 מחובר אליו ישירות, ו־16 פירושו לא מסונכרן."},{"id":"N03.20","lv":"CCNA","t":"NAT","q":"איזה סוג NAT מתרגם כתובות פנימיות רבות לכתובת ציבורית אחת, בעזרת פורטים?","c":"PAT – NAT Overload","w":["Static NAT","Dynamic NAT בלי overload","NAT64"],"e":"‏PAT מבדיל בין השיחות לפי מספרי פורטים, ולכן כתובת אחת משרתת אלפי מארחים."},{"id":"N03.21","lv":"CCNA","t":"NAT","q":"במונחי NAT של Cisco, איך נקראת הכתובת הפרטית של מארח פנימי?","c":"Inside Local","w":["Inside Global","Outside Local","Outside Global"],"e":"‏Inside Local היא הכתובת הפנימית, ו־Inside Global היא הכתובת הציבורית שהיא מתורגמת אליה."},{"id":"N03.22","lv":"CCNA","t":"NAT","q":"איזו פקודה מגדירה PAT עם הכתובת של ממשק G0/0?","c":"ip nat inside source list 1 interface g0/0 overload","w":["ip nat outside source static g0/0","ip nat pool overload g0/0","nat enable g0/0"],"e":"‏ACL 1 קובעת מי מתורגם, ו־interface … overload משתמשת בכתובת הממשק עם פורטים. צריך גם לסמן ip nat inside ו־ip nat outside בממשקים."},{"id":"N03.23","lv":"CCNA","t":"NAT","q":"איזו פקודה מציגה את טבלת התרגומים של NAT?","c":"show ip nat translations","w":["show nat table","show ip nat statistics only","show ip route nat"],"e":"‏show ip nat translations מציגה את הצמדים Inside Local/Global ו־Outside."},{"id":"N03.24","lv":"CCNA","t":"Syslog","q":"מהו שם רמת Syslog מספר 3?","c":"Errors","w":["Warnings","Critical","Notifications"],"e":"‏0 Emergency, ‏1 Alert, ‏2 Critical, ‏3 Error, ‏4 Warning, ‏5 Notice, ‏6 Informational, ‏7 Debug."},{"id":"N03.25","lv":"CCNA","t":"Syslog","q":"איזו פקודה שולחת לוגים לשרת 10.1.1.50?","c":"logging host 10.1.1.50","w":["logging server 10.1.1.50 udp","syslog 10.1.1.50","ip syslog-server 10.1.1.50"],"e":"‏logging host קובעת את השרת, ו־logging trap קובעת את הרמה שנשלחת אליו."},{"id":"N03.26","lv":"CCNA","t":"SNMP","q":"איזו גרסת SNMP מספקת אימות והצפנה?","c":"SNMPv3","w":["SNMPv1","SNMPv2c","כל הגרסאות"],"e":"‏v1 ו־v2c משתמשים ב־Community String בטקסט גלוי. ‏v3 מוסיף משתמשים, אימות (auth) והצפנה (priv)."},{"id":"N03.27","lv":"CCNA","t":"SNMP","q":"מה ההבדל בין SNMP Trap ל־SNMP Inform?","c":"Inform דורש אישור מהמנהל, ו־Trap לא","w":["Trap מוצפן ו־Inform לא","Inform נשלח מהמנהל להתקן","אין הבדל"],"e":"שניהם התראות שההתקן יוזם. Inform אמין יותר, כי המנהל מאשר את קבלתו."},{"id":"N03.28","lv":"CCNA","t":"SSH ואבטחת קווים","q":"מה הגודל המינימלי של מפתח RSA שנדרש ל־SSHv2 ב־IOS?","c":"768 ביט","w":["512 ביט","360 ביט","4096 ביט"],"e":"‏SSHv2 דורש מפתח של 768 ביט לפחות. בפועל מומלץ 2048 ומעלה."},{"id":"N03.29","lv":"CCNA","t":"SSH ואבטחת קווים","q":"איזו פקודה מנתקת משתמש VTY שלא הקליד דבר במשך 10 דקות?","c":"exec-timeout 10 0","w":["timeout 600","session-timeout 10","idle 10"],"e":"‏exec-timeout מקבל דקות ושניות. ‏0 0 מבטל את הניתוק האוטומטי."},{"id":"N03.30","lv":"CCNA","t":"ACL רגילה","q":"מה כוללת כל ACL בסופה, באופן מרומז?","c":"deny any","w":["permit any","log","remark"],"e":"אם אין התאמה לאף שורה, החבילה נזרקת. לכן ACL שיש בה רק שורות deny חוסמת הכול."},{"id":"N03.31","lv":"CCNA","t":"ACL רגילה","q":"מה פירוש host 10.1.1.5 בשורת ACL?","c":"10.1.1.5 0.0.0.0 – התאמה לכתובת אחת בלבד","w":["10.1.1.0 0.0.0.255","כל המארחים ברשת 10.1.1.0","המארח שמריץ את ה־ACL"],"e":"‏host הוא קיצור של Wildcard 0.0.0.0. המילה any היא קיצור של ‎0.0.0.0 255.255.255.255."},{"id":"N03.32","lv":"CCNA","t":"ACL מורחבת ו־PBR","q":"איזו שורה מתירה ל־192.168.1.0/24 גלישת HTTPS לכל יעד?","c":"permit tcp 192.168.1.0 0.0.0.255 any eq 443","w":["permit udp 192.168.1.0 0.0.0.255 any eq 443","permit tcp any 192.168.1.0 0.0.0.255 eq 443","permit ip 192.168.1.0 0.0.0.255 any eq 443"],"e":"‏HTTPS עובד ב־TCP, והפורט 443 צמוד ליעד. ל־ip אין פורטים."},{"id":"N03.33","lv":"CCNA","t":"ACL מורחבת ו־PBR","q":"באיזו מילת מפתח מתירים רק תשובות לחיבורי TCP שנפתחו מבפנים?","c":"established","w":["reflexive","return","stateful"],"e":"‏established תופסת חבילות TCP עם ACK או RST – כלומר חבילות שאינן פתיחת חיבור חדש."},{"id":"N03.34","lv":"CCNA","t":"Port Security","q":"באיזה מצב הפרה של Port Security התעבורה הלא מורשית נזרקת בלי הודעת Syslog?","c":"Protect","w":["Restrict","Shutdown","Disable"],"e":"‏Protect זורק בשקט. ‏Restrict זורק, מדווח ומעלה את מונה ההפרות. ‏Shutdown מעביר את הפורט ל־err-disabled."},{"id":"N03.35","lv":"CCNA","t":"Port Security","q":"איזו פקודה מחזירה פורטים אוטומטית ממצב err-disabled שנגרם מ־Port Security?","c":"errdisable recovery cause psecure-violation","w":["port-security auto-recover","clear errdisable all","no errdisable"],"e":"‏errdisable recovery cause עם הסיבה המתאימה מפעיל שחרור אוטומטי, וה־interval קובע אחרי כמה זמן."},{"id":"N03.36","lv":"CCNA","t":"DHCP Snooping","q":"איזו פקודה מסמנת פורט שמחובר לשרת DHCP לגיטימי כמהימן?","c":"ip dhcp snooping trust","w":["ip dhcp trust","dhcp snooping allow","ip helper-address trust"],"e":"בפורטים לא מהימנים (ברירת המחדל) הודעות OFFER ו־ACK נחסמות. ‏trust מתיר אותן בפורט של השרת."},{"id":"N03.37","lv":"CCNA","t":"DAI","q":"בטבלה של איזה מנגנון משתמש DAI כדי לאמת הודעות ARP?","c":"DHCP Snooping Binding","w":["טבלת ה־MAC","טבלת ה־NAT","טבלת ה־CDP"],"e":"‏DAI משווה את צמד ה־IP וה־MAC של שולח ה־ARP לטבלת ה־Binding שנבנתה ב־DHCP Snooping."},{"id":"N03.38","lv":"CCNA","t":"AAA","q":"באילו פורטים משתמש RADIUS?","c":"UDP 1812 לאימות ו־1813 לתיעוד","w":["TCP 49","UDP 514","TCP 1812"],"e":"‏RADIUS עובד ב־UDP 1812/1813 (בגרסאות ישנות 1645/1646). ‏TACACS+ עובד ב־TCP 49."},{"id":"N03.39","lv":"CCNA","t":"Wireless","q":"באיזה תדר עובד Wi-Fi 802.11b/g/n בתחום 2.4GHz, וכמה ערוצים לא חופפים יש בו?","c":"3 ערוצים לא חופפים: 1, 6 ו־11","w":["11 ערוצים לא חופפים","24 ערוצים לא חופפים","ערוץ אחד בלבד"],"e":"בתחום 2.4GHz רק ערוצים 1, 6 ו־11 (בצפון אמריקה) לא חופפים. ב־5GHz יש הרבה יותר ערוצים."},{"id":"N03.40","lv":"CCNA","t":"Wireless","q":"איזה תקן אבטחה אלחוטית הוא המתקדם ביותר, ומשתמש ב־SAE במקום PSK?","c":"WPA3","w":["WPA2","WEP","WPA"],"e":"‏WPA3-Personal מחליף את ה־PSK במנגנון SAE, שמגן מפני התקפת מילון מקוונת. ‏WEP שבור לחלוטין."},{"id":"N03.41","lv":"CCNA","t":"Wireless","q":"מה תפקיד ה־WLC בארכיטקטורה אלחוטית מרכזית?","c":"ניהול מרכזי של נקודות הגישה (Lightweight APs) ושל ה־WLANים","w":["ניתוב בין ספקים","מתן כתובות DHCP בלבד","הצפנת דיסקים"],"e":"‏Lightweight APs מתחברים לבקר (WLC) במנהרות CAPWAP, והבקר מנהל את התצורה, ה־RF והאבטחה."},{"id":"N03.42","lv":"CCNA","t":"Wireless","q":"באילו פורטים UDP משתמש CAPWAP?","c":"5246 לבקרה ו־5247 לנתונים","w":["1812 ו־1813","67 ו־68","161 ו־162"],"e":"‏CAPWAP מקים מנהרת בקרה מוצפנת (5246) ומנהרת נתונים (5247) בין ה־AP ל־WLC."},{"id":"N03.43","lv":"CCNA","t":"FHRP","q":"מה המטרה של HSRP?","c":"לספק Default Gateway וירטואלי עם גיבוי בין כמה נתבים","w":["לחלק עומסים בין VLANים","למנוע לולאות שכבה 2","להקצות כתובות IP"],"e":"‏HSRP יוצר כתובת IP וכתובת MAC וירטואליות. נתב Active עונה עליהן, ונתב Standby מחליף אותו אם הוא נופל."},{"id":"N03.44","lv":"CCNA","t":"FHRP","q":"מהי עדיפות HSRP כברירת מחדל?","c":"100","w":["1","255","0"],"e":"ברירת המחדל היא 100, והגבוה מנצח. כדי שנתב עם עדיפות גבוהה ישתלט מחדש, צריך preempt."},{"id":"N03.45","lv":"CCNA","t":"FHRP","q":"איזה פרוטוקול FHRP הוא תקן פתוח של IETF?","c":"VRRP","w":["HSRP","GLBP","CARP של Cisco"],"e":"‏VRRP (‏RFC 5798) פתוח. ‏HSRP ו־GLBP הם קנייניים של Cisco."},{"id":"N03.46","lv":"CCNA","t":"QoS","q":"איזה ערך DSCP מקובל לתעבורת קול?","c":"EF (46)","w":["AF11 (10)","CS1 (8)","0"],"e":"‏Expedited Forwarding (‏DSCP 46) מיועד לקול – השהיה נמוכה, Jitter נמוך ומעט איבוד."},{"id":"N03.47","lv":"CCNA","t":"QoS","q":"מה ההבדל בין Policing ל־Shaping?","c":"Policing זורק או מסמן מחדש תעבורה שחורגת, ו־Shaping מעכב אותה בתור כדי להחליק את הקצב","w":["Shaping זורק ו־Policing מעכב","אין הבדל","Policing מצפין"],"e":"‏Shaping דורש Buffer, ומתאים ליציאה לכיוון ספק. ‏Policing אוכף קצב מיידית."},{"id":"N03.48","lv":"CCNA","t":"אוטומציה ו־SDN","q":"איזה פורמט נתונים משתמש בזוגות מפתח–ערך בסוגריים מסולסלים, ונפוץ ב־REST API?","c":"JSON","w":["XML","YAML","CSV"],"e":"‏JSON בנוי מאובייקטים {\"key\": value} ומערכים [ ]. ‏XML משתמש בתגיות, ו־YAML מבוסס הזחות."},{"id":"N03.49","lv":"CCNA","t":"אוטומציה ו־SDN","q":"איזו פעולת HTTP ב־REST API משמשת לקריאת נתונים בלבד?","c":"GET","w":["POST","PUT","DELETE"],"e":"‏GET קורא, ‏POST יוצר, ‏PUT/PATCH מעדכנים, ו־DELETE מוחק (CRUD)."},{"id":"N03.50","lv":"CCNA","t":"אוטומציה ו־SDN","q":"איזה כלי אוטומציה לא דורש Agent בהתקנים ועובד מעל SSH?","c":"Ansible","w":["Puppet","Chef","SaltStack עם Minion"],"e":"‏Ansible הוא Agentless: הוא דוחף תצורה דרך SSH, בעזרת Playbooks ב־YAML. ‏Puppet ו־Chef דורשים Agent."},{"id":"N03.51","lv":"CCNA","t":"אוטומציה ו־SDN","q":"בארכיטקטורת SDN, מה ה־Northbound API?","c":"הממשק בין הבקר לאפליקציות שמעליו","w":["הממשק בין הבקר להתקני הרשת","כבל קונסולה","פרוטוקול ניתוב"],"e":"‏Northbound – כלפי אפליקציות (בדרך כלל REST). ‏Southbound – כלפי ההתקנים (OpenFlow, ‏NETCONF ועוד)."},{"id":"N04.1","lv":"CCNP","t":"STP מתקדם","q":"מה עושה Root Guard כשמגיע בפורט Superior BPDU?","c":"מעביר את הפורט למצב root-inconsistent (חסום) עד שה־BPDUs האלה מפסיקים להגיע","w":["מכבה את הפורט ל־err-disabled לצמיתות","הופך את המתג המחובר ל־Root","מתעלם מה־BPDU וממשיך להעביר"],"e":"‏Root Guard מגן על מיקום ה־Root, והחסימה שלו משתחררת אוטומטית."},{"id":"N04.2","lv":"CCNP","t":"STP מתקדם","q":"מפני מה מגן Loop Guard?","c":"מפני פורט חסום שעובר ל־Forwarding כי הפסיק לקבל BPDUs, למשל בקישור חד־כיווני","w":["מפני חיבור מתג לפורט של מחשב","מפני מתג שהופך ל־Root","מפני MAC Flooding"],"e":"במקום לעבור ל־Forwarding אחרי Max Age, הפורט עובר ל־loop-inconsistent."},{"id":"N04.3","lv":"CCNP","t":"STP מתקדם","q":"מה עושה UDLD במצב aggressive כשהוא מזהה קישור חד־כיווני?","c":"מעביר את הפורט ל־err-disabled","w":["רק שולח הודעת Syslog","משנה את ה־Duplex","מחליף את ה־Root"],"e":"במצב normal, ‏UDLD רק מסמן ומדווח. במצב aggressive הוא מכבה את הפורט."},{"id":"N04.4","lv":"CCNP","t":"STP מתקדם","q":"מה התוצאה של spanning-tree bpdufilter enable ברמת ממשק?","c":"הפורט מפסיק לשלוח ולקבל BPDUs – ובפועל STP כבוי בו","w":["הפורט נכבה כשמגיע BPDU","הפורט הופך ל־Root Port","הפורט נחסם"],"e":"זו הגדרה מסוכנת, כי אם יחוברו לפורט מתג, עלולה להיווצר לולאה. ברמה גלובלית BPDU Filter מתנהג אחרת: פורט שמקבל BPDU מאבד את ה־PortFast."},{"id":"N04.5","lv":"CCNP","t":"STP מתקדם","q":"ב־RSTP, איזה סוג קישור מאפשר התכנסות מהירה עם Proposal/Agreement?","c":"Point-to-Point (Full-Duplex)","w":["Shared (Half-Duplex)","Edge בלבד","כל סוג"],"e":"במקטע Shared, ‏RSTP חוזר להתנהגות האיטית של 802.1D."},{"id":"N04.6","lv":"CCNP","t":"STP מתקדם","q":"ב־RSTP, אחרי כמה BPDUs שלא התקבלו מניחים שהשכן נפל?","c":"3 (‏6 שניות)","w":["10 (‏20 שניות)","1","5"],"e":"ב־RSTP כל מתג שולח Hello כל 2 שניות. אם שלושה רצופים לא מגיעים, השכן נחשב מת – במקום 20 שניות של Max Age."},{"id":"N04.7","lv":"CCNP","t":"STP מתקדם","q":"מה מציין תפקיד Backup Port ב־RSTP?","c":"גיבוי ל־Designated Port של אותו מתג באותו מקטע משותף","w":["דרך חלופית ל־Root דרך מתג אחר","פורט Edge","פורט כבוי"],"e":"‏Backup נדיר – הוא נוצר כששני פורטים של אותו מתג מחוברים לאותו Hub. ‏Alternate הוא הגיבוי ל־Root Port."},{"id":"N04.8","lv":"CCNP","t":"STP מתקדם","q":"מה עושה הפקודה spanning-tree portfast trunk?","c":"מפעילה PortFast גם על פורט Trunk – למשל לשרת וירטואליזציה","w":["מבטלת את ה־Trunk","מפעילה BPDU Guard על Trunk","מגדירה Native VLAN"],"e":"‏PortFast רגיל פועל רק על פורטי Access. הגרסה הזו מיועדת ל־Trunk שמחובר להתקן קצה."},{"id":"N04.9","lv":"CCNP","t":"MST","q":"איזה מופע MST קיים תמיד, ומתקשר עם מתגים מחוץ לאזור?","c":"MST0 – ‏IST","w":["MST1","MST15","CST"],"e":"‏IST (‏MST0) הוא היחיד ששולח BPDUs. המידע על שאר המופעים נישא בתוכו כ־M-Records."},{"id":"N04.10","lv":"CCNP","t":"MST","q":"אחרי שינוי בתצורת MST (instance/vlan), מתי השינוי נכנס לתוקף?","c":"ביציאה ממצב spanning-tree mst configuration","w":["מיד","אחרי reload","אחרי 15 שניות"],"e":"‏show pending מציג את השינויים לפני שהם מופעלים, ו־abort מבטל אותם."},{"id":"N04.11","lv":"CCNP","t":"MST","q":"מה מחזיק ה־Extended System ID ב־Bridge ID של MST?","c":"את מספר המופע","w":["את מספר ה־VLAN","את מספר ה־Revision","כלום – הוא 0 תמיד"],"e":"למשל, ב־MST2 עם עדיפות 4096 תוצג העדיפות 4098."},{"id":"N04.12","lv":"CCNP","t":"MST","q":"איזה תקן IEEE הגדיר את MST במקור?","c":"802.1s","w":["802.1w","802.1D","802.1ad"],"e":"‏802.1w הוא RSTP, ו־802.1s הוא MST. שניהם שולבו מאוחר יותר ב־802.1Q."},{"id":"N04.13","lv":"CCNP","t":"MST","q":"מה ההמלצה לגבי מיקום ה־CIST Root כשאזור MST מחובר לרשת PVST+?","c":"שה־CIST Root יהיה בתוך אזור ה־MST","w":["שה־CIST Root יהיה מחוץ לאזור תמיד","זה לא משנה","שאין CIST Root"],"e":"אחרת נדרשים כל שורשי ה־PVST+ מחוץ לאזור, ופורטי הגבול עלולים להיחסם ב־PVST Simulation."},{"id":"N04.14","lv":"CCNP","t":"VTP","q":"מה מונע את \"פצצת ה־Revision\" ב־VTPv3?","c":"רק Primary Server יכול לשנות VLANים, והקידום אליו נעשה בפקודת EXEC מפורשת","w":["ההצפנה של ההודעות","מצב Transparent חובה","ה־Revision מתאפס כל יום"],"e":"מתג חדש עם Revision גבוה לא יכול להשתלט על הדומיין בלי vtp primary."},{"id":"N04.15","lv":"CCNP","t":"VTP","q":"איזו פעולה מאפסת את ה־Configuration Revision במתג לפני שמחברים אותו לרשת?","c":"מעבר למצב Transparent ובחזרה, או שינוי זמני של שם הדומיין","w":["reload","erase startup-config בלבד","no vlan 1"],"e":"שתי הפעולות מאפסות את ה־Revision ל־0. ‏erase startup-config לא מספיק, כי ה־VLANים נשמרים ב־vlan.dat."},{"id":"N04.16","lv":"CCNP","t":"VTP","q":"באיזה מצב VTP אפשר להשתמש ב־Extended VLANs ‏(1006–4094) ב־VTPv2?","c":"Transparent","w":["Server","Client","אין אפשרות"],"e":"‏VTPv1/v2 לא מפיצים Extended VLANs. ב־Transparent הם מוגדרים מקומית בלבד, ונשמרים ב־running-config."},{"id":"N04.17","lv":"CCNP","t":"VTP","q":"מה נבדק כדי לוודא ששני מתגים משתמשים באותה סיסמת VTP?","c":"ה־MD5 Digest ב־show vtp status","w":["ה־Hostname","ה־Revision בלבד","ה־Native VLAN"],"e":"ה־Digest מחושב גם מהסיסמה. אם הוא שונה, הפרסומות נדחות."},{"id":"N04.18","lv":"CCNP","t":"Trunk ו־DTP","q":"איזו פקודה מכבה DTP בפורט Trunk סטטי?","c":"switchport nonegotiate","w":["no dtp","switchport mode access","dtp disable"],"e":"מומלץ להגדיר mode trunk יחד עם nonegotiate, כדי למנוע Switch Spoofing."},{"id":"N04.19","lv":"CCNP","t":"Trunk ו־DTP","q":"מה התוצאה של dynamic desirable בצד אחד ו־dynamic auto בצד השני?","c":"Trunk","w":["Access","err-disabled","אין קישור"],"e":"‏desirable יוזם משא ומתן, ו־auto מסכים כשמבקשים ממנו."},{"id":"N04.20","lv":"CCNP","t":"Trunk ו־DTP","q":"איזו פקודה גלובלית מתייגת גם את ה־Native VLAN, כהגנה מפני Double Tagging?","c":"vlan dot1q tag native","w":["switchport trunk native tag","dot1q native encrypt","spanning-tree native tag"],"e":"כשה־Native מתויג, המתג לא מסיר את התג החיצוני, והמתקפה נכשלת."},{"id":"N04.21","lv":"CCNP","t":"EtherChannel","q":"כמה פורטים יכולים להיות חברים בקבוצת LACP אחת, וכמה מהם פעילים?","c":"עד 16, ומהם 8 פעילים ו־8 ב־Hot-Standby","w":["עד 8, כולם פעילים","עד 4 פעילים","ללא הגבלה"],"e":"‏LACP מאפשר 16 פורטים בקבוצה. השמונה עם העדיפות הטובה ביותר פעילים."},{"id":"N04.22","lv":"CCNP","t":"EtherChannel","q":"מה קובע lacp system-priority?","c":"איזה מתג מחליט אילו פורטים יהיו פעילים כשיש יותר מ־8","w":["את עדיפות ה־STP","את אלגוריתם האיזון","את מהירות הערוץ"],"e":"העדיפות הנמוכה מנצחת (ברירת המחדל 32768), ובשוויון ה־MAC הנמוכה."},{"id":"N04.23","lv":"CCNP","t":"EtherChannel","q":"מה עושה port-channel min-links 2?","c":"מוריד את כל הערוץ אם פחות משני פורטים פעילים","w":["מגביל את הערוץ לשני פורטים","מחייב שני ערוצים","קובע Hash"],"e":"המטרה היא שהתעבורה תעבור לנתיב חלופי, במקום להמשיך בערוץ עם רוחב פס נמוך מדי."},{"id":"N04.24","lv":"CCNP","t":"EtherChannel","q":"מה מזהה EtherChannel Misconfig Guard?","c":"מצב שבו צד אחד מוגדר on, והצד השני לא יצר ערוץ – וזה עלול ליצור לולאה","w":["אלגוריתם Hash לא אחיד","VLAN חסר","מהירות שונה"],"e":"במקרה כזה הפורטים עוברים ל־err-disabled."},{"id":"N04.25","lv":"CCNP","t":"EtherChannel","q":"איזה מנגנון משתמש בפרוטוקול MEC/vPC/StackWise כדי לחבר ערוץ אחד לשני מתגים פיזיים?","c":"Multichassis EtherChannel – שני מתגים שנראים כמתג לוגי אחד","w":["PAgP בלבד","HSRP","MST"],"e":"‏StackWise Virtual, ‏VSS או vPC מאפשרים ערוץ שמתפצל לשני מתגים, בלי ש־STP יחסום חלק ממנו."},{"id":"N04.26","lv":"CCNP","t":"EtherChannel","q":"מה מצב lacp rate fast?","c":"שליחת LACPDUs כל שנייה, במקום כל 30 שניות","w":["הגדלת המהירות ל־10G","ביטול LACP","מעבר ל־PAgP"],"e":"זיהוי מהיר יותר של שכן שנפל."},{"id":"N04.27","lv":"CCNP","t":"אבטחת שכבה 2","q":"מה עושה Private VLAN במצב Isolated?","c":"מונע תקשורת בין פורטים Isolated, אבל מאפשר להם להגיע לפורט Promiscuous","w":["מבודד את ה־VLAN מהנתב","מצפין את התעבורה","חוסם Broadcast בלבד"],"e":"‏PVLAN נפוץ ברשתות אורחים ובמרכזי נתונים: כל הלקוחות מגיעים ל־Gateway, אבל לא זה לזה."},{"id":"N04.28","lv":"CCNP","t":"אבטחת שכבה 2","q":"ב־802.1X, מהו ה־Authenticator?","c":"המתג או נקודת הגישה, שמעבירים בין הלקוח לשרת האימות","w":["המחשב של המשתמש","שרת ה־RADIUS","שרת ה־DHCP"],"e":"‏Supplicant = לקוח, ‏Authenticator = מתג/AP, ‏Authentication Server = ‏RADIUS (למשל ISE)."},{"id":"N04.29","lv":"CCNP","t":"אבטחת שכבה 2","q":"איזה פרוטוקול נושא את EAP בין הלקוח למתג ב־802.1X?","c":"EAPoL – EAP over LAN","w":["RADIUS","TACACS+","PPP"],"e":"בין המתג לשרת, ה־EAP נישא בתוך RADIUS."},{"id":"N04.30","lv":"CCNP","t":"אבטחת שכבה 2","q":"מה עושה MAB (MAC Authentication Bypass)?","c":"מאמת התקנים שלא תומכים ב־802.1X לפי כתובת ה־MAC שלהם, מול RADIUS","w":["חוסם את כל כתובות ה־MAC","מצפין את כתובות ה־MAC","מחליף את Port Security"],"e":"‏MAB מתאים למדפסות ולמצלמות שאין להן Supplicant."},{"id":"N04.31","lv":"CCNP","t":"אבטחת שכבה 2","q":"מה מסנן IP Source Guard?","c":"חבילות IP שכתובת המקור שלהן (ואופציונלית ה־MAC) לא תואמת לטבלת DHCP Snooping בפורט","w":["רק הודעות ARP","רק הודעות DHCP","BPDUs"],"e":"‏ip verify source בודק כל חבילה, ומונע זיוף כתובת IP."},{"id":"N04.32","lv":"CCNP","t":"אבטחת שכבה 2","q":"מה הסף של Storm Control שנקבע ב־storm-control broadcast level 20.00 10.00?","c":"חסימה מעל 20% מרוחב הפס, וחזרה מתחת ל־10%","w":["20 חבילות לשנייה","20 מגה־ביט בדיוק","10% חסימה ו־20% שחרור"],"e":"הערך הראשון הוא סף עליון לחסימה, והשני הוא סף תחתון לחזרה (היסטרזיס)."},{"id":"N04.33","lv":"CCNP","t":"אבטחת שכבה 2","q":"מה ה־Rate Limit כברירת מחדל של DAI בפורט Untrusted?","c":"15 הודעות ARP לשנייה","w":["100 לשנייה","1 לשנייה","ללא הגבלה"],"e":"חריגה מהקצב מעבירה את הפורט ל־err-disabled. בפורט Trusted אין הגבלה."},{"id":"N04.34","lv":"CCNP","t":"אבטחת שכבה 2","q":"איזה מנגנון במתג מאפשר לשכפל תעבורה מפורט אחד לפורט אחר שמחובר ל־Wireshark?","c":"SPAN","w":["NetFlow","SNMP","UDLD"],"e":"‏SPAN משכפל באותו מתג, ‏RSPAN משכפל דרך VLAN, ו־ERSPAN משכפל בתוך מנהרת GRE מעל IP."},{"id":"N04.35","lv":"CCNP","t":"אבטחת שכבה 2","q":"מה ההבדל בין RSPAN ל־ERSPAN?","c":"RSPAN מעביר את התעבורה המשוכפלת ב־VLAN ייעודי בשכבה 2, ו־ERSPAN עוטף אותה ב־GRE ומעביר מעל רשת IP","w":["אין הבדל","ERSPAN רק באותו מתג","RSPAN מצפין"],"e":"‏ERSPAN מאפשר לשלוח תעבורה ממשוכפלת למחשב ניתוח מרוחק, גם מעבר לנתבים."},{"id":"N04.36","lv":"CCNP","t":"ארכיטקטורה","q":"מה מאפיין טופולוגיית Spine-Leaf במרכזי נתונים?","c":"כל Leaf מחובר לכל Spine, ולכן בין כל שני שרתים יש מספר קפיצות קבוע ו־ECMP","w":["כל מתג מחובר לכל מתג","עץ עם Root אחד","טבעת"],"e":"‏Leaf אף פעם לא מתחבר ישירות ל־Leaf אחר, ו־Spine לא מתחבר ל־Spine."},{"id":"N04.37","lv":"CCNP","t":"ארכיטקטורה","q":"מה ההבדל העיקרי בין Collapsed Core לבין מודל שלוש שכבות?","c":"ב־Collapsed Core שכבות ה־Distribution וה־Core מאוחדות","w":["אין Access","אין ניתוב","רק אלחוטי"],"e":"מודל שתי השכבות מתאים לקמפוס קטן או בינוני."},{"id":"N04.38","lv":"CCNP","t":"ארכיטקטורה","q":"למה מקובל להשתמש בקישורים מנותבים (שכבה 3) בין Distribution ל־Core?","c":"אין לולאות שכבה 2, אין תלות ב־STP, ומתאפשר ECMP מהיר בעזרת פרוטוקול ניתוב","w":["זה זול יותר","אין צורך בכתובות","כדי להפעיל VTP"],"e":"פרוטוקול הניתוב מתכנס מהר יותר מ־STP, ומנצל את כל הקישורים במקביל."},{"id":"N04.39","lv":"CCNP","t":"ארכיטקטורה","q":"מה זה StackWise?","c":"חיבור כמה מתגים פיזיים בכבלי מחסנית, כך שהם מתנהגים ומנוהלים כמתג לוגי אחד","w":["פרוטוקול ניתוב","תקן PoE","מצב VTP"],"e":"במחסנית יש מתג ראשי (Active) וגיבוי (Standby), תצורה אחת ו־Control Plane אחד."},{"id":"N04.40","lv":"CCNP","t":"FHRP","q":"מה עושה הפקודה standby 1 preempt ב־HSRP?","c":"מאפשרת לנתב עם העדיפות הגבוהה יותר להשתלט מחדש על תפקיד ה־Active","w":["מכבה את HSRP","קובעת את העדיפות ל־255","יוצרת קבוצה חדשה"],"e":"בלי preempt, נתב שחוזר לפעולה לא לוקח בחזרה את תפקיד ה־Active, גם אם העדיפות שלו גבוהה."},{"id":"N04.41","lv":"CCNP","t":"FHRP","q":"מה כתובת ה־MAC הווירטואלית של HSRPv1, קבוצה 10?","c":"0000.0C07.AC0A","w":["0000.5E00.010A","0007.B400.0A01","0000.0C9F.F00A"],"e":"‏HSRPv1 משתמש ב־0000.0C07.ACxx, כאשר xx הוא מספר הקבוצה בהקסדצימלי. ‏HSRPv2 משתמש ב־0000.0C9F.Fxxx, ו־VRRP ב־0000.5E00.01xx."},{"id":"N04.42","lv":"CCNP","t":"FHRP","q":"מה מאפשר track בשילוב HSRP?","c":"הורדה של עדיפות ה־HSRP כשממשק או אובייקט שנמצא במעקב נופל","w":["מעקב אחרי כתובות MAC","רישום לוגים","שינוי כתובת ה־IP הווירטואלית"],"e":"למשל, אם ה־Uplink לספק נופל, העדיפות יורדת והנתב השני הופך ל־Active (בתנאי שמוגדר בו preempt)."},{"id":"N04.43","lv":"CCNP","t":"FHRP","q":"במה GLBP שונה מ־HSRP ומ־VRRP?","c":"GLBP מחלק עומסים בין כמה נתבים פעילים בו־זמנית, בעזרת כמה כתובות MAC וירטואליות","w":["GLBP הוא תקן פתוח","GLBP לא תומך בגיבוי","GLBP פועל רק ב־IPv6"],"e":"ה־AVG מחלק ללקוחות כתובות MAC של AVFs שונים, וכך כל הנתבים מעבירים תעבורה."},{"id":"N04.44","lv":"CCNP","t":"FHRP","q":"לאיזו כתובת Multicast שולח HSRPv2 את ההודעות שלו?","c":"224.0.0.102","w":["224.0.0.2","224.0.0.18","224.0.0.5"],"e":"‏HSRPv1 שולח ל־224.0.0.2, ‏HSRPv2 ל־224.0.0.102, ו־VRRP ל־224.0.0.18."},{"id":"N05.1","lv":"CCNP","t":"OSPF מרובה אזורים","q":"איזה סוג LSA מייצר כל נתב OSPF, ומתאר את הקישורים שלו באזור?","c":"Type 1 – Router LSA","w":["Type 2 – Network LSA","Type 3 – Summary LSA","Type 5 – External LSA"],"e":"‏Router LSA נשאר בתוך האזור, ומתאר את הממשקים של הנתב ואת השכנים שלו."},{"id":"N05.2","lv":"CCNP","t":"OSPF מרובה אזורים","q":"מי מייצר LSA מסוג 2?","c":"ה־DR של מקטע Broadcast","w":["כל ABR","ASBR","כל נתב"],"e":"‏Network LSA מתאר את המקטע ואת כל הנתבים שמחוברים אליו, ונוצר רק על ידי ה־DR."},{"id":"N05.3","lv":"CCNP","t":"OSPF מרובה אזורים","q":"איזה LSA ממיר ה־ABR באזור NSSA ל־Type 5?","c":"Type 7","w":["Type 3","Type 4","Type 1"],"e":"ה־ASBR בתוך ה־NSSA מייצר Type 7, וה־ABR מתרגם אותו ל־Type 5 לשאר הרשת."},{"id":"N05.4","lv":"CCNP","t":"OSPF מרובה אזורים","q":"איזה סוג אזור חוסם LSAs מסוג 3, 4 ו־5, ומקבל רק נתיב ברירת מחדל?","c":"Totally Stubby","w":["Stub","NSSA","Backbone"],"e":"‏area X stub no-summary (ב־ABR). זו הרחבה של Cisco ל־Stub, שבו עדיין מגיעים LSAs מסוג 3."},{"id":"N05.5","lv":"CCNP","t":"OSPF מרובה אזורים","q":"מה ההגבלה לגבי Area 0 ו־Stub?","c":"Area 0 לא יכול להיות Stub או NSSA","w":["Area 0 חייב להיות Stub","אין הגבלה","רק Area 0 יכול להיות NSSA"],"e":"עמוד השדרה חייב לשאת את כל סוגי ה־LSA."},{"id":"N05.6","lv":"CCNP","t":"OSPF מרובה אזורים","q":"מה סדר ההעדפה של OSPF בין סוגי נתיבים לאותו יעד?","c":"Intra-Area > Inter-Area > E1/N1 > E2/N2","w":["E2 > E1 > IA > O","לפי Cost בלבד","Inter-Area > Intra-Area"],"e":"‏OSPF מעדיף נתיב פנימי לאזור, בלי קשר ל־Cost. ה־Cost משמש רק להשוואה בתוך אותו סוג."},{"id":"N05.7","lv":"CCNP","t":"OSPF מרובה אזורים","q":"מה Cost ברירת המחדל של נתיב חיצוני שהוכנס ל־OSPF בעזרת redistribute?","c":"20 (‏E2), ו־1 לנתיב ברירת מחדל מ־default-information originate","w":["1 לכולם","110","0"],"e":"‏metric-type 1 גורם לנתיב להצטבר עם ה־Cost הפנימי (E1)."},{"id":"N05.8","lv":"CCNP","t":"OSPF מרובה אזורים","q":"למה חובה להוסיף subnets ב־redistribute ב־IOS ישן?","c":"בלעדיה מוכנסות רק רשתות מחלקתיות, ותתי־הרשתות לא נכנסות","w":["כדי להפעיל E1","כדי לסכם","זו מילה אופציונלית בלי השפעה"],"e":"ב־IOS XE חדש ההתנהגות הזו היא ברירת המחדל, אבל במבחנים עדיין כותבים subnets."},{"id":"N05.9","lv":"CCNP","t":"OSPF מרובה אזורים","q":"מה עושה area 1 range 10.10.0.0 255.255.252.0 not-advertise?","c":"ה־ABR לא מפרסם לאזורים אחרים את הרשתות שבטווח – סינון Type 3","w":["מסכם ומפרסם","מוחק את הרשתות מאזור 1","מסנן Type 5"],"e":"‏not-advertise הופך את פקודת הסיכום לכלי סינון ב־ABR."},{"id":"N05.10","lv":"CCNP","t":"OSPF מרובה אזורים","q":"מה ההבדל בין area filter-list לבין distribute-list in ב־OSPF?","c":"filter-list מסנן Type 3 ב־ABR ומשפיע על האזור כולו, ו־distribute-list in רק מונע התקנה ב־RIB המקומי, וה־LSA נשאר ב־LSDB","w":["אין הבדל","distribute-list מוחק LSAs מכל האזור","filter-list פועל רק ב־ASBR"],"e":"בתוך אזור, ה־LSDB חייב להיות זהה בכל הנתבים. לכן distribute-list רק משפיע על טבלת הניתוב המקומית."},{"id":"N05.11","lv":"CCNP","t":"OSPF מרובה אזורים","q":"מתי משתמשים ב־Virtual Link?","c":"כשאזור לא מחובר פיזית ל־Area 0, ומחברים אותו דרך אזור מעבר","w":["כדי להצפין OSPF","כדי לסכם נתיבים","בין שני ASBRs"],"e":"‏Virtual Link הוא מנהרה לוגית ששייכת ל־Area 0, דרך Transit Area שאינו Stub."},{"id":"N05.12","lv":"CCNP","t":"OSPF מרובה אזורים","q":"מה תפקיד LSA מסוג 4?","c":"לפרסם לאזורים אחרים איך מגיעים ל־ASBR","w":["לפרסם נתיבים חיצוניים","לתאר מקטע Broadcast","לפרסם נתיב ברירת מחדל"],"e":"ה־ABR מייצר Type 4, כדי שנתבים באזורים אחרים יוכלו לחשב את הנתיב ל־ASBR של נתיבי Type 5."},{"id":"N05.13","lv":"CCNP","t":"OSPF מתקדם","q":"באיזה מצב שכנות נתקעים בדרך כלל כשה־MTU לא תואם?","c":"ExStart / Exchange","w":["Init","2-Way","Loading"],"e":"הודעות DBD גדולות נזרקות בצד עם ה־MTU הקטן. הפתרונות: ip mtu זהה, או ip ospf mtu-ignore."},{"id":"N05.14","lv":"CCNP","t":"OSPF מתקדם","q":"איזו פקודה הופכת קישור Ethernet בין שני נתבים ל־Point-to-Point ב־OSPF?","c":"ip ospf network point-to-point","w":["ip ospf type p2p","ospf p2p enable","encapsulation ppp"],"e":"היתרונות: אין בחירת DR, אין Wait Timer, וההתכנסות מהירה יותר. צריך להגדיר בשני הצדדים."},{"id":"N05.15","lv":"CCNP","t":"OSPF מתקדם","q":"מה עושה ip ospf mtu-ignore?","c":"מבטל את בדיקת ה־MTU בהודעות DBD, כדי לאפשר שכנות למרות MTU שונה","w":["משנה את ה־MTU","מכבה OSPF","מסנן LSAs"],"e":"זה פתרון עוקף. הפתרון הנכון הוא ליישר את ה־MTU בשני הצדדים."},{"id":"N05.16","lv":"CCNP","t":"OSPF מתקדם","q":"באיזה פרק זמן OSPF מרענן כל LSA כברירת מחדל, גם בלי שינוי?","c":"כל 30 דקות","w":["כל 10 שניות","כל שעה","אף פעם"],"e":"‏LSRefreshTime הוא 1800 שניות. ‏MaxAge הוא 3600 שניות – ואז ה־LSA נמחק."},{"id":"N05.17","lv":"CCNP","t":"OSPF מתקדם","q":"מה תפקיד מספר הרצף (Seq#) ב־LSA?","c":"לזהות איזה עותק של ה־LSA חדש יותר","w":["לספור קפיצות","להצפין","לקבוע עלות"],"e":"עותק עם מספר רצף גבוה יותר מחליף את הישן ב־LSDB."},{"id":"N05.18","lv":"CCNP","t":"OSPF מתקדם","q":"איזו פקודה מציגה את ה־LSDB של OSPF?","c":"show ip ospf database","w":["show ip ospf neighbor","show ip route ospf","show ip protocols"],"e":"אפשר לסנן לפי סוג: router, ‏network, ‏summary, ‏asbr-summary, ‏external."},{"id":"N05.19","lv":"CCNP","t":"OSPF מתקדם","q":"ב־OSPFv3, איך מפעילים את הפרוטוקול על ממשק?","c":"ipv6 ospf 1 area 0 בממשק","w":["network 2001:db8::/64 area 0","router ospfv3 network","ipv6 enable ospf"],"e":"‏OSPFv3 לא משתמש בפקודת network – רק בהגדרה בממשק."},{"id":"N05.20","lv":"CCNP","t":"OSPF מתקדם","q":"באיזה סוג כתובות משתמש OSPFv3 כמקור להודעות Hello?","c":"Link-Local","w":["Global Unicast","Loopback","IPv4"],"e":"השכנויות ב־OSPFv3 נוצרות מעל כתובות Link-Local."},{"id":"N05.21","lv":"CCNP","t":"OSPF מתקדם","q":"מה צריך להיות זהה בכל נתבי האזור כדי שתהיה שכנות עם אזור Stub?","c":"דגל ה־Stub בהודעות Hello – כל הנתבים צריכים להגדיר area X stub","w":["רק ה־ABR צריך את ההגדרה","Router ID","Process ID"],"e":"נתב שלא הגדיר את האזור כ־Stub ידחה Hellos עם הדגל, ולכן תיווצר אי־התאמה."},{"id":"N05.22","lv":"CCNP","t":"OSPF מתקדם","q":"איזו שיטת אימות מומלצת ב־OSPFv2 ב־IOS מודרני?","c":"HMAC-SHA עם key chain (RFC 5709)","w":["טקסט גלוי","MD5 בלבד","אין צורך באימות"],"e":"‏MD5 נחשב חלש. IOS XE תומך ב־HMAC-SHA-256 בעזרת key chain."},{"id":"N05.23","lv":"CCNP","t":"OSPF מתקדם","q":"מה עושה timers throttle spf?","c":"קובע השהיות לפני הרצת SPF וביניהן, כדי לאזן בין מהירות התכנסות לעומס על המעבד","w":["מגדיר Hello","מגדיר Dead","מכבה SPF"],"e":"שלושת הערכים הם: השהיה ראשונית, השהיה בין ריצות, והשהיה מרבית."},{"id":"N05.24","lv":"CCNP","t":"OSPF מתקדם","q":"מה עושה BFD בשילוב OSPF?","c":"מזהה נפילת שכן במילי־שניות, ומודיע ל־OSPF – מהר בהרבה מטיימר ה־Dead","w":["מצפין את OSPF","מסכם נתיבים","בוחר DR"],"e":"‏Bidirectional Forwarding Detection פועל בנפרד מהפרוטוקול, וכמה פרוטוקולים יכולים להשתמש בו יחד."},{"id":"N05.25","lv":"CCNP","t":"EIGRP","q":"איזה AD מקבל נתיב EIGRP חיצוני (שהוכנס ב־Redistribution)?","c":"170","w":["90","110","5"],"e":"פנימי = 90, חיצוני = 170, נתיב סיכום = 5."},{"id":"N05.26","lv":"CCNP","t":"EIGRP","q":"אילו ערכי K פעילים כברירת מחדל ב־EIGRP?","c":"K1 ו־K3 – רוחב פס והשהיה","w":["K1 עד K5","K2 ו־K4","רק K1"],"e":"‏K2 (Load), ‏K4 ו־K5 (Reliability) מאופסים כברירת מחדל. ערכי ה־K חייבים להיות זהים בין שכנים."},{"id":"N05.27","lv":"CCNP","t":"EIGRP","q":"מה עושה variance 2 ב־EIGRP?","c":"מאפשר איזון עומסים גם על Feasible Successors שה־Metric שלהם עד פי 2 מהטוב ביותר","w":["מכפיל את ה־AD","מגדיר שני Successors בדיוק","משנה את ה־K"],"e":"רק נתיבים שעומדים ב־Feasibility Condition נכנסים לאיזון עומסים לא שווה."},{"id":"N05.28","lv":"CCNP","t":"EIGRP","q":"מה המשמעות של נתיב במצב Active בטבלת הטופולוגיה של EIGRP?","c":"הנתב איבד את ה־Successor, אין לו FS, והוא שולח Queries לשכנים","w":["הנתיב תקין ופעיל","הנתיב חסום","הנתיב מסוכם"],"e":"מצב Passive הוא יציב. מצב Active ארוך מדי מוביל ל־Stuck In Active (SIA)."},{"id":"N05.29","lv":"CCNP","t":"EIGRP","q":"מה עושה eigrp stub בנתב סניף?","c":"מודיע לשכנים לא לשלוח לו Queries, ומגביל את מה שהוא מפרסם","w":["מכבה EIGRP","הופך אותו ל־Hub","מסכם הכול"],"e":"‏Stub מצמצם את היקף ה־Queries (מונע SIA), ומתאים לסניפים בטופולוגיית Hub-and-Spoke."},{"id":"N05.30","lv":"CCNP","t":"EIGRP","q":"לאיזו כתובת Multicast נשלחות הודעות Hello של EIGRP?","c":"224.0.0.10","w":["224.0.0.5","224.0.0.9","224.0.0.2"],"e":"‏EIGRP משתמש ב־224.0.0.10, ובפרוטוקול IP 88."},{"id":"N05.31","lv":"CCNP","t":"EIGRP","q":"מה ההבדל בין EIGRP Classic ל־Named Mode?","c":"Named Mode מרכז את כל ההגדרות תחת router eigrp NAME ו־address-family, ותומך ב־Wide Metrics","w":["Named Mode לא תומך ב־IPv6","Classic חדש יותר","אין הבדל"],"e":"‏Wide Metrics (64 ביט) מאפשרים להבחין בין ממשקים מהירים מאוד."},{"id":"N05.32","lv":"CCNP","t":"EIGRP","q":"איזה פרוטוקול מבטיח מסירה אמינה של עדכוני EIGRP?","c":"RTP – Reliable Transport Protocol","w":["TCP","UDP","RSVP"],"e":"‏RTP של EIGRP משתמש במספרי רצף ובאישורים. הודעות Hello ו־ACK נשלחות בלי אמינות."},{"id":"N05.33","lv":"CCNP","t":"EIGRP","q":"מהו Hold Time של EIGRP כברירת מחדל בקישורי LAN?","c":"15 שניות","w":["40 שניות","180 שניות","5 שניות"],"e":"‏Hello הוא 5 שניות ו־Hold הוא 15. בקישורי WAN איטיים הערכים הם 60 ו־180."},{"id":"N05.34","lv":"CCNP","t":"EIGRP","q":"מה הסיבה הנפוצה לכך ששני נתבי EIGRP לא יוצרים שכנות?","c":"מספר AS שונה, ערכי K שונים, או תת־רשת שונה בממשק המשותף","w":["Router ID זהה בלבד","Hello Timer שונה","Hostname שונה"],"e":"ב־EIGRP, טיימרי Hello/Hold לא חייבים להתאים. ה־AS, ה־K והתת־רשת – חייבים."},{"id":"N05.35","lv":"CCNP","t":"EIGRP","q":"איך מסכמים נתיבים ב־EIGRP Classic בממשק יוצא?","c":"ip summary-address eigrp 100 10.1.0.0 255.255.0.0","w":["area range","summary-address בתהליך","aggregate-address"],"e":"הסיכום מוגדר בממשק, ונוצר נתיב ל־Null0 עם AD 5."},{"id":"N05.36","lv":"CCNP","t":"השוואת IGP","q":"איזה פרוטוקול ניתוב משתמש באלגוריתם DUAL?","c":"EIGRP","w":["OSPF","RIP","IS-IS"],"e":"‏DUAL מבטיח נתיבים ללא לולאות, ומאפשר גיבוי מיידי בעזרת Feasible Successor."},{"id":"N05.37","lv":"CCNP","t":"השוואת IGP","q":"איזה IGP מבוסס Link State, משמש בעיקר ספקים, ורץ ישירות מעל שכבה 2 (לא מעל IP)?","c":"IS-IS","w":["OSPF","EIGRP","BGP"],"e":"‏IS-IS משתמש ב־CLNS, ולכן הוא לא תלוי ב־IP. ה־AD שלו הוא 115."},{"id":"N05.38","lv":"CCNP","t":"השוואת IGP","q":"מה מאפשרת הפקודה maximum-paths 8?","c":"התקנה של עד 8 נתיבים שווי עלות (ECMP) לאותו יעד","w":["8 שכנים לכל היותר","8 אזורים","8 ממשקים פסיביים"],"e":"ברירת המחדל ב־IOS היא 4 נתיבים לרוב הפרוטוקולים."},{"id":"N05.39","lv":"CCNP","t":"Redistribution","q":"מה הבעיה העיקרית ב־Mutual Redistribution בשתי נקודות בין שני פרוטוקולים?","c":"לולאות ניתוב, ובחירה בנתיב לא אופטימלי בגלל הבדלי AD","w":["אין שום בעיה","עומס CPU בלבד","אובדן כתובות MAC"],"e":"הפתרון: Route Tags, ‏route-maps שמסננים לפי Tag, או שינוי AD."},{"id":"N05.40","lv":"CCNP","t":"Redistribution","q":"למה צריך metric ב־redistribute ospf 1 לתוך RIP או EIGRP?","c":"כי ל־RIP ול־EIGRP אין דרך לתרגם את ה־Cost של OSPF, וברירת המחדל היא Infinity – כלומר הנתיבים לא ייכנסו","w":["כדי לשנות את ה־AD","אין צורך בכך","כדי להצפין"],"e":"ב־EIGRP מגדירים את חמשת ערכי ה־Metric (או default-metric). ב־RIP מגדירים Hop Count."},{"id":"N05.41","lv":"CCNP","t":"Redistribution","q":"מהו Route Tag?","c":"ערך מספרי שמצמידים לנתיב ב־Redistribution, ומשמש לזיהוי ולסינון בנקודות אחרות","w":["סיסמת אימות","מספר AS","סוג LSA"],"e":"מגדירים ב־route-map עם set tag, ומסננים עם match tag."},{"id":"N05.42","lv":"CCNP","t":"Redistribution","q":"איזה AD קובע הנתב לנתיבים שהוכנסו ל־OSPF ממקור חיצוני?","c":"110 – כמו כל נתיב OSPF, אלא אם שונה עם distance ospf external","w":["170","20","1"],"e":"בניגוד ל־EIGRP, ב־OSPF ה־AD של נתיבים חיצוניים זהה כברירת מחדל לזה של נתיבים פנימיים."},{"id":"N05.43","lv":"CCNP","t":"Redistribution","q":"מה עושה distribute-list ב־EIGRP?","c":"מסנן אילו נתיבים מתקבלים או מפורסמים, לפי ACL או Prefix-List","w":["מחלק עומסים","יוצר שכנים","משנה Metric"],"e":"לדוגמה: distribute-list prefix FILTER out g0/1."},{"id":"N05.44","lv":"CCNP","t":"Redistribution","q":"מה המשמעות של ip prefix-list LIST permit 10.0.0.0/8 ge 24 le 24?","c":"התאמה לכל קידומת ‎/24 בדיוק, בתוך 10.0.0.0/8","w":["התאמה ל־10.0.0.0/8 בלבד","כל קידומת עד ‎/24","כל קידומת מ־‎/8 עד ‎/24"],"e":"‏ge ו־le מגדירים טווח של אורכי מסכה, בתוך הקידומת הבסיסית."},{"id":"N06.1","lv":"CCNP","t":"BGP","q":"באיזה פורט TCP עובד BGP?","c":"179","w":["89","520","646"],"e":"‏BGP משתמש ב־TCP 179 לחיבור Unicast בין שכנים (Peers). הוא לא משתמש ב־Multicast."},{"id":"N06.2","lv":"CCNP","t":"BGP","q":"מה ה־AD של eBGP ושל iBGP?","c":"eBGP = 20, ‏iBGP = 200","w":["eBGP = 200, ‏iBGP = 20","שניהם 110","eBGP = 90, ‏iBGP = 170"],"e":"נתיב מספק חיצוני מקבל עדיפות על IGP, ונתיב iBGP פחות אמין מ־IGP פנימי."},{"id":"N06.3","lv":"CCNP","t":"BGP","q":"איזה סוג פרוטוקול הוא BGP?","c":"Path Vector","w":["Link State","Distance Vector פשוט","Hybrid של Cisco"],"e":"‏BGP מפרסם את רשימת ה־AS שהנתיב עובר בהם (AS_PATH), ומשתמש בה גם למניעת לולאות."},{"id":"N06.4","lv":"CCNP","t":"BGP","q":"איך BGP מונע לולאות בין מערכות אוטונומיות?","c":"נתב דוחה עדכון שבו מופיע ה־AS שלו עצמו ב־AS_PATH","w":["Split Horizon","TTL","STP"],"e":"אם מספר ה־AS המקומי כבר נמצא ברשימה, העדכון חזר אליו, ולכן הוא נזרק."},{"id":"N06.5","lv":"CCNP","t":"BGP","q":"מה כלל ה־Split Horizon של iBGP?","c":"נתיב שנלמד משכן iBGP לא מפורסם לשכן iBGP אחר","w":["נתיב לא חוזר לממשק שממנו נלמד","אין כלל כזה","נתיב eBGP לא מפורסם ל־iBGP"],"e":"לכן נדרש Full Mesh של iBGP, או Route Reflectors, או Confederations."},{"id":"N06.6","lv":"CCNP","t":"BGP","q":"מהו מצב ה־BGP שבו השכנות עובדת ומתחלפים נתיבים?","c":"Established","w":["Active","Connect","OpenSent"],"e":"מצב Active, למרות השם, פירושו שהנתב מנסה ליצור חיבור TCP ונכשל. ‏Established הוא המצב התקין."},{"id":"N06.7","lv":"CCNP","t":"BGP","q":"מה עושה network 10.1.0.0 mask 255.255.0.0 תחת router bgp?","c":"מפרסם את הקידומת, אם היא קיימת בטבלת הניתוב עם אותה מסכה בדיוק","w":["מפעיל BGP על ממשקים","יוצר שכן","מסכם אוטומטית"],"e":"בניגוד ל־OSPF, הפקודה network ב־BGP לא מפעילה ממשקים. היא מכניסה נתיב ל־BGP, אם הוא קיים ב־RIB."},{"id":"N06.8","lv":"CCNP","t":"BGP","q":"איזה מאפיין BGP נבדק ראשון בתהליך בחירת הנתיב ב־Cisco?","c":"Weight (הגבוה מנצח)","w":["AS_PATH","MED","Local Preference"],"e":"הסדר: Weight, ‏Local Pref, נתיב שמקורו מקומי, ‏AS_PATH קצר, ‏Origin, ‏MED, ‏eBGP על פני iBGP, ‏IGP Metric ל־Next-Hop, ואחריהם שוברי שוויון."},{"id":"N06.9","lv":"CCNP","t":"BGP","q":"לאיזה היקף משפיע Local Preference?","c":"לכל הנתבים בתוך ה־AS – ומשפיע על בחירת נקודת היציאה","w":["רק לנתב המקומי","לשכנים ב־AS אחרים","לכל האינטרנט"],"e":"‏Local Pref (ברירת מחדל 100, הגבוה מנצח) מועבר ב־iBGP. ‏Weight הוא מקומי לנתב בלבד."},{"id":"N06.10","lv":"CCNP","t":"BGP","q":"איזה מאפיין BGP משפיע על התעבורה הנכנסת מ־AS שכן, כשיש כמה קישורים אליו?","c":"MED (הנמוך עדיף)","w":["Weight","Local Preference","Origin"],"e":"‏MED נשלח לשכן ומציע לו דרך איזה קישור להיכנס. ‏AS_PATH Prepending משמש לאותה מטרה ברמה רחבה יותר."},{"id":"N06.11","lv":"CCNP","t":"BGP","q":"מה עושה neighbor 10.1.1.1 next-hop-self?","c":"הנתב מחליף את ה־Next-Hop בנתיבים שהוא מעביר לשכן ה־iBGP בכתובת שלו עצמו","w":["הנתב מפרסם רק את עצמו","יוצר שכנות eBGP","מסנן נתיבים"],"e":"בלי זה, נתיבי eBGP מגיעים ל־iBGP עם Next-Hop חיצוני, שאולי לא נגיש בתוך ה־AS."},{"id":"N06.12","lv":"CCNP","t":"BGP","q":"למה משתמשים ב־update-source loopback0 בשכנות iBGP?","c":"כדי שהשכנות תישען על Loopback יציב, שנגיש דרך כמה נתיבים ב־IGP","w":["כדי להצפין","כדי לשנות את ה־AS","כדי להפעיל Multicast"],"e":"אם קישור פיזי נופל, החיבור לכתובת ה־Loopback נשמר דרך נתיב חלופי."},{"id":"N06.13","lv":"CCNP","t":"BGP","q":"מה נדרש כדי ליצור eBGP בין כתובות Loopback, ולא בין כתובות מחוברות ישירות?","c":"ebgp-multihop (או disable-connected-check), יחד עם update-source","w":["רק network","next-hop-self","route-reflector-client"],"e":"ה־TTL של חבילות eBGP הוא 1 כברירת מחדל, ולכן צריך להגדיל אותו."},{"id":"N06.14","lv":"CCNP","t":"BGP","q":"איזו פקודה מציגה את מצב השכנים ב־BGP בתמצית?","c":"show ip bgp summary","w":["show ip bgp neighbors brief","show bgp peers","show ip protocols bgp"],"e":"העמודה State/PfxRcd מציגה מספר (כמות קידומות) כשהשכנות Established, ומצב (למשל Active) כשלא."},{"id":"N06.15","lv":"CCNP","t":"BGP","q":"מה תפקיד Route Reflector?","c":"להחזיר נתיבי iBGP ללקוחות שלו, וכך לחסוך את הצורך ב־Full Mesh","w":["לסכם נתיבים","לבחור DR","לתרגם כתובות"],"e":"הלקוחות מתחברים ל־RR בלבד, וה־RR מעביר ביניהם נתיבים, בניגוד לכלל ה־Split Horizon של iBGP."},{"id":"N06.16","lv":"CCNP","t":"BGP","q":"מה ההבדל בין ASN פרטי לציבורי?","c":"ASN פרטי (‏64512–65534, ובטווח של 32 ביט: 4200000000 ומעלה) לא מפורסם באינטרנט","w":["אין הבדל","ASN פרטי מהיר יותר","ASN ציבורי רק ל־iBGP"],"e":"‏ASN פרטי מתאים לתוך ארגון, או לשכנות עם ספק שמסיר אותו מה־AS_PATH."},{"id":"N06.17","lv":"CCNP","t":"BGP","q":"איך מפרסמים נתיב BGP מסכם, ומסתירים את הרשתות הספציפיות?","c":"aggregate-address 10.0.0.0 255.0.0.0 summary-only","w":["area range","summary-address","network auto-summary"],"e":"בלי summary-only, גם הנתיבים הספציפיים ממשיכים להתפרסם לצד הסיכום."},{"id":"N06.18","lv":"CCNP","t":"BGP","q":"באיזה Address Family מגדירים שכני BGP ל־IPv6?","c":"address-family ipv6 unicast, עם neighbor X activate","w":["router bgp ipv6","ipv6 bgp enable","address-family vpnv4"],"e":"‏MP-BGP מפריד בין משפחות כתובות. כל שכן צריך activate במשפחה שבה הוא משתתף."},{"id":"N06.19","lv":"CCNP","t":"VRF","q":"מה מאפשר VRF-Lite?","c":"כמה טבלאות ניתוב נפרדות על אותו נתב – הפרדה לוגית, גם עם כתובות חופפות","w":["הצפנה בין נתבים","איזון עומסים","תרגום כתובות"],"e":"כל VRF הוא \"נתב וירטואלי\". ממשקים משויכים אליו בפקודה vrf forwarding."},{"id":"N06.20","lv":"CCNP","t":"VRF","q":"מה קורה לכתובת ה־IP של ממשק כשמשייכים אותו ל־VRF?","c":"הכתובת נמחקת, וצריך להגדיר אותה מחדש","w":["הכתובת נשמרת","הכתובת מוכפלת","הממשק נכבה לצמיתות"],"e":"IOS מציגה הודעה: ‏\"% Interface … IPv4 disabled and address(es) removed\"."},{"id":"N06.21","lv":"CCNP","t":"VRF","q":"איך בודקים ping בתוך VRF בשם CUST-A?","c":"ping vrf CUST-A 10.1.1.1","w":["ping 10.1.1.1 vrf","ping CUST-A","vrf ping 10.1.1.1"],"e":"רוב פקודות ה־show וה־ping מקבלות את הפרמטר vrf."},{"id":"N06.22","lv":"CCNP","t":"IP SLA","q":"מה מאפשר IP SLA בשילוב Track על נתיב סטטי?","c":"להוציא את הנתיב מהטבלה כשיעד מרוחק לא עונה, גם כשהממשק המקומי נשאר up","w":["להצפין את הנתיב","לשנות את ה־AD","לסכם נתיבים"],"e":"‏ip sla שולח בדיקות (ICMP echo), ‏track עוקב אחרי הנגישות, ו־ip route … track 1 תלוי בתוצאה."},{"id":"N06.23","lv":"CCNP","t":"IP SLA","q":"איזו פקודה מפעילה מדידת IP SLA מספר 1 מיד ולצמיתות?","c":"ip sla schedule 1 life forever start-time now","w":["ip sla 1 start","ip sla enable 1","track 1 ip sla start"],"e":"בלי schedule המדידה מוגדרת אבל לא רצה."},{"id":"N06.25","lv":"CCNP","t":"PBR","q":"מה קורה ב־PBR לחבילה שלא מתאימה לשום בלוק permit ב־route-map?","c":"היא מנותבת כרגיל, לפי טבלת הניתוב","w":["היא נזרקת","היא נשלחת ל־Null0","היא נשלחת ל־CPU"],"e":"זה ההבדל מ־ACL לסינון: ב־PBR, \"אין התאמה\" פירושו \"בלי מדיניות\"."},{"id":"N06.26","lv":"CCNP","t":"PBR","q":"מה ההבדל בין set ip next-hop ל־set ip default next-hop?","c":"default next-hop פועל רק כשאין לחבילה נתיב ספציפי בטבלת הניתוב","w":["אין הבדל","default next-hop גובר תמיד","next-hop פועל רק ב־IPv6"],"e":"‏set ip next-hop גובר על טבלת הניתוב. ‏default next-hop משמש רק כ\"מוצא אחרון\"."},{"id":"N06.27","lv":"CCNP","t":"PBR","q":"איזו פקודה מציגה כמה חבילות נותבו לפי route-map?","c":"show route-map","w":["show ip policy counters","show access-lists","show ip route policy"],"e":"בפלט מופיעה שורה של Policy routing matches, עם מספר חבילות ובתים."},{"id":"N06.28","lv":"CCNP","t":"Multicast","q":"איזה פרוטוקול משמש מארחים להצטרף לקבוצת Multicast ב־IPv4?","c":"IGMP","w":["PIM","MLD","MSDP"],"e":"‏IGMP פועל בין מארח לנתב. ‏PIM פועל בין נתבים. ‏MLD הוא המקבילה של IGMP ב־IPv6."},{"id":"N06.29","lv":"CCNP","t":"Multicast","q":"מה עושה IGMP Snooping במתג?","c":"מעביר Multicast רק לפורטים שבהם יש מארחים שהצטרפו לקבוצה","w":["מציף Multicast לכל הפורטים","חוסם Multicast","מתרגם Multicast ל־Unicast"],"e":"המתג \"מצותת\" להודעות IGMP Join, ובונה טבלה של קבוצות ופורטים."},{"id":"N06.30","lv":"CCNP","t":"Multicast","q":"מה תפקיד ה־RP ב־PIM Sparse Mode?","c":"נקודת מפגש שבה מקורות ומקבלים נפגשים לפני שנבנה עץ ישיר","w":["נתב שחוסם Multicast","שרת IGMP","נתב DR בלבד"],"e":"ב־PIM-SM המקבלים מצטרפים לעץ משותף (‏*,G) שמתחיל ב־RP, ויכולים לעבור לעץ מקור (‏S,G)."},{"id":"N06.31","lv":"CCNP","t":"Multicast","q":"מה בודק RPF (Reverse Path Forwarding) ב־Multicast?","c":"שחבילת Multicast הגיעה בממשק שבו הנתב היה שולח Unicast חזרה למקור","w":["שהיעד נגיש","שהקבוצה חוקית","שה־TTL תקין"],"e":"‏RPF מונע לולאות Multicast. חבילה שמגיעה מממשק אחר נזרקת."},{"id":"N06.32","lv":"CCNP","t":"מנהרות ו־VPN","q":"מה החיסרון של מנהרת GRE לבדה?","c":"אין בה הצפנה","w":["היא לא תומכת ב־Multicast","היא לא עובדת מעל IP","היא לא תומכת בפרוטוקולי ניתוב"],"e":"‏GRE עוטף כל פרוטוקול, כולל Multicast ו־OSPF, אבל לא מצפין. לכן משלבים GRE over IPsec."},{"id":"N06.33","lv":"CCNP","t":"מנהרות ו־VPN","q":"מה גודל התקורה של כותרת GRE בסיסית מעל IPv4?","c":"24 בתים (‏20 IP ועוד 4 GRE)","w":["8 בתים","40 בתים","60 בתים"],"e":"לכן מקובל להוריד את ה־MTU במנהרה ל־1476 (ועם IPsec לערך נמוך יותר), ולהגדיר ip tcp adjust-mss."},{"id":"N06.34","lv":"CCNP","t":"מנהרות ו־VPN","q":"איזה פרוטוקול IPsec מספק גם הצפנה וגם שלמות?","c":"ESP","w":["AH","IKE","GRE"],"e":"‏AH מספק אימות ושלמות בלבד, בלי הצפנה, ולא עובד עם NAT. ‏ESP מספק את כל השלושה."},{"id":"N06.35","lv":"CCNP","t":"מנהרות ו־VPN","q":"מה התפקיד של IKE ב־IPsec?","c":"ניהול משא ומתן על הפרמטרים והמפתחות, והקמת ה־Security Associations","w":["הצפנת הנתונים עצמם","תרגום כתובות","ניתוב"],"e":"‏IKEv1 עובר שני שלבים (Phase 1 ו־Phase 2). ‏IKEv2 יעיל יותר. שניהם עובדים ב־UDP 500, וב־4500 כשיש NAT-T."},{"id":"N06.36","lv":"CCNP","t":"מנהרות ו־VPN","q":"מה ההבדל בין Tunnel Mode ל־Transport Mode ב־IPsec?","c":"Tunnel עוטף את כל חבילת ה־IP המקורית בכותרת חדשה, ו־Transport מגן רק על המטען","w":["אין הבדל","Transport מוסיף כותרת חדשה","Tunnel לא מצפין"],"e":"‏Site-to-Site משתמש ב־Tunnel Mode. ‏Transport Mode נפוץ עם GRE over IPsec."},{"id":"N06.37","lv":"CCNP","t":"מנהרות ו־VPN","q":"מה מאפשר DMVPN?","c":"רשת Hub-and-Spoke שבה סניפים יכולים להקים מנהרות ישירות ביניהם, באופן דינמי","w":["רק מנהרה אחת קבועה","הצפנה בשכבה 2","תרגום כתובות"],"e":"‏DMVPN משלב mGRE, ‏NHRP ו־IPsec. בשלב 3 (Phase 3) המנהרות הישירות בין הסניפים נוצרות לפי הצורך."},{"id":"N06.38","lv":"CCNP","t":"מנהרות ו־VPN","q":"מה היתרון של VXLAN על VLAN?","c":"מזהה של 24 ביט (כ־16 מיליון סגמנטים), ושכבה 2 שנמתחת מעל רשת שכבה 3","w":["הצפנה מובנית","מהירות גבוהה יותר תמיד","אין צורך ברשת IP"],"e":"‏VXLAN עוטף מסגרות Ethernet ב־UDP 4789. נקודות הקצה נקראות VTEP."},{"id":"N06.39","lv":"CCNP","t":"מנהרות ו־VPN","q":"מה ה־Control Plane הנפוץ ל־VXLAN בארכיטקטורות מודרניות?","c":"BGP EVPN","w":["OSPF בלבד","STP","VTP"],"e":"‏EVPN מפיץ ב־BGP כתובות MAC ו־IP, במקום להסתמך על Flood and Learn."},{"id":"N06.40","lv":"CCNP","t":"מנהרות ו־VPN","q":"באיזה פרוטוקול משתמש LISP כדי להפריד בין זהות למיקום?","c":"EID (זהות) ו־RLOC (מיקום), עם Map-Server ו־Map-Resolver","w":["VLAN ו־VTP","MAC ו־ARP","AS ו־BGP"],"e":"‏LISP הוא ה־Control Plane של SD-Access. ה־Data Plane שלו הוא VXLAN."},{"id":"N06.41","lv":"CCNP","t":"NAT מתקדם","q":"מה עושה ip nat inside source static tcp 192.168.1.10 80 203.0.113.5 80?","c":"Port Forwarding – חיבורים מבחוץ ל־203.0.113.5:80 מועברים לשרת הפנימי 192.168.1.10:80","w":["מתרגם את כל הרשת","חוסם פורט 80","PAT לכל המשתמשים"],"e":"‏Static NAT עם פורטים מאפשר לפרסם שירות פנימי בודד בכתובת הציבורית."},{"id":"N06.42","lv":"CCNP","t":"NAT מתקדם","q":"איזו פקודה מוחקת את כל התרגומים הדינמיים של NAT?","c":"clear ip nat translation *","w":["no ip nat","reset nat","clear nat all"],"e":"שימושי אחרי שינוי ב־ACL או ב־Pool, כדי שתרגומים ישנים לא יישארו פעילים."},{"id":"N06.43","lv":"CCNP","t":"NAT מתקדם","q":"מה NAT64 מאפשר?","c":"למארחים ב־IPv6 בלבד לתקשר עם שרתים ב־IPv4","w":["תרגום בין שני מארחי IPv4","הצפנת IPv6","תרגום MAC"],"e":"בדרך כלל NAT64 משולב עם DNS64, שמסנתז רשומות AAAA מתוך רשומות A."},{"id":"N07.1","lv":"CCNP","t":"AAA ו־TACACS+","q":"איזה פרוטוקול AAA מתאים להרשאת פקודות (Command Authorization) בניהול ציוד רשת?","c":"TACACS+","w":["RADIUS","LDAP","Kerberos"],"e":"‏TACACS+ מפריד בין אימות, הרשאה ותיעוד, ומאפשר לבדוק כל פקודה מול השרת."},{"id":"N07.2","lv":"CCNP","t":"AAA ו־TACACS+","q":"מה עושה aaa authorization exec default group tacacs+ local?","c":"קובע את רמת ההרשאה של המשתמש (למשל privilege 15) לפי השרת, ואם השרת לא זמין – לפי המסד המקומי","w":["מאמת סיסמאות בלבד","מתעד פקודות","מכבה את AAA"],"e":"‏Exec Authorization מגדיר מה המשתמש מקבל אחרי שהוא מתחבר, למשל רמת הרשאה או autocommand."},{"id":"N07.3","lv":"CCNP","t":"AAA ו־TACACS+","q":"מה עושה aaa accounting commands 15 default start-stop group tacacs+?","c":"שולח לשרת רשומה על כל פקודה ברמה 15 שהמשתמשים מריצים","w":["חוסם פקודות ברמה 15","מאמת פקודות","מוחק את ההיסטוריה"],"e":"זה יוצר Audit Trail מלא: מי הריץ מה, ומתי."},{"id":"N07.4","lv":"CCNP","t":"AAA ו־TACACS+","q":"מה עושה aaa new-model בפועל ברגע ההקלדה?","c":"מעביר את כל הקווים לאימות לפי Method Lists – ברירת המחדל היא local","w":["מוחק את כל המשתמשים","מפעיל RADIUS","מאתחל את ההתקן"],"e":"לכן יוצרים משתמש מקומי לפני ההפעלה, כדי לא לנעול את עצמך בחוץ."},{"id":"N07.5","lv":"CCNP","t":"AAA ו־TACACS+","q":"מה מאפשר CoA (Change of Authorization) ב־RADIUS?","c":"לשרת לשנות הרשאות של סשן קיים, למשל VLAN או ACL, בלי שהמשתמש יתחבר מחדש","w":["להצפין סיסמאות","לאפס את המתג","לגבות תצורה"],"e":"‏CoA מוגדר ב־RFC 5176, ונפוץ ב־Cisco ISE, למשל להעברת משתמש ל־VLAN הסגר."},{"id":"N07.6","lv":"CCNP","t":"אבטחת התקנים","q":"מה תפקיד CoPP (Control Plane Policing)?","c":"להגביל את קצב התעבורה שמגיעה ל־CPU של הנתב, כהגנה מפני DoS","w":["לסנן את תעבורת המשתמשים","להצפין","לתעדף קול"],"e":"‏CoPP מוחל על ה־control-plane בעזרת MQC, למשל כדי להגביל ICMP, ‏SSH ו־SNMP."},{"id":"N07.7","lv":"CCNP","t":"אבטחת התקנים","q":"איזה סוג סיסמה ב־IOS משתמש ב־scrypt?","c":"Type 9","w":["Type 8","Type 5","Type 7"],"e":"‏Type 8 = ‏PBKDF2-SHA256, ‏Type 9 = ‏scrypt (המומלץ), ‏Type 5 = ‏MD5, ‏Type 7 = הצפנה הפיכה וחלשה."},{"id":"N07.8","lv":"CCNP","t":"אבטחת התקנים","q":"מה מאפשרת הפקודה privilege exec level 5 show running-config?","c":"משתמשים ברמת הרשאה 5 יוכלו להריץ את הפקודה","w":["מוחקת את הפקודה","מצפינה את התצורה","מגבילה את רמה 15"],"e":"רמות 2–14 ריקות כברירת מחדל, והמנהל מעביר אליהן פקודות לפי הצורך."},{"id":"N07.9","lv":"CCNP","t":"אבטחת התקנים","q":"מה ההבדל בין Parser View (‏Role-Based CLI) לבין Privilege Levels?","c":"Views מאפשרים בחירה מדויקת של פקודות, בלי היררכיה מספרית שבה רמה גבוהה כוללת את כל מה שמתחתיה","w":["אין הבדל","Views לא דורשים AAA","Privilege Levels חדשים יותר"],"e":"‏Views דורשים aaa new-model ו־enable view. כל View מגדיר commands include."},{"id":"N07.10","lv":"CCNP","t":"אבטחת התקנים","q":"מה עושה login block-for 120 attempts 3 within 60?","c":"אחרי 3 ניסיונות התחברות כושלים בתוך 60 שניות, חוסם התחברויות ל־120 שניות","w":["נועל משתמש לצמיתות","מגביל ל־3 משתמשים","מוחק משתמשים"],"e":"זו הגנה מפני Brute Force. ‏login quiet-mode access-class מאפשר למנהלים להתחבר גם בזמן החסימה."},{"id":"N07.11","lv":"CCNP","t":"QoS","q":"מה המודל של Cisco להגדרת QoS בפקודות class-map, ‏policy-map ו־service-policy?","c":"MQC – Modular QoS CLI","w":["CBWFQ בלבד","IntServ","RSVP"],"e":"‏class-map מסווג, ‏policy-map מגדיר פעולות, ו־service-policy מחיל את המדיניות על ממשק בכיוון מסוים."},{"id":"N07.12","lv":"CCNP","t":"QoS","q":"מה ההבדל בין LLQ ל־CBWFQ?","c":"LLQ מוסיף ל־CBWFQ תור עדיפות קפדני (Priority), לתעבורה רגישה כמו קול","w":["אין הבדל","CBWFQ מהיר יותר","LLQ לא מבטיח רוחב פס"],"e":"‏priority בתוך policy-map יוצר את ה־LLQ, עם Policing מובנה כדי שהתור לא ירעיב את השאר."},{"id":"N07.13","lv":"CCNP","t":"QoS","q":"מה עושה WRED?","c":"זורק חבילות TCP באופן אקראי לפני שהתור מתמלא, כדי למנוע Global Synchronization","w":["מתעדף קול","מצפין","מגביל ל־1 Mbps"],"e":"‏WRED זורק יותר מתעבורה בעדיפות נמוכה (לפי DSCP). זה גורם ל־TCP להאט בהדרגה, ולא כל הזרמים בבת אחת."},{"id":"N07.14","lv":"CCNP","t":"QoS","q":"באיזה שדה מסמנים QoS בשכבה 2 (בתג 802.1Q)?","c":"PCP / CoS – שלושה ביטים","w":["DSCP – שישה ביטים","TTL","EXP"],"e":"‏CoS (‏0–7) נמצא בתג 802.1Q. ‏DSCP נמצא בכותרת IP, ו־EXP/TC בתווית MPLS."},{"id":"N07.15","lv":"CCNP","t":"QoS","q":"מה פירוש Trust Boundary?","c":"הנקודה ברשת שממנה מאמינים לסימוני QoS שמגיעים מההתקן","w":["גבול רשת האורחים","גבול ה־VLAN","גבול ה־Firewall"],"e":"בדרך כלל מאמינים לטלפון IP (‏mls qos trust cos), ולא למחשב של המשתמש."},{"id":"N07.16","lv":"CCNP","t":"ניטור","q":"מה מספק NetFlow?","c":"סטטיסטיקה על זרמי תעבורה – מי מדבר עם מי, באיזה פורט, וכמה","w":["העתק מלא של החבילות","התראות SNMP","זמן מדויק"],"e":"‏Flow מזוהה לפי שבעה שדות (מקור, יעד, פורטים, פרוטוקול, ToS וממשק). ‏Flexible NetFlow מאפשר להגדיר את השדות."},{"id":"N07.17","lv":"CCNP","t":"ניטור","q":"מה ההבדל בין NetFlow לבין SPAN?","c":"NetFlow מייצא מטא־נתונים מסוכמים על זרמים, ו־SPAN משכפל את החבילות עצמן","w":["אין הבדל","SPAN מסכם","NetFlow משכפל חבילות"],"e":"‏SPAN מתאים לניתוח מלא ב־Wireshark. ‏NetFlow מתאים לניתוח מגמות ולאבטחה."},{"id":"N07.18","lv":"CCNP","t":"ניטור","q":"מה עושה Conditional Debugging, למשל debug condition interface g0/1?","c":"מגביל את פלט ה־debug לתעבורה שעומדת בתנאי, וכך מקטין עומס ורעש","w":["מכבה את כל ה־debug","שומר debug לקובץ","מפעיל debug לכל הממשקים"],"e":"זה קריטי בנתבי ייצור, כי debug לא ממוקד עלול להעמיס על המעבד."},{"id":"N07.19","lv":"CCNP","t":"אוטומציה","q":"באיזה פורט עובד NETCONF מעל SSH?","c":"830","w":["22","443","161"],"e":"‏NETCONF משתמש ב־TCP 830 מעל SSH, ומחליף הודעות XML עם פעולות RPC כמו get-config ו־edit-config."},{"id":"N07.20","lv":"CCNP","t":"אוטומציה","q":"מה ההבדל בין NETCONF ל־RESTCONF?","c":"RESTCONF מספק גישה למודלי YANG מעל HTTPS בפעולות REST, בפורמט JSON או XML","w":["RESTCONF עובד מעל SSH בלבד","NETCONF משתמש ב־JSON בלבד","אין הבדל"],"e":"שניהם מבוססים על YANG. ‏NETCONF תומך גם ב־candidate datastore ובעסקאות."},{"id":"N07.21","lv":"CCNP","t":"אוטומציה","q":"מה זה YANG?","c":"שפת מידול נתונים שמתארת את מבנה התצורה ואת המצב של התקני רשת","w":["פרוטוקול תעבורה","שפת תכנות כללית","פורמט הצפנה"],"e":"‏YANG מגדיר את המבנה. ‏NETCONF ו־RESTCONF הם הפרוטוקולים שמעבירים את הנתונים לפיו."},{"id":"N07.22","lv":"CCNP","t":"אוטומציה","q":"מה קוד ההחזרה של HTTP כשבקשת REST יצרה משאב בהצלחה?","c":"201 Created","w":["200 OK","404 Not Found","500 Internal Server Error"],"e":"‏2xx = הצלחה, ‏4xx = שגיאת לקוח (‏401 = לא מאומת, ‏404 = לא נמצא), ‏5xx = שגיאת שרת."},{"id":"N07.23","lv":"CCNP","t":"אוטומציה","q":"מה ההבדל בין Model-Driven Telemetry לבין SNMP Polling?","c":"בטלמטריה ההתקן דוחף (Push) נתונים ברציפות או כשיש שינוי, וב־SNMP השרת שואל כל פרק זמן","w":["אין הבדל","SNMP מהיר יותר","טלמטריה לא משתמשת ב־YANG"],"e":"‏MDT מבוסס על מודלי YANG, ומועבר ב־gRPC או NETCONF – ביעילות ובזמן אמת."},{"id":"N07.24","lv":"CCNP","t":"אוטומציה","q":"מה מבנה ה־Python הנכון לבדוק אם ה־status של ממשק בתוך מילון data הוא up?","c":"if data[\"status\"] == \"up\":","w":["if data.status = \"up\"","if (data[status] -eq up)","if data->status == up"],"e":"מילון ב־Python נקרא בסוגריים מרובעים עם מפתח מחרוזת, והשוואה נכתבת ב־==."},{"id":"N07.25","lv":"CCNP","t":"אוטומציה","q":"מה תפקידה של ספריית Netmiko ב־Python?","c":"להתחבר ב־SSH להתקני רשת ולשלוח פקודות CLI","w":["לבנות ממשק גרפי","לנתח JSON בלבד","להריץ שרת Web"],"e":"‏Netmiko מבוססת על Paramiko, ומטפלת ב־prompts של יצרנים שונים."},{"id":"N07.26","lv":"CCNP","t":"אוטומציה","q":"מה מאפיין את Cisco DNA Center (Catalyst Center)?","c":"בקר מרכזי לניהול, אוטומציה ו־Assurance של רשת הקמפוס, עם REST API צפוני","w":["נתב ליבה","Firewall","שרת DHCP"],"e":"זה הבקר של SD-Access. הוא מספק Intent-Based Networking, הקצאה אוטומטית וניתוח בעיות."},{"id":"N07.27","lv":"CCNP","t":"SD-WAN ו־SD-Access","q":"מה התפקיד של vSmart ב־Cisco SD-WAN?","c":"Control Plane – הפצת נתיבים ומדיניות לנתבי הקצה (OMP)","w":["Data Plane","ניהול גרפי","אימות ראשוני של התקנים"],"e":"‏vManage = ניהול, ‏vSmart = בקרה (OMP), ‏vBond = תזמור ואימות ראשוני, ‏vEdge/cEdge = העברת נתונים."},{"id":"N07.28","lv":"CCNP","t":"SD-WAN ו־SD-Access","q":"איזה פרוטוקול מפיץ נתיבים בין רכיבי Cisco SD-WAN?","c":"OMP – Overlay Management Protocol","w":["BGP בלבד","OSPF","EIGRP"],"e":"‏OMP רץ מעל חיבורי DTLS/TLS בין הנתבים לבין vSmart."},{"id":"N07.29","lv":"CCNP","t":"SD-WAN ו־SD-Access","q":"אילו טכנולוגיות מרכיבות את SD-Access?","c":"LISP ל־Control Plane, ‏VXLAN ל־Data Plane, ו־Cisco TrustSec (SGT) למדיניות","w":["OSPF, ‏GRE ו־ACL","STP, ‏VTP ו־DTP","BGP, ‏MPLS ו־LDP"],"e":"‏SGT (‏Scalable Group Tag) מאפשר מדיניות לפי זהות, ולא לפי כתובת IP."},{"id":"N07.30","lv":"CCNP","t":"SD-WAN ו־SD-Access","q":"מה תפקיד ה־Fabric Edge Node ב־SD-Access?","c":"מתג Access שמחבר את משתמשי הקצה ל־Fabric, ומשמש VTEP","w":["הבקר המרכזי","נקודת היציאה מה־Fabric","שרת DNS"],"e":"ה־Border Node מחבר לרשתות חיצוניות, וה־Control Plane Node מחזיק את מסד ה־LISP."},{"id":"N07.31","lv":"CCNP","t":"Wireless מתקדם","q":"מה ההבדל בין AP במצב Local לבין AP במצב FlexConnect?","c":"ב־FlexConnect אפשר להעביר תעבורה מקומית בסניף, ולהמשיך לעבוד גם כשהקישור ל־WLC נופל","w":["Local לא מתחבר ל־WLC","FlexConnect עובד בלי SSID","אין הבדל"],"e":"במצב Local כל התעבורה עוברת במנהרה ל־WLC. ‏FlexConnect מתאים לסניפים מרוחקים."},{"id":"N07.32","lv":"CCNP","t":"Wireless מתקדם","q":"מה מאפשר נדידה בשכבה 3 (Layer 3 Roaming) בין בקרים?","c":"שמירה על כתובת ה־IP של הלקוח כשהוא עובר ל־AP שמחובר לבקר אחר, בעזרת מנהרת Anchor/Foreign","w":["שינוי כתובת IP בכל מעבר","ניתוק מלא","מעבר ל־VLAN 1"],"e":"הבקר המקורי (Anchor) שומר את נקודת היציאה, והבקר החדש (Foreign) מעביר אליו את התעבורה במנהרה."},{"id":"N07.33","lv":"CCNP","t":"Wireless מתקדם","q":"מה תפקיד RRM בבקר אלחוטי?","c":"התאמה אוטומטית של ערוצים ועוצמת שידור של נקודות הגישה","w":["אימות משתמשים","הקצאת IP","הצפנה"],"e":"‏Radio Resource Management כולל DCA (בחירת ערוצים) ו־TPC (בקרת עוצמה)."},{"id":"N07.34","lv":"CCNP","t":"Wireless מתקדם","q":"מה זה RSSI ו־SNR?","c":"RSSI הוא עוצמת האות שנקלטת (dBm), ו־SNR הוא היחס בין האות לרעש (dB) – SNR גבוה טוב יותר","w":["שניהם מדדי הצפנה","RSSI הוא מהירות","SNR הוא מספר משתמשים"],"e":"למשל, ‎-65 dBm עם SNR של 25 dB נחשבים טובים לקול."},{"id":"N07.35","lv":"CCNP","t":"וירטואליזציה","q":"מה ההבדל בין Hypervisor מסוג 1 לבין Hypervisor מסוג 2?","c":"סוג 1 רץ ישירות על החומרה (Bare Metal), וסוג 2 רץ מעל מערכת הפעלה מארחת","w":["סוג 2 מהיר יותר","סוג 1 רק לשולחן עבודה","אין הבדל"],"e":"‏ESXi ו־Hyper-V Server הם מסוג 1. ‏VirtualBox ו־VMware Workstation הם מסוג 2."},{"id":"N07.36","lv":"CCNP","t":"וירטואליזציה","q":"מה ההבדל המרכזי בין מכונה וירטואלית לבין Container?","c":"Container חולק את הליבה של מערכת ההפעלה המארחת, ולכן קל ומהיר יותר מ־VM עם מערכת הפעלה מלאה","w":["Container כולל מערכת הפעלה מלאה","אין הבדל","VM קל יותר"],"e":"‏Docker ו־Kubernetes הם דוגמאות לעולם ה־Containers."},{"id":"N07.37","lv":"CCNP","t":"וירטואליזציה","q":"מה זה NFV?","c":"הרצת פונקציות רשת (נתב, Firewall, מאזן עומסים) כתוכנה על שרתים סטנדרטיים","w":["סוג סיב","פרוטוקול ניתוב","תקן PoE"],"e":"למשל, CSR1000v / Catalyst 8000V הם נתבים וירטואליים."},{"id":"N07.38","lv":"CCNP","t":"MPLS","q":"מה עושה LDP?","c":"מפיץ תוויות (Labels) בין נתבי MPLS","w":["מפיץ נתיבי IP","מאמת משתמשים","מסנכרן שעון"],"e":"‏LDP עובד ב־UDP/TCP 646. כל נתב מקצה תווית לכל קידומת, ומפרסם אותה לשכנים."},{"id":"N07.39","lv":"CCNP","t":"MPLS","q":"מה התפקיד של נתב PE ב־MPLS L3VPN?","c":"נתב קצה של הספק, שמחובר ללקוחות ומחזיק VRF לכל לקוח","w":["נתב ליבה שמעביר רק תוויות","הנתב של הלקוח","שרת DNS"],"e":"‏CE הוא הנתב של הלקוח, ‏PE הוא קצה הספק, ו־P הוא ליבת הספק. ‏PE מחליף נתיבי VPN עם PEs אחרים ב־MP-BGP."},{"id":"N07.40","lv":"CCNP","t":"MPLS","q":"מה מאפשר ה־Route Distinguisher ב־MPLS VPN?","c":"להבדיל בין קידומות חופפות של לקוחות שונים, כך שכל אחת תהיה ייחודית ב־MP-BGP","w":["לקבוע מדיניות ייבוא וייצוא","להצפין","לבחור DR"],"e":"‏RD יוצר קידומת VPNv4 ייחודית. ה־Route Target הוא שקובע לאיזה VRF הנתיב ייובא."},{"id":"N07.41","lv":"CCNP","t":"IPv6 מתקדם","q":"מה עושה RA Guard?","c":"חוסם הודעות Router Advertisement של IPv6 בפורטים שאין מאחוריהם נתב לגיטימי","w":["מגן על ARP","מאמת DHCPv4","מצפין IPv6"],"e":"זו המקבילה של DHCP Snooping לעולם ה־RA. היא מונעת מתקפת Rogue Router ב־IPv6."},{"id":"N07.42","lv":"CCNP","t":"IPv6 מתקדם","q":"מה תפקיד הודעת ICMPv6 Router Solicitation?","c":"מארח מבקש מהנתבים לשלוח מיד Router Advertisement","w":["נתב מבקש כתובת MAC","מארח מכריז על כתובתו","הודעת שגיאה"],"e":"‏RS נשלח ל־FF02::2 (כל הנתבים), והנתב עונה ב־RA עם Prefix ופרמטרים."},{"id":"N07.43","lv":"CCNP","t":"IPv6 מתקדם","q":"מה עושה DAD ב־IPv6?","c":"בודק שכתובת שהמארח רוצה להשתמש בה אינה בשימוש, בעזרת Neighbor Solicitation","w":["מקצה כתובת","מתרגם כתובת","מצפין"],"e":"‏Duplicate Address Detection פועל לפני שהכתובת הופכת פעילה, גם כשהכתובת נוצרה ב־SLAAC."},{"id":"N07.44","lv":"CCNP","t":"ארכיטקטורה","q":"מה ההבדל בין SaaS, ‏PaaS ו־IaaS?","c":"IaaS מספק תשתית (שרתים וירטואליים), ‏PaaS מספק פלטפורמה לפיתוח, ו־SaaS מספק אפליקציה מוכנה","w":["אין הבדל","SaaS מספק רק אחסון","IaaS מספק אפליקציות"],"e":"ככל שעולים בשכבות, הספק מנהל יותר רכיבים והלקוח פחות."},{"id":"N07.45","lv":"CCNP","t":"ארכיטקטורה","q":"מה ההבדל בין Underlay ל־Overlay?","c":"Underlay היא הרשת הפיזית בשכבה 3 שמעבירה חבילות, ו־Overlay היא רשת לוגית שנבנית מעליה במנהרות (VXLAN, ‏GRE)","w":["אין הבדל","Overlay היא הכבלים","Underlay היא רשת אלחוטית"],"e":"ב־SD-Access וב־SD-WAN, ה־Overlay מאפשר הפרדה ומדיניות בלי תלות בטופולוגיה הפיזית."},{"id":"N08.1","lv":"CCNA","t":"Subnetting ו־VLSM","q":"כמה כתובות שמישות יש ב־‎/29?","c":"6","w":["8","14","4"],"e":"ב־‎/29 נשארים 3 ביטי מארח: 2 בחזקת 3 פחות 2 = 6. ‏8 הוא גודל הבלוק כולו."},{"id":"N08.2","lv":"CCNA","t":"Subnetting ו־VLSM","q":"מהי כתובת הרשת של 192.168.10.200/28?","c":"192.168.10.192","w":["192.168.10.200","192.168.10.208","192.168.10.128"],"e":"גודל הבלוק הוא 16, והכפולות שלו הן 192 ו־208. ‏200 נמצא ביניהן, ולכן הרשת היא ‎.192."},{"id":"N08.3","lv":"CCNA","t":"Subnetting ו־VLSM","q":"מה ה־Broadcast של הרשת 10.0.8.0/22?","c":"10.0.11.255","w":["10.0.8.255","10.0.15.255","10.0.12.255"],"e":"‏‎/22 נותן בלוק של 4 באוקטט השלישי: ‏8, 9, 10, 11. הכתובת האחרונה היא 10.0.11.255."},{"id":"N08.4","lv":"CCNA","t":"IPv4","q":"איזו כתובת היא APIPA?","c":"169.254.12.7","w":["172.16.12.7","192.0.2.7","100.64.1.1"],"e":"‏169.254.0.0/16 היא הכתובת שמחשב נותן לעצמו כשלא קיבל תשובה מ־DHCP."},{"id":"N08.5","lv":"CCNA","t":"Cisco IOS","q":"איזה זיכרון מכיל את ה־startup-config?","c":"NVRAM","w":["RAM","Flash","ROM"],"e":"ה־startup-config נשמר ב־NVRAM, וה־running-config נמצא ב־RAM."},{"id":"N08.6","lv":"CCNA","t":"Cisco IOS","q":"מה עושה הפקודה copy running-config startup-config?","c":"שומרת את התצורה הפעילה כך שתישאר גם אחרי אתחול","w":["מוחקת את התצורה","טוענת את התצורה מה־NVRAM","מגבה לשרת TFTP"],"e":"בלי שמירה, כל שינוי אובד ב־reload."},{"id":"N08.7","lv":"CCNA","t":"STP","q":"כמה Root Ports יש ל־Root Bridge?","c":"אפס","w":["אחד","אחד לכל VLAN","כמספר הפורטים"],"e":"ה־Root Bridge לא צריך דרך לעצמו. כל הפורטים שלו הם Designated."},{"id":"N08.8","lv":"CCNA","t":"STP","q":"מה עלות ה־STP (Short) של פורט 100 Mbps?","c":"19","w":["4","100","2"],"e":"‏10M = 100, ‏100M = 19, ‏1G = 4, ‏10G = 2."},{"id":"N08.9","lv":"CCNA","t":"VLAN","q":"איזה טווח VLAN נקרא Extended Range?","c":"1006–4094","w":["1–1005","2–1001","4095–8191"],"e":"‏Extended Range נשמר ב־running-config ולא ב־vlan.dat."},{"id":"N08.10","lv":"CCNA","t":"ACL רגילה","q":"איזו פקודה מחילה ACL 10 על תעבורה שנכנסת לממשק?","c":"ip access-group 10 in","w":["access-class 10 in","ip access-list 10 in","apply acl 10 in"],"e":"‏ip access-group פועלת על ממשקים, ו־access-class פועלת על קווי VTY."},{"id":"N08.11","lv":"CCNA","t":"ACL מורחבת ו־PBR","q":"באיזה טווח מספרים נמצאות ACL מורחבות?","c":"100–199 ו־2000–2699","w":["1–99 ו־1300–1999","200–299","700–799"],"e":"‏1–99 הן Standard, ו־100–199 הן Extended. טווחי ה־1300 וה־2000 הם הרחבות."},{"id":"N08.12","lv":"CCNA","t":"DHCP","q":"מה עושה ip helper-address?","c":"מעביר הודעות Broadcast של DHCP כ־Unicast לשרת ברשת אחרת","w":["מגדיר Default Gateway","מפעיל שרת DHCP מקומי","חוסם DHCP"],"e":"הנתב הופך ל־Relay Agent, וממלא את השדה giaddr כדי שהשרת יבחר את ה־Pool המתאים."},{"id":"N08.13","lv":"CCNA","t":"Port Security","q":"מה ברירת המחדל של מספר כתובות ה־MAC המותרות ב־Port Security?","c":"1","w":["2","10","ללא הגבלה"],"e":"אחרי switchport port-security מותרת כתובת אחת, ומצב ההפרה הוא Shutdown."},{"id":"N08.14","lv":"CCNA","t":"Syslog","q":"לאיזו רמת חומרה שייכת ההודעה ‎%LINEPROTO-5-UPDOWN?","c":"5 – Notifications","w":["3 – Errors","4 – Warnings","6 – Informational"],"e":"המספר שבין המקפים הוא רמת החומרה."},{"id":"N08.15","lv":"CCNA","t":"OSPF","q":"מה ה־Wildcard שמפעיל OSPF רק בממשק עם הכתובת 10.1.1.1?","c":"network 10.1.1.1 0.0.0.0 area 0","w":["network 10.1.1.1 255.255.255.255 area 0","network 10.1.1.0 0.0.0.255 area 0","network 10.1.1.1 area 0"],"e":"‏Wildcard ‏0.0.0.0 מחייב התאמה מלאה של כל 32 הביטים, ולכן תופס ממשק אחד בלבד."},{"id":"N08.16","lv":"CCNA","t":"NAT","q":"איזו פקודה מסמנת ממשק כצד הפנימי של NAT?","c":"ip nat inside","w":["nat inside enable","ip nat source inside","ip inside nat"],"e":"חייבים לסמן גם ip nat outside בממשק החיצוני, אחרת לא יתבצע תרגום."},{"id":"N08.17","lv":"CCNP","t":"OSPF מרובה אזורים","q":"מה ה־Cost של נתיב מסכם שנוצר ב־area range, כברירת מחדל?","c":"ה־Cost הנמוך מבין הרשתות שהסיכום כולל (התנהגות ברירת המחדל ב־IOS)","w":["סכום כל העלויות","תמיד 1","110"],"e":"אפשר לקבוע עלות ידנית בעזרת cost בסוף הפקודה."},{"id":"N08.18","lv":"CCNP","t":"OSPF מרובה אזורים","q":"מה מסמן הקוד O N2 בטבלת הניתוב?","c":"נתיב חיצוני שנלמד מ־LSA מסוג 7 באזור NSSA, עם Metric קבוע","w":["נתיב בתוך האזור","נתיב Inter-Area","נתיב EIGRP"],"e":"‏N1 ו־N2 מקבילים ל־E1 ו־E2, אבל מגיעים מתוך NSSA."},{"id":"N08.19","lv":"CCNP","t":"EIGRP","q":"מה זה Stuck In Active (SIA)?","c":"מצב שבו נתב שלח Query ולא קיבל Reply בזמן, ולכן השכנות עם השכן שלא ענה מתאפסת","w":["נתיב שהוא תמיד פעיל","שכן שלא שולח Hello","נתיב חיצוני"],"e":"הפתרונות: Stub, סיכום וסינון – כדי לצמצם את היקף ה־Queries."},{"id":"N08.20","lv":"CCNP","t":"BGP","q":"איזה מאפיין BGP חובה שיופיע בכל עדכון (Well-known Mandatory)?","c":"AS_PATH, ‏NEXT_HOP ו־ORIGIN","w":["MED ו־Local Pref","Weight","Community"],"e":"‏Local Pref הוא Well-known Discretionary, ‏MED הוא Optional Non-transitive, ו־Weight הוא מאפיין של Cisco בלבד."},{"id":"N08.21","lv":"CCNP","t":"BGP","q":"מה עושה AS_PATH Prepending?","c":"מוסיף את ה־AS שלך כמה פעמים לנתיב שמפורסם, כדי שהנתיב ייראה ארוך ופחות מועדף לתעבורה נכנסת","w":["מקצר את הנתיב","מסנן נתיבים","משנה את ה־Weight"],"e":"‏AS_PATH קצר מועדף, ולכן Prepending מסיט תעבורה נכנסת לקישור אחר."},{"id":"N08.22","lv":"CCNP","t":"BGP","q":"מה עושה BGP Community no-export?","c":"אומר לשכן לא לפרסם את הנתיב מחוץ ל־AS שלו","w":["מוחק את הנתיב","משנה את ה־MED","מצפין"],"e":"‏Communities הן תגיות לנתיבים, שמאפשרות מדיניות מרחוק. ‏no-advertise חוסם פרסום לכל שכן."},{"id":"N08.23","lv":"CCNP","t":"STP מתקדם","q":"מה מבצעת הפקודה spanning-tree pathcost method long?","c":"מעבירה לשיטת העלויות של 802.1t, עם ערכים של 32 ביט שמבחינים בין ממשקים מהירים","w":["מאריכה את טיימר ה־Max Age","מבטלת את STP","משנה עדיפות"],"e":"בשיטה הזו ל־10G יש עלות 2000, ול־100G יש עלות 200."},{"id":"N08.24","lv":"CCNP","t":"EtherChannel","q":"איזה מצב PAgP יוזם משא ומתן?","c":"desirable","w":["auto","active","on"],"e":"ב־PAgP: ‏desirable יוזם ו־auto פסיבי. ‏active ו־passive הם של LACP."},{"id":"N08.25","lv":"CCNP","t":"FHRP","q":"מה כתובת ה־MAC הווירטואלית של VRRP, קבוצה 5?","c":"0000.5E00.0105","w":["0000.0C07.AC05","0007.B400.0501","FFFF.FFFF.0005"],"e":"‏VRRP משתמש ב־0000.5E00.01xx, כאשר xx הוא מספר הקבוצה (VRID)."},{"id":"N08.26","lv":"CCNP","t":"אבטחת שכבה 2","q":"איזה מנגנון מגן מפני שרת DHCPv6 זדוני?","c":"DHCPv6 Guard","w":["DHCP Snooping של IPv4","BPDU Guard","Port Fast"],"e":"‏DHCPv6 Guard חוסם הודעות שרת (Advertise ו־Reply) בפורטים שאין מאחוריהם שרת מורשה."},{"id":"N08.27","lv":"CCNP","t":"מנהרות ו־VPN","q":"איזה פורט UDP משמש IPsec כשיש NAT בדרך (NAT-T)?","c":"4500","w":["500","1701","1194"],"e":"‏IKE מתחיל ב־UDP 500. אם מזוהה NAT, המעבר הוא ל־4500, ו־ESP נעטף ב־UDP."},{"id":"N08.28","lv":"CCNP","t":"QoS","q":"מה ערך DSCP של AF41?","c":"34","w":["46","26","10"],"e":"‏AFxy = ‏8x + 2y, ולכן AF41 = ‏32 + 2 = ‏34. מקובל לווידאו אינטראקטיבי."},{"id":"N08.29","lv":"CCNP","t":"אוטומציה","q":"מהו סוג הנתונים ב־JSON עבור [\"Gi0/1\", \"Gi0/2\"]?","c":"מערך (Array) של מחרוזות","w":["אובייקט","מספר","בוליאני"],"e":"סוגריים מרובעים מסמנים מערך, וסוגריים מסולסלים מסמנים אובייקט."},{"id":"N08.30","lv":"CCNP","t":"אוטומציה","q":"איזה כלי מבוסס Agent ומשתמש במודל Pull עם קבצי Manifest?","c":"Puppet","w":["Ansible","Netmiko","Postman"],"e":"‏Puppet Agent מושך תצורה מה־Puppet Master. ‏Ansible דוחף (Push) בלי Agent."},{"id":"N08.31","lv":"CCNP","t":"Wireless מתקדם","q":"איזה תקן מאפשר מעבר מהיר בין נקודות גישה (Fast BSS Transition)?","c":"802.11r","w":["802.11k","802.11v","802.11w"],"e":"‏802.11r מקצר את זמן המעבר. ‏802.11k מספק דוחות על השכנים, ‏802.11v מאפשר ניהול BSS, ו־802.11w מגן על מסגרות ניהול."},{"id":"N08.32","lv":"CCNP","t":"ארכיטקטורה","q":"מה מאפשר ה־Fabric Border Node ב־SD-Access?","c":"חיבור ה־Fabric לרשתות חיצוניות, כמו מרכז הנתונים או האינטרנט","w":["חיבור משתמשי הקצה","ניהול גרפי","אחסון מסד ה־LISP בלבד"],"e":"ה־Border מתרגם בין המדיניות של ה־Fabric לבין העולם החיצוני."}];